    static func testUnchangedFTSRefresh() async throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let path = directory.appendingPathComponent("fts.sqlite3").path
        let db = DatabaseEngine(path: path)
        try await db.open()
        let first = FeedArticle(
            title: "Original research", link: "https://example.com/fts", guid: "fts",
            description: "Initial description", pubDate: Date(), source: "Publisher", fullContent: "Originalbodytoken")
        try await db.upsertArticles([first])
        var handle: OpaquePointer?
        assertEqual(sqlite3_open(path, &handle), SQLITE_OK, "Open isolated FTS observation")
        defer { sqlite3_close(handle) }
        assertEqual(
            sqlite3_create_function_v2(
                handle, "news_publisher_input", 3, SQLITE_UTF8 | SQLITE_DETERMINISTIC, nil, publisherInputFunction, nil,
                nil, nil), SQLITE_OK, "Register publisher hashing on the isolated FTS writer")
        func rowID() -> Int64 {
            var statement: OpaquePointer?
            assertEqual(
                sqlite3_prepare_v2(
                    handle, "SELECT rowid FROM articles_fts WHERE article_id='fts';", -1, &statement, nil), SQLITE_OK,
                "Observe FTS row")
            defer { sqlite3_finalize(statement) }
            assertEqual(sqlite3_step(statement), SQLITE_ROW, "FTS retains its row")
            return sqlite3_column_int64(statement, 0)
        }
        func indexData() -> String {
            var statement: OpaquePointer?
            assertEqual(
                sqlite3_prepare_v2(
                    handle,
                    "SELECT group_concat(id || ':' || hex(block), '|') FROM (SELECT id, block FROM articles_fts_data ORDER BY id);",
                    -1, &statement, nil), SQLITE_OK, "Observe FTS segments")
            defer { sqlite3_finalize(statement) }
            assertEqual(sqlite3_step(statement), SQLITE_ROW, "FTS has segment data")
            return String(cString: sqlite3_column_text(statement, 0))
        }
        // Segment data, unlike a durable row key, detects unnecessary delete/reindex work.
        let other = FeedArticle(
            title: "Other story", link: "https://example.com/other", guid: "other", description: "", pubDate: Date(),
            source: "Publisher")
        try await db.upsertArticles([other])
        let initialID = rowID()
        let initialIndex = indexData()
        try await db.upsertArticles([first])
        assertEqual(rowID(), initialID, "Identical refresh keeps the FTS key")
        assertEqual(indexData(), initialIndex, "Identical refresh does not delete/reinsert FTS")
        var metadata = first
        metadata.imageUrl = "https://example.com/new-photo.jpg"
        try await db.upsertArticles([metadata])
        assertEqual(rowID(), initialID, "Image-only metadata keeps the FTS key")
        assertEqual(indexData(), initialIndex, "Image-only metadata does not rebuild searchable text")
        assertEqual(
            sqlite3_exec(
                handle,
                "UPDATE articles SET title='Updated research', content=NULL, category='Science' WHERE id='fts';", nil,
                nil, nil), SQLITE_OK, "Change searchable fields including NULL")
        assertEqual(rowID(), initialID, "Changed searchable fields retain the durable FTS key")
        assertTrue(indexData() != initialIndex, "Changed searchable fields rebuild FTS")
        assertEqual(try await db.searchArticles(query: "Updated").count, 1, "Updated title is searchable")
        assertTrue(
            try await db.searchArticles(query: "Originalbodytoken").isEmpty, "Cleared NULL content removes old terms")
        assertEqual(try await db.searchArticles(query: "Science").count, 1, "Updated category is indexed")
        try await db.upsertArticles([
            FeedArticle(
                title: "Migration anchor", link: "https://example.com/anchor", guid: "anchor", description: "",
                pubDate: Date(), source: "Publisher")
        ])
        await db.close()
        assertEqual(
            sqlite3_exec(
                handle,
                "DROP TRIGGER trg_articles_au; CREATE TRIGGER trg_articles_au AFTER UPDATE ON articles BEGIN DELETE FROM articles_fts WHERE article_id=old.id; INSERT INTO articles_fts(article_id,title,description,content,source,category) VALUES(new.id,new.title,coalesce(new.description,''),coalesce(new.content,''),new.source,coalesce(new.category,'')); END; PRAGMA user_version=11;",
                nil, nil, nil), SQLITE_OK, "Reconstruct v11 trigger fixture")
        try await db.open()
        let migratedID = rowID()
        let migratedIndex = indexData()
        assertEqual(
            sqlite3_exec(handle, "UPDATE articles SET updated_at=updated_at+1 WHERE id='fts';", nil, nil, nil),
            SQLITE_OK, "Exercise migrated metadata update")
        assertEqual(rowID(), migratedID, "Existing v11 database receives a durable FTS key")
        assertEqual(indexData(), migratedIndex, "Existing v11 database receives the guarded trigger")
        assertEqual(try await db.searchArticles(query: "Updated").count, 1, "Migration preserves searchable rows")
        await db.close()
    }

    static func testSearchSpellingSuggestion() async throws {
        func scalars(_ text: String) -> [Unicode.Scalar] { Array(text.unicodeScalars) }
        assertEqual(SearchSpelling.distance(scalars("nvida"), scalars("nvidia")), 1, "One deletion is one edit")
        assertEqual(SearchSpelling.distance(scalars("teh"), scalars("the")), 1, "An adjacent swap is one edit")
        assertEqual(SearchSpelling.distance(scalars("kitten"), scalars("sitting")), 3, "Classic distance")
        let vocabulary = ["nvidia": 3, "chips": 2, "election": 4, "elections": 1, "artificial": 2, "2026": 5]
        func correction(_ term: String) -> String? { SearchSpelling.correction(for: term, in: vocabulary) }
        assertEqual(correction("nvida"), "nvidia", "A typo maps to the library word")
        assertEqual(correction("chps"), "chips", "Four characters allow one edit")
        assertEqual(correction("nvid"), nil, "A word's start is not a typo")
        assertEqual(correction("chp"), nil, "Under four characters is never changed")
        assertEqual(correction("electionz"), "election", "Ties go to the commoner word")
        assertEqual(correction("zebra"), nil, "Nothing close, no correction")
        assertEqual(correction("2027"), nil, "A number is never corrected to another number")
        assertEqual(
            SearchSpelling.corrected("Nvida \"artifical\" source:reuters", vocabulary: vocabulary),
            "nvidia artificial source:reuters", "Misspelled terms change; operators stay")
        assertEqual(SearchSpelling.corrected("nvidia chips", vocabulary: vocabulary), nil, "Known words, no suggestion")

        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let db = DatabaseEngine(path: directory.appendingPathComponent("spelling.sqlite3").path)
        try await db.open()
        try await db.upsertArticles([
            FeedArticle(
                title: "Nvidia unveils new chips", link: "https://example.com/nvidia", guid: "nvidia",
                description: "The chipmaker raised its forecast", pubDate: Date(), source: "Publisher")
        ])
        assertTrue(try await db.searchArticles(query: "nvida chips").isEmpty, "The typo finds nothing")
        assertEqual(
            try await db.searchSuggestion(query: "nvida chips"), "nvidia chips", "The suggestion fixes the typo")
        assertEqual(
            try await db.searchSuggestion(query: "nvidia tariffs"), nil, "A word with nothing close gets no suggestion")
        // A re-worded headline keeps the story count and rowid; the cached word list must still see the new words.
        try await db.upsertArticles([
            FeedArticle(
                title: "Nvidia unveils new processors", link: "https://example.com/nvidia", guid: "nvidia",
                description: "The chipmaker raised its forecast", pubDate: Date(), source: "Publisher")
        ])
        assertEqual(
            try await db.searchSuggestion(query: "procesors"), "processors", "An edited headline refreshes the words")
        await db.close()
    }

    static func testFTSRowIDMigration() async throws {
        print("  - Testing durable FTS keys, copied v14 migration, rollback, VACUUM and deletion...")
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-fts-keys-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let path = directory.appendingPathComponent("original.sqlite3").path
        let copy = directory.appendingPathComponent("copy.sqlite3").path
        func execute(_ file: String, _ sql: String) {
            var handle: OpaquePointer?
            assertEqual(sqlite3_open(file, &handle), SQLITE_OK, "Open isolated FTS fixture")
            defer { sqlite3_close(handle) }
            assertEqual(sqlite3_exec(handle, sql, nil, nil, nil), SQLITE_OK, "Prepare FTS fixture")
        }
        func value(_ file: String, _ sql: String) -> String? {
            var handle: OpaquePointer?
            var statement: OpaquePointer?
            assertEqual(sqlite3_open(file, &handle), SQLITE_OK, "Inspect isolated FTS fixture")
            defer { sqlite3_close(handle) }
            assertEqual(sqlite3_prepare_v2(handle, sql, -1, &statement, nil), SQLITE_OK, "Prepare FTS inspection")
            defer { sqlite3_finalize(statement) }
            guard sqlite3_step(statement) == SQLITE_ROW else { return nil }
            return sqlite3_column_text(statement, 0).map { String(cString: $0) }
        }
        let seed = DatabaseEngine(path: path)
        try await seed.open()
        let now = Date()
        let articles = ["one", "two", "three"].map { (id: String) in
            FeedArticle(
                storedID: id, title: "Research evidence \(id)", link: "https://example.com/fts-keys/\(id)",
                guid: id, description: "Independent report", pubDate: now, source: "Publisher \(id)")
        }
        try await seed.upsertArticles(articles)
        try await seed.markRead(articleId: "one", isRead: true)
        try await seed.setSaved(articleId: "two", isSaved: true)
        let event = try await seed.createEvent(memberArticleIDs: ["one", "two"], at: now)
        let originalOrder = try await seed.searchArticles(query: "Research").map(\.id)
        await seed.close()
        // Restore the actual v14 derived index and triggers; its rowids need not equal article rowids.
        execute(
            path,
            """
            DROP TRIGGER trg_articles_ai; DROP TRIGGER trg_articles_ad; DROP TRIGGER trg_articles_au;
            DROP TABLE articles_fts; DROP TABLE article_fts_rows;
            CREATE VIRTUAL TABLE articles_fts USING fts5(article_id UNINDEXED,title,description,content,source,category,tokenize='porter unicode61');
            INSERT INTO articles_fts(article_id,title,description,content,source,category)
            SELECT id,title,coalesce(description,''),coalesce(content,''),source,coalesce(category,'') FROM articles ORDER BY id DESC;
            CREATE TRIGGER trg_articles_ai AFTER INSERT ON articles BEGIN
                INSERT INTO articles_fts(article_id,title,description,content,source,category)
                VALUES(new.id,new.title,coalesce(new.description,''),coalesce(new.content,''),new.source,coalesce(new.category,''));
            END;
            CREATE TRIGGER trg_articles_ad AFTER DELETE ON articles BEGIN
                DELETE FROM articles_fts WHERE article_id=old.id;
            END;
            CREATE TRIGGER trg_articles_au AFTER UPDATE ON articles
            WHEN old.title IS NOT new.title OR old.description IS NOT new.description OR old.content IS NOT new.content
              OR old.source IS NOT new.source OR old.category IS NOT new.category
            BEGIN
                DELETE FROM articles_fts WHERE article_id=old.id;
                INSERT INTO articles_fts(article_id,title,description,content,source,category)
                VALUES(new.id,new.title,coalesce(new.description,''),coalesce(new.content,''),new.source,coalesce(new.category,''));
            END;
            PRAGMA user_version=14;
            """)
        let readAt = value(path, "SELECT read_at FROM article_state WHERE article_id='one';")
        let savedAt = value(path, "SELECT saved_at FROM article_state WHERE article_id='two';")
        try FileManager.default.copyItem(atPath: path, toPath: copy)
        let cancelledDB = DatabaseEngine(path: copy)
        let cancelled = Task {
            withUnsafeCurrentTask { $0?.cancel() }
            try await cancelledDB.open()
        }
        do {
            try await cancelled.value
            assertTrue(false, "Cancelled FTS migration must throw")
        } catch is CancellationError {}
        assertEqual(value(copy, "PRAGMA user_version;"), "14", "Cancellation keeps the old version")
        assertEqual(value(copy, "SELECT count(*) FROM articles_fts;"), "3", "Cancellation preserves the old FTS index")

        // Fail after the old FTS table has been dropped, exercising transactional DDL rollback.
        execute(copy, "CREATE VIEW article_fts_rows AS SELECT 1;")
        let db = DatabaseEngine(path: copy)
        do {
            try await db.open()
            assertTrue(false, "Injected migration failure must throw")
        } catch {}
        assertEqual(value(copy, "PRAGMA user_version;"), "14", "Failed rebuild keeps the old version")
        assertEqual(
            value(copy, "SELECT count(*) FROM articles_fts WHERE articles_fts MATCH 'Research';"), "3",
            "Failed rebuild restores the old searchable index")
        assertEqual(
            value(
                copy,
                "SELECT count(*) FROM sqlite_master WHERE name IN ('trg_articles_ai','trg_articles_ad','trg_articles_au');"
            ), "3", "Failed rebuild restores the old triggers")
        execute(copy, "DROP VIEW article_fts_rows;")
        try await db.open()
        assertEqual(
            value(copy, "PRAGMA user_version;"), "29", "Copied v14 library upgrades through v15 to the current schema")
        assertEqual(
            value(copy, "SELECT count(*) FROM articles WHERE category IS NOT NULL;"), "0",
            "A library from before v22 keeps none of the classifier labels v22 wrote into the publisher column (#817)")
        assertEqual(
            value(
                copy,
                "SELECT count(*) FROM articles a WHERE NOT EXISTS (SELECT 1 FROM article_enrichment ae WHERE ae.article_id = a.id AND ae.category IS NOT NULL);"
            ), "0", "Every article from before v22 keeps a classifier category in article_enrichment (#817)")
        assertEqual(value(path, "PRAGMA user_version;"), "14", "Original library stays untouched")
        assertEqual(
            try await db.searchArticles(query: "Research").map(\.id), originalOrder,
            "Migration preserves ranks and ID tie order")
        assertEqual(
            value(copy, "SELECT read_at FROM article_state WHERE article_id='one';"), readAt,
            "Migration preserves read timestamps")
        assertEqual(
            value(copy, "SELECT saved_at FROM article_state WHERE article_id='two';"), savedAt,
            "Migration preserves saved timestamps")
        assertEqual(
            try await db.fetchEvent(id: event.id)?.memberArticleIDs.count, 2, "Migration preserves event membership")
        let key = value(copy, "SELECT fts_rowid FROM article_fts_rows WHERE article_id='one';")
        await db.close()
        // Explicitly relocate an article's hidden rowid: the mapping must use its durable ID.
        execute(copy, "UPDATE articles SET rowid=rowid+100 WHERE id='one'; VACUUM;")
        try await db.open()
        assertEqual(
            value(copy, "SELECT fts_rowid FROM article_fts_rows WHERE article_id='one';"), key,
            "Durable FTS key survives rowid relocation and VACUUM")
        assertEqual(
            try await db.searchArticles(query: "Research").map(\.id), originalOrder,
            "Search still joins the correct publications")
        let candidates = try await db.eventCandidateRows(
            matching: "Research", around: now, window: 48 * 3600,
            activeSince: now.addingTimeInterval(-72 * 3600), excluding: "one", limit: 10)
        assertEqual(Set(candidates.map(\.id)), ["two", "three"], "Candidate joins survive VACUUM")
        await db.close()
        execute(copy, "PRAGMA foreign_keys=ON; DELETE FROM articles WHERE id='three';")
        assertEqual(value(copy, "SELECT count(*) FROM article_fts_rows;"), "2", "Deletion removes the mapping")
        assertEqual(
            value(copy, "SELECT count(*) FROM articles_fts WHERE article_id='three';"), "0",
            "Deletion removes FTS postings")
        execute(copy, "BEGIN; DELETE FROM articles WHERE id='one'; ROLLBACK;")
        assertEqual(
            value(copy, "SELECT fts_rowid FROM article_fts_rows WHERE article_id='one';"), key,
            "Rolled-back deletion restores the mapping")
        assertEqual(
            value(copy, "SELECT count(*) FROM articles_fts WHERE article_id='one';"), "1",
            "Rolled-back deletion restores FTS")
        assertEqual(value(copy, "PRAGMA quick_check;"), "ok", "Migrated database passes quick_check")
        assertEqual(value(copy, "PRAGMA foreign_key_check;"), nil, "Migrated database has no dangling references")
        execute(copy, "INSERT INTO articles_fts(articles_fts) VALUES('integrity-check');")
    }

    @MainActor
    static func testDatabaseHealthAndDerivedRetention() async throws {
        print(
            "  - Testing database health (v26 auto_vacuum, quick_check, checkpoint, derived retention) (#536, #537)...")
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-db-health-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }

        func value(_ file: String, _ sql: String) -> String? {
            var handle: OpaquePointer?
            var statement: OpaquePointer?
            assertEqual(sqlite3_open(file, &handle), SQLITE_OK, "Open SQLite file for inspection")
            defer { sqlite3_close(handle) }
            guard sqlite3_prepare_v2(handle, sql, -1, &statement, nil) == SQLITE_OK else { return nil }
            defer { sqlite3_finalize(statement) }
            guard sqlite3_step(statement) == SQLITE_ROW else { return nil }
            return sqlite3_column_text(statement, 0).map { String(cString: $0) }
        }

        // 1. Fresh DB starts at v26 with incremental auto_vacuum (2), and shrinks after pruneOldArticles (#536).
        let shrinkPath = directory.appendingPathComponent("shrink.sqlite3").path
        let shrinkDB = DatabaseEngine(path: shrinkPath)
        try await shrinkDB.open()
        assertEqual(value(shrinkPath, "PRAGMA user_version;"), "29", "New database opens at schema v29")
        assertEqual(value(shrinkPath, "PRAGMA auto_vacuum;"), "2", "New database uses incremental auto_vacuum (2)")

        let now = Date(timeIntervalSince1970: 1_800_000_000)
        let expiredDate = now.addingTimeInterval(-45 * 86_400)
        let paddingBody = String(repeating: "Detailed archival paragraph text for vacuum verification. ", count: 120)
        let bulkyArticles = (0..<250).map { idx in
            FeedArticle(
                storedID: "bulky-\(idx)",
                title: "Bulky archival report \(idx)",
                link: "https://example.com/bulky/\(idx)",
                guid: "bulky-\(idx)",
                description: "Archival summary \(idx)",
                pubDate: expiredDate,
                source: "Archival Press",
                fullContent: paddingBody
            )
        }
        try await shrinkDB.upsertArticles(bulkyArticles)
        // A feed item, identified by its feed-scoped GUID, that the feed keeps serving after it is pruned (#783).
        let servedFeed = "https://example.com/archive.xml"
        let served = FeedArticle(
            title: "Still served report", link: "https://example.com/served/report", guid: "served-guid",
            description: "Served long after reading", pubDate: expiredDate, source: "Archival Press")
        let servedID = try await shrinkDB.upsertArticles([served], feedUrl: servedFeed)
        try await shrinkDB.markReadBatch(articleIds: bulkyArticles.map(\.id) + Array(servedID), isRead: true)
        await shrinkDB.checkpointAndOptimize()
        let sizeBeforePrune =
            (try? FileManager.default.attributesOfItem(atPath: shrinkPath)[.size] as? Int64) ?? 0
        let prunedCount = try await shrinkDB.pruneOldArticles(keepReadDays: 30, now: now)
        assertEqual(prunedCount, 251, "Prunes all 251 expired read articles")
        assertTrue(
            try await shrinkDB.upsertArticles([served], feedUrl: servedFeed).isEmpty,
            "A pruned story its feed still serves is not stored again as new (#783)")
        assertTrue(
            try await shrinkDB.upsertArticles([bulkyArticles[0]]).isEmpty,
            "A pruned story keeps its stored ID's tombstone")
        assertTrue(try await shrinkDB.fetchArticles(limit: 10).isEmpty, "Pruned stories stay out of every list")
        let sameAddress = FeedArticle(
            title: "Next edition", link: served.link, guid: "served-guid-2", description: "A new edition",
            pubDate: now, source: "Archival Press")
        assertEqual(
            try await shrinkDB.upsertArticles([sameAddress], feedUrl: servedFeed).count, 1,
            "A new story at a pruned story's address still arrives")
        try await shrinkDB.upsertArticles([bulkyArticles[1]], preservingStoredContent: true)
        assertTrue(
            try await shrinkDB.fetchArticles(limit: 10).contains { $0.id == bulkyArticles[1].id },
            "Saving a pruned story explicitly stores it again")
        await shrinkDB.checkpointAndOptimize()
        await shrinkDB.close()
        let sizeAfterPrune =
            (try? FileManager.default.attributesOfItem(atPath: shrinkPath)[.size] as? Int64) ?? 0
        assertTrue(
            sizeAfterPrune < sizeBeforePrune,
            "Incremental vacuum + checkpoint shrinks the SQLite file on disk (\(sizeBeforePrune) -> \(sizeAfterPrune))"
        )

        // 2. Derived intelligence row retention (#537):
        //    - 40-day-old singleton's pair_assessments, article_features, and article_embeddings are removed on prune.
        //    - Event member's features and embeddings stay even when older than 72h.
        //    - Re-clustering recomputes features deterministically if needed.
        let retentionPath = directory.appendingPathComponent("derived-retention.sqlite3").path
        let retentionDB = DatabaseEngine(path: retentionPath)
        try await retentionDB.open()
        let singletonOld = FeedArticle(
            storedID: "singleton-40d",
            title: "Central Bank Holds Rates Steady in Frankfurt Meeting",
            link: "https://example.com/singleton-40d",
            guid: "singleton-40d",
            description: "Policymakers left benchmark interest rates unchanged on Thursday.",
            pubDate: now.addingTimeInterval(-40 * 86_400),
            source: "Finance Wire"
        )
        let eventMemberA = FeedArticle(
            storedID: "event-member-a",
            title: "Volcano Erupts Near Reykjanes Peninsula in Iceland",
            link: "https://example.com/event-member-a",
            guid: "event-member-a",
            description: "Lava fountains opened along a four-kilometer fissure overnight.",
            pubDate: now.addingTimeInterval(-10 * 86_400),
            source: "Nordic News"
        )
        let eventMemberB = FeedArticle(
            storedID: "event-member-b",
            title: "Iceland Evacuates Grindavik After New Volcanic Fissure Opens",
            link: "https://example.com/event-member-b",
            guid: "event-member-b",
            description: "Emergency crews evacuated residents near the Reykjanes eruption.",
            pubDate: now.addingTimeInterval(-10 * 86_400 + 600),
            source: "Atlantic Dispatch"
        )
        try await retentionDB.upsertArticles([singletonOld, eventMemberA, eventMemberB])
        _ = try await retentionDB.createEvent(
            memberArticleIDs: [eventMemberA.id, eventMemberB.id], at: now.addingTimeInterval(-10 * 86_400))

        let singletonFeatures = EventFeatures(
            title: singletonOld.title, description: singletonOld.description, date: singletonOld.pubDate)
        let memberFeatures = EventFeatures(
            title: eventMemberA.title, description: eventMemberA.description, date: eventMemberA.pubDate)
        try await retentionDB.upsertArticleFeatures(
            [singletonOld.id: singletonFeatures, eventMemberA.id: memberFeatures],
            version: EventFeatures.storageVersion,
            at: now.addingTimeInterval(-40 * 86_400)
        )
        let syntheticVector = Array(repeating: Float(0.1), count: 384)
        try await retentionDB.upsertArticleEmbeddings(
            [singletonOld.id: syntheticVector, eventMemberA.id: syntheticVector],
            modelVersion: SentenceEmbedder.modelVersion
        )
        try await retentionDB.upsertPairDecisions(
            [
                DatabaseEngine.PairDecision(
                    articleID: eventMemberA.id,
                    otherArticleID: singletonOld.id,
                    decision: "borderline",
                    reason: "test-old-pair",
                    score: 0.42
                )
            ],
            matcherVersion: EventMatcher.version,
            at: now.addingTimeInterval(-40 * 86_400)
        )
        try await retentionDB.upsertPairDecisions(
            [
                DatabaseEngine.PairDecision(
                    articleID: eventMemberA.id,
                    otherArticleID: eventMemberB.id,
                    decision: "match",
                    reason: "test-recent-pair",
                    score: 0.88
                )
            ],
            matcherVersion: EventMatcher.version,
            at: now.addingTimeInterval(-5 * 86_400)
        )

        _ = try await retentionDB.pruneOldArticles(keepReadDays: 30, now: now)
        let remainingFeatures = try await retentionDB.fetchArticleFeatures(
            articleIDs: [singletonOld.id, eventMemberA.id], version: EventFeatures.storageVersion)
        assertTrue(
            remainingFeatures[singletonOld.id] == nil,
            "40-day-old singleton's article_features row is pruned (#537)"
        )
        assertEqual(
            remainingFeatures[eventMemberA.id], memberFeatures,
            "Event member's article_features row is retained outside 72h window (#537)"
        )
        let remainingEmbeddings = try await retentionDB.fetchArticleEmbeddings(
            articleIDs: [singletonOld.id, eventMemberA.id], modelVersion: SentenceEmbedder.modelVersion)
        assertTrue(
            remainingEmbeddings[singletonOld.id] == nil,
            "40-day-old singleton's article_embeddings row is pruned (#537)"
        )
        assertTrue(
            remainingEmbeddings[eventMemberA.id] != nil,
            "Event member's article_embeddings row is retained (#537)"
        )
        await retentionDB.close()
        assertEqual(
            value(retentionPath, "SELECT count(*) FROM pair_assessments;"), "1",
            "Pair assessment older than 30 days is pruned while recent pair assessment stays (#537)"
        )
        let recomputedFeatures = EventFeatures(
            title: singletonOld.title, description: singletonOld.description, date: singletonOld.pubDate)
        assertEqual(
            recomputedFeatures, singletonFeatures,
            "Recomputing pruned EventFeatures produces identical deterministic signals (#537)"
        )

        // 3. Corrupted SQLite fixture surfaces databaseHealthNotice without crashing (#536).
        let corruptPath = directory.appendingPathComponent("corrupt.sqlite3").path
        try Data("not a valid sqlite3 header at all - corrupted payload bytes".utf8).write(
            to: URL(fileURLWithPath: corruptPath))
        let corruptDB = DatabaseEngine(path: corruptPath)
        let corruptStore = ArticleStore(database: corruptDB)
        await corruptStore.initialize()
        assertTrue(
            corruptStore.databaseHealthNotice != nil,
            "Corrupted database surfaces a user-visible health notice on ArticleStore (#536)"
        )
        await corruptDB.close()
    }

    @MainActor
    static func testReadOnlyLibraryRefresh() async throws {
        print("  - Testing a read-only library skips scheduled refreshes and explains a manual one (#787)...")
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-readonly-refresh-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let path = directory.appendingPathComponent("library.sqlite3").path
        try Data("not a valid sqlite3 header at all - corrupted payload bytes".utf8).write(
            to: URL(fileURLWithPath: path))
        let engine = DatabaseEngine(path: path)
        let store = ArticleStore(database: engine)
        await store.initialize()
        assertTrue(store.databaseHealthNotice != nil, "The damaged library opens read-only with a notice")

        let suite = testDefaultsSuite("test.readonly.refresh")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        _ = settings.addFeed(url: "https://example.com/readonly.xml")
        let fetches = TestRecorder()
        let manager = FeedManager(
            settings: settings, store: store, schedulesRefresh: false,
            fetchBatch: { urls, _ in
                await fetches.record(urls)
                return urls.map { ($0, [], nil, nil) }
            })
        defer { manager.stopBackgroundWork() }

        // The store's own startup task can still report that the library could not be loaded; let it finish first.
        try await Task.sleep(for: .milliseconds(300))
        store.operationError = nil
        await manager.fetchFeedsAsync(scheduled: true)
        assertEqual(await fetches.batches.count, 0, "A scheduled refresh downloads nothing while read-only")
        assertTrue(store.operationError == nil, "A scheduled refresh raises no alert while read-only")

        await manager.fetchFeedsAsync()
        assertEqual(await fetches.batches.count, 0, "A manual refresh downloads nothing while read-only")
        assertTrue(
            store.operationError?.contains("read-only") == true
                && store.operationError?.contains(store.databaseHealthNotice ?? "?") == true,
            "A manual refresh says why, with the library's own notice")
        await engine.close()
    }

    static func testLibraryBackupAndFutureSchemaGuard() async throws {
        print("  - Testing the pre-migration backup and the newer-library guard (#746, #747)...")
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-backup-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        func value(_ file: URL, _ sql: String) -> String? {
            var handle: OpaquePointer?
            var statement: OpaquePointer?
            assertEqual(
                sqlite3_open_v2(file.path, &handle, SQLITE_OPEN_READONLY, nil), SQLITE_OK, "Inspect backup fixture")
            defer { sqlite3_close(handle) }
            guard sqlite3_prepare_v2(handle, sql, -1, &statement, nil) == SQLITE_OK else { return nil }
            defer { sqlite3_finalize(statement) }
            guard sqlite3_step(statement) == SQLITE_ROW else { return nil }
            return sqlite3_column_text(statement, 0).map { String(cString: $0) }
        }
        func files(_ prefix: String) throws -> [String] {
            try FileManager.default.contentsOfDirectory(atPath: directory.path).filter { $0.hasPrefix(prefix) }.sorted()
        }
        let current = String(DatabaseEngine.schemaVersion)
        let library = directory.appendingPathComponent("news.sqlite3")
        let creator = DatabaseEngine(path: library.path)
        try await creator.open()
        try await creator.upsertArticles(
            ["a", "b", "c"].map { name in
                FeedArticle(
                    storedID: "backup-\(name)", title: "Backup report \(name)",
                    link: "https://backup.test/\(name)", guid: "backup-guid-\(name)",
                    description: "Backup body \(name)", pubDate: Date(), source: "Backup Publisher")
            })
        await creator.close()
        assertEqual(value(library, "PRAGMA user_version;"), current, "A fresh library is written at schemaVersion")
        assertEqual(try files("news-before-"), [], "A fresh library is never backed up")
        var handle: OpaquePointer?
        assertEqual(sqlite3_open(library.path, &handle), SQLITE_OK, "Open v25 backup fixture")
        assertEqual(
            sqlite3_exec(
                handle,
                "DROP INDEX idx_events_story; ALTER TABLE events DROP COLUMN story_id; PRAGMA user_version = 25;",
                nil, nil, nil), SQLITE_OK, "Reconstruct a v25 library")
        sqlite3_close(handle)

        // A backup that cannot be written leaves the library unmigrated and read-only.
        var holder: OpaquePointer?
        assertEqual(sqlite3_open(library.path, &holder), SQLITE_OK, "Hold the v25 fixture's WAL files open")
        assertEqual(
            sqlite3_exec(holder, "SELECT count(*) FROM articles;", nil, nil, nil), SQLITE_OK, "Read v25 fixture")
        try FileManager.default.setAttributes([.posixPermissions: 0o555], ofItemAtPath: directory.path)
        let blocked = DatabaseEngine(path: library.path)
        try await blocked.open()
        let blockedNotice = await blocked.databaseHealthNotice()
        await blocked.close()
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: directory.path)
        sqlite3_close(holder)
        assertTrue(blockedNotice?.contains("couldn't back up") == true, "A failed backup surfaces the health notice")
        assertEqual(value(library, "PRAGMA user_version;"), "25", "A failed backup stops the migration")

        // Two engines opening one v25 library together: one backup, one migration, no error.
        let race = directory.appendingPathComponent("race", isDirectory: true)
        try FileManager.default.createDirectory(at: race, withIntermediateDirectories: true)
        let raceLibrary = race.appendingPathComponent("news.sqlite3")
        try FileManager.default.copyItem(at: library, to: raceLibrary)
        let racers = [DatabaseEngine(path: raceLibrary.path), DatabaseEngine(path: raceLibrary.path)]
        try await withThrowingTaskGroup(of: Void.self) { group in
            for racer in racers { group.addTask { try await racer.open() } }
            try await group.waitForAll()
        }
        for racer in racers {
            let raceNotice = await racer.databaseHealthNotice()
            assertEqual(raceNotice, nil, "Both concurrent opens end writable")
            await racer.close()
        }
        assertEqual(value(raceLibrary, "PRAGMA user_version;"), current, "Concurrent opens migrate the library once")
        assertEqual(
            try FileManager.default.contentsOfDirectory(atPath: race.path).filter { $0.hasPrefix("news-before-") }
                .count,
            1, "Concurrent opens back the library up once")

        // Two older copies exist; the migration keeps the newer one and its own.
        for (name, age) in [
            ("news-before-v20-2026-01-01.sqlite3", 200.0), ("news-before-v21-2026-02-01.sqlite3", 100.0),
        ] {
            let url = directory.appendingPathComponent(name)
            try Data("old copy".utf8).write(to: url)
            try FileManager.default.setAttributes(
                [.modificationDate: Date().addingTimeInterval(-age * 86400)], ofItemAtPath: url.path)
        }
        try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: library.path)
        let db = DatabaseEngine(path: library.path)
        try await db.open()
        let notice = await db.databaseHealthNotice()
        assertEqual(notice, nil, "A backed-up migration opens writable without a notice")
        assertEqual(value(library, "PRAGMA user_version;"), current, "The v25 library migrates to schemaVersion")
        assertEqual(try await db.fetchArticles(limit: nil).count, 3, "The migration keeps every article")
        // A write waits for another connection's lock instead of failing busy.
        var locker: OpaquePointer?
        assertEqual(sqlite3_open(library.path, &locker), SQLITE_OK, "Open a second connection")
        assertEqual(
            sqlite3_exec(locker, "BEGIN IMMEDIATE;", nil, nil, nil), SQLITE_OK, "A second connection takes the lock")
        nonisolated(unsafe) let held = locker
        // The lock stays held for a second, far longer than the write takes to reach SQLite; without the busy
        // timeout the write fails at once instead of waiting.
        let lockedAt = Date()
        DispatchQueue.global().asyncAfter(deadline: .now() + 1) {
            sqlite3_exec(held, "COMMIT;", nil, nil, nil)
            sqlite3_close(held)
        }
        try await db.markRead(articleId: "backup-a", isRead: true)
        let waited = Date().timeIntervalSince(lockedAt)
        assertTrue(waited >= 0.9, "A write waits for another connection's lock (waited \(waited) s)")
        assertTrue(try await db.isRead(articleId: "backup-a"), "A write waits out another connection's lock")
        await db.close()
        let backups = try files("news-before-")
        let day = Date().formatted(Date.ISO8601FormatStyle(timeZone: .current).year().month().day())
        let backup = "news-before-v25-\(day).sqlite3"
        assertEqual(backups, ["news-before-v21-2026-02-01.sqlite3", backup], "Only the newest two backups are kept")
        let backupURL = directory.appendingPathComponent(backup)
        let backupMode = try FileManager.default.attributesOfItem(atPath: backupURL.path)[.posixPermissions] as? Int
        assertEqual(backupMode, 0o600, "The backup keeps the library's file permissions")
        assertEqual(value(backupURL, "PRAGMA user_version;"), "25", "The backup keeps the old schema version")
        assertEqual(value(backupURL, "SELECT count(*) FROM articles;"), "3", "The backup keeps every article")
        assertEqual(value(backupURL, "PRAGMA quick_check;"), "ok", "The backup is a sound database")
        assertEqual(try files(".news-before-"), [], "No partial backup is left behind")

        let reopened = DatabaseEngine(path: library.path)
        try await reopened.open()
        await reopened.close()
        assertEqual(try files("news-before-"), backups, "A current library opens without a new backup")

        // A library from a newer build opens read-only and stays byte-identical.
        let future = directory.appendingPathComponent("future.sqlite3")
        try FileManager.default.copyItem(at: library, to: future)
        assertEqual(sqlite3_open(future.path, &handle), SQLITE_OK, "Open future fixture")
        assertEqual(
            sqlite3_exec(handle, "PRAGMA user_version = \(DatabaseEngine.schemaVersion + 1);", nil, nil, nil),
            SQLITE_OK, "Reconstruct a library from a newer build")
        sqlite3_close(handle)
        let futureBytes = try Data(contentsOf: future)
        let sideFile = URL(fileURLWithPath: future.path + ".world-tension-v2.json")
        try Data("[]".utf8).write(to: sideFile)
        let newer = DatabaseEngine(path: future.path)
        try await newer.open()
        let futureNotice = await newer.databaseHealthNotice()
        assertTrue(futureNotice?.contains("newer version") == true, "A newer library surfaces the health notice")
        assertEqual(try await newer.fetchArticles(limit: nil).count, 3, "A newer library stays readable")
        do {
            try await newer.markRead(articleId: "backup-a", isRead: true)
            assertTrue(false, "A newer library refuses writes")
        } catch {}
        let reading = WorldTensionReading(
            evaluatedAt: Date(), inputHash: "", modelGeneration: "", headlines: [],
            assessment: WorldTensionAssessment(score: 1, summary: "", reasons: []))
        for (name, write) in [
            ("saving a World Tension reading", { _ = try await newer.saveWorldTensionReading(reading) }),
            ("clearing enrichment", { try await newer.clearArticleEnrichment() }),
            ("clearing the database cache", { try await newer.clearAllDatabaseCache() }),
        ] as [(String, () async throws -> Void)] {
            do {
                try await write()
                assertTrue(false, "A newer library refuses \(name)")
            } catch let error as CocoaError {
                assertEqual(error.code, .fileWriteVolumeReadOnly, "A newer library refuses \(name) as read-only")
            } catch {
                assertTrue(false, "A newer library refuses \(name) as read-only, not with \(error)")
            }
        }
        assertEqual(try Data(contentsOf: sideFile), Data("[]".utf8), "A newer library's side files stay untouched")
        await newer.close()
        assertEqual(try Data(contentsOf: future), futureBytes, "A newer library is never migrated or written")
        assertEqual(try files("future-before-"), [], "A newer library is never backed up")
    }

    @MainActor
    static func testLibraryBackupRestore() async throws {
        print("  - Testing library backup and restore (#563)...")
        let fileManager = FileManager.default
        let directory = fileManager.temporaryDirectory.appendingPathComponent("news-restore-\(UUID().uuidString)")
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
        let suite = testDefaultsSuite("test.backup")
        let defaults = UserDefaults(suiteName: suite)!
        defer {
            removeTestDefaults(suite)
            try? fileManager.removeItem(at: directory)
        }
        func article(_ name: String) -> FeedArticle {
            FeedArticle(
                storedID: "restore-\(name)", title: "Restore report \(name)", link: "https://restore.test/\(name)",
                guid: "restore-guid-\(name)", description: "Restore body \(name)", pubDate: Date(),
                source: "Restore Publisher")
        }
        let library = directory.appendingPathComponent("news.sqlite3")
        let sideFile = URL(fileURLWithPath: library.path + ".world-tension-v2.json")
        let db = DatabaseEngine(path: library.path)
        try await db.open()
        try await db.upsertArticles([article("a"), article("b")])
        try await db.markRead(articleId: "restore-a", isRead: true)
        try await db.setSaved(articleId: "restore-b", isSaved: true)
        try Data("[\"before\"]".utf8).write(to: sideFile)
        defaults.set(["https://restore.test/feed"], forKey: AppSettings.feedURLsKey)
        defaults.set(["Tech"], forKey: AppSettings.userSectionsKey)
        defaults.set(["muted.test"], forKey: AppSettings.mutedSourcesKey)
        defaults.set(["https://restore.test/feed"], forKey: AppSettings.starredFeedURLsKey)
        defaults.set(["https://restore.test/feed": 1_700_000_000.0], forKey: AppSettings.starredFeedTimesKey)
        defaults.set(AppSettings.NotificationMode.minimal.rawValue, forKey: AppSettings.notificationModeKey)

        let archive = directory.appendingPathComponent("News Backup.sqlite3")
        try Data("an older file the reader chose to replace".utf8).write(to: archive)
        try await db.writeBackup(to: archive, settings: AppSettings.backupSettings(from: defaults))
        func permissions(_ file: URL) throws -> Int? {
            try fileManager.attributesOfItem(atPath: file.path)[.posixPermissions] as? Int
        }
        assertEqual(try permissions(archive), 0o600, "A backup is readable by its owner only")
        func value(_ file: URL, _ sql: String) -> String? {
            var handle: OpaquePointer?
            var statement: OpaquePointer?
            defer { sqlite3_close(handle) }
            guard sqlite3_open_v2(file.path, &handle, SQLITE_OPEN_READONLY, nil) == SQLITE_OK,
                sqlite3_prepare_v2(handle, sql, -1, &statement, nil) == SQLITE_OK
            else { return nil }
            defer { sqlite3_finalize(statement) }
            guard sqlite3_step(statement) == SQLITE_ROW else { return nil }
            return sqlite3_column_text(statement, 0).map { String(cString: $0) }
        }

        // A backup is never written over the live library, its WAL files, or a link to the library.
        let link = directory.appendingPathComponent("link.sqlite3")
        try fileManager.createSymbolicLink(at: link, withDestinationURL: library)
        for destination in [library, URL(fileURLWithPath: library.path + "-wal"), link] {
            do {
                try await db.writeBackup(to: destination, settings: Data())
                assertTrue(false, "A backup over the library itself is refused (\(destination.lastPathComponent))")
            } catch {
                assertTrue(
                    error.localizedDescription.contains("library itself"),
                    "A backup over the library is refused with a plain message (\(destination.lastPathComponent))")
            }
        }
        try fileManager.removeItem(at: link)
        assertEqual(try await db.fetchArticles(limit: nil).count, 2, "A refused destination leaves the library intact")
        // A hard link is checked on a closed library: SQLite fails writes on an open file that gains a second link.
        let closedLibrary = directory.appendingPathComponent("closed.sqlite3")
        try fileManager.copyItem(at: archive, to: closedLibrary)
        let hardLink = directory.appendingPathComponent("hard-link.sqlite3")
        try fileManager.linkItem(at: closedLibrary, to: hardLink)
        do {
            try await DatabaseEngine(path: closedLibrary.path).writeBackup(to: hardLink, settings: Data())
            assertTrue(false, "A backup over a hard link to the library is refused")
        } catch {
            assertTrue(error.localizedDescription.contains("library itself"), "A hard link to the library is refused")
        }
        for file in [hardLink, closedLibrary] { try fileManager.removeItem(at: file) }

        // Everything changes after the backup.
        try await db.upsertArticles([article("c")])
        try await db.markRead(articleId: "restore-a", isRead: false)
        try await db.markRead(articleId: "restore-b", isRead: true)
        try await db.setSaved(articleId: "restore-b", isSaved: false)
        try Data("[\"after\"]".utf8).write(to: sideFile)
        defaults.set(["https://other.test/feed"], forKey: AppSettings.feedURLsKey)
        defaults.removeObject(forKey: AppSettings.userSectionsKey)
        defaults.set(true, forKey: AppSettings.allowInsecureHTTPKey)
        defaults.set(AppSettings.NotificationMode.full.rawValue, forKey: AppSettings.notificationModeKey)

        // A damaged file, a foreign file with an articles table this build can't migrate, and a backup from a newer build
        // are refused; the live library stays open and unchanged.
        let foreign = directory.appendingPathComponent("foreign.sqlite3")
        var handle: OpaquePointer?
        assertEqual(sqlite3_open(foreign.path, &handle), SQLITE_OK, "Create the foreign fixture")
        assertEqual(
            sqlite3_exec(handle, "CREATE TABLE articles (headline TEXT);", nil, nil, nil), SQLITE_OK,
            "Give the foreign fixture an articles table with other columns")
        sqlite3_close(handle)
        let corrupt = directory.appendingPathComponent("corrupt.sqlite3")
        try Data(repeating: 0x5A, count: 8192).write(to: corrupt)
        // A real SQLite file with a valid header and a damaged b-tree: the articles table's root page header is
        // overwritten, so the file opens but fails integrity_check.
        let damagedPages = directory.appendingPathComponent("damaged-pages.sqlite3")
        var pages = try Data(contentsOf: archive)
        let rawPageSize = Int(pages[16]) << 8 | Int(pages[17])
        let pageSize = rawPageSize == 1 ? 65_536 : rawPageSize
        let root = Int(value(archive, "SELECT rootpage FROM sqlite_master WHERE name = 'articles';") ?? "") ?? 0
        assertTrue(root > 1, "The archive's articles table has a root page past the header")
        let offset = (root - 1) * pageSize
        pages.replaceSubrange(offset..<(offset + 12), with: Data(repeating: 0xFF, count: 12))
        try pages.write(to: damagedPages)
        assertTrue(
            value(damagedPages, "SELECT count(*) FROM sqlite_master;") != nil,
            "The damaged-page fixture still opens as SQLite")
        assertTrue(
            value(damagedPages, "PRAGMA integrity_check(1);") != "ok", "The damaged-page fixture fails integrity_check")
        let newer = directory.appendingPathComponent("newer.sqlite3")
        try fileManager.copyItem(at: archive, to: newer)
        assertEqual(sqlite3_open(newer.path, &handle), SQLITE_OK, "Open the newer-backup fixture")
        assertEqual(
            sqlite3_exec(handle, "PRAGMA user_version = \(DatabaseEngine.schemaVersion + 1);", nil, nil, nil),
            SQLITE_OK, "Mark the fixture as saved by a newer build")
        sqlite3_close(handle)
        for (name, file, message) in [
            ("damaged", corrupt, "damaged"), ("damaged-page", damagedPages, "damaged"), ("foreign", foreign, "damaged"),
            ("newer", newer, "newer version"),
        ] {
            do {
                _ = try await db.restoreBackup(from: file)
                assertTrue(false, "A \(name) backup is refused")
            } catch {
                assertTrue(
                    error.localizedDescription.contains(message), "A \(name) backup is refused with a plain message")
            }
            assertEqual(
                try await db.fetchArticles(limit: nil).count, 3, "A refused \(name) backup leaves the library open")
        }
        assertTrue(try await db.isRead(articleId: "restore-b"), "A refused backup leaves read state alone")
        assertEqual(
            try Data(contentsOf: sideFile), Data("[\"after\"]".utf8), "A refused backup leaves side files alone")
        assertEqual(defaults.stringArray(forKey: AppSettings.feedURLsKey), ["https://other.test/feed"], "Settings kept")

        // A side file that can't be written stops the restore before the swap: the library stays open and unchanged.
        try fileManager.removeItem(at: sideFile)
        try fileManager.createDirectory(at: sideFile, withIntermediateDirectories: false)
        do {
            _ = try await db.restoreBackup(from: archive)
            assertTrue(false, "A restore whose side file can't be written fails")
        } catch {}
        assertEqual(try await db.fetchArticles(limit: nil).count, 3, "A failed side file leaves the library in place")
        try fileManager.removeItem(at: sideFile)
        try Data("[\"after\"]".utf8).write(to: sideFile)
        func keptCopies() throws -> [String] {
            try fileManager.contentsOfDirectory(atPath: directory.path).filter {
                $0.contains(".restoring") || ($0.hasPrefix("news-before-restore-") && $0.hasSuffix(".sqlite3"))
            }.sorted()
        }
        // The failed attempt's own kept copy is set aside so the pruning below starts from known copies.
        for name in try keptCopies() { try fileManager.removeItem(at: directory.appendingPathComponent(name)) }

        // The restore swaps the backup in, closes the library and hands back the settings. Two older copies of replaced libraries exist; the restore keeps the newer one and its own.
        for (name, age) in [
            ("news-before-restore-2026-01-01.sqlite3", 200.0), ("news-before-restore-2026-02-01.sqlite3", 100.0),
        ] {
            let url = directory.appendingPathComponent(name)
            try Data("old copy".utf8).write(to: url)
            try fileManager.setAttributes(
                [.modificationDate: Date().addingTimeInterval(-age * 86400)], ofItemAtPath: url.path)
        }
        let settings = try await db.restoreBackup(from: archive)
        try AppSettings.restoreSettings(settings ?? Data(), to: defaults)
        let afterFirst = try keptCopies()
        assertEqual(afterFirst.count, 2, "A restore keeps the replaced library and prunes to the newest two copies")
        assertEqual(afterFirst.first, "news-before-restore-2026-02-01.sqlite3", "Pruning keeps the newer old copy")
        let kept = directory.appendingPathComponent(afterFirst.last ?? "")
        let day = Date().formatted(Date.ISO8601FormatStyle(timeZone: .current).year().month().day())
        assertTrue(kept.lastPathComponent.hasPrefix("news-before-restore-\(day)-"), "The kept copy is time-stamped")
        assertEqual(try permissions(kept), 0o600, "The kept library is readable by its owner only")
        let undo = DatabaseEngine(path: kept.path)
        try await undo.open()
        assertEqual(
            try await undo.fetchArticles(limit: nil).count, 3, "The kept copy holds the replaced library, for undo")
        assertTrue(try await undo.isRead(articleId: "restore-b"), "The kept copy holds the replaced read state")
        await undo.close()
        let restored = DatabaseEngine(path: library.path)
        try await restored.open()
        let notice = await restored.databaseHealthNotice()
        assertEqual(notice, nil, "A restored library opens writable")
        assertEqual(
            Set(try await restored.fetchArticles(limit: nil).map(\.id)), ["restore-a", "restore-b"],
            "The restore brings back the backed-up stories")
        assertTrue(try await restored.isRead(articleId: "restore-a"), "The restore brings back read state")
        assertTrue(!(try await restored.isRead(articleId: "restore-b")), "The restore brings back unread state")
        assertTrue(try await restored.isSaved(articleId: "restore-b"), "The restore brings back saved state")
        await restored.close()
        assertEqual(try Data(contentsOf: sideFile), Data("[\"before\"]".utf8), "The restore brings back World Tension")
        assertEqual(sqlite3_open_v2(library.path, &handle, SQLITE_OPEN_READONLY, nil), SQLITE_OK, "Inspect restore")
        assertEqual(
            sqlite3_exec(handle, "SELECT * FROM \(DatabaseEngine.backupExtrasTable);", nil, nil, nil) == SQLITE_OK,
            false, "The restored library doesn't keep the backup's extras table")
        sqlite3_close(handle)
        let reloaded = AppSettings(defaults: defaults)
        assertEqual(reloaded.feedURLs, ["https://restore.test/feed"], "The restore brings back subscriptions")
        assertEqual(reloaded.userSections, ["Tech"], "The restore brings back sections")
        assertEqual(reloaded.muteRules.sources, ["muted.test"], "The restore brings back mute rules")
        assertEqual(reloaded.starredFeedURLs, ["https://restore.test/feed"], "The restore brings back starred feeds")
        assertEqual(reloaded.notificationMode, .minimal, "The restore brings back the notification mode")
        assertEqual(reloaded.allowInsecureHTTP, false, "A setting the backup lacked returns to its default")

        // A second restore the same day keeps its own copy beside the first one instead of replacing it.
        try await Task.sleep(nanoseconds: 1_100_000_000)
        let again = DatabaseEngine(path: library.path)
        try await again.open()
        _ = try await again.restoreBackup(from: archive)
        let afterSecond = try keptCopies()
        assertEqual(afterSecond.count, 2, "Two restores in one day keep two copies")
        assertTrue(afterSecond.contains(kept.lastPathComponent), "The second restore keeps the first restore's copy")
        assertEqual(
            value(kept, "SELECT count(*) FROM articles;"), "3", "The first copy still holds the original library")
        let second = directory.appendingPathComponent(afterSecond.first { $0 != kept.lastPathComponent } ?? "")
        assertEqual(value(second, "SELECT count(*) FROM articles;"), "2", "The second copy holds the restored library")
    }

    static func testRealLibraryMigrationFixture() async throws {
        print("  - Testing real-library v14 migration fixture in CI (#539)...")
        let fixtureSource = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
            .appendingPathComponent("Tests/Fixtures/legacy-library-v14.sqlite3")
        assertTrue(
            FileManager.default.fileExists(atPath: fixtureSource.path),
            "Sanitized legacy library fixture must exist at Tests/Fixtures/legacy-library-v14.sqlite3"
        )
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-real-fixture-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }

        let workingCopy = directory.appendingPathComponent("library.sqlite3")
        try FileManager.default.copyItem(at: fixtureSource, to: workingCopy)

        func value(_ file: String, _ sql: String) -> String? {
            var handle: OpaquePointer?
            var statement: OpaquePointer?
            assertEqual(sqlite3_open(file, &handle), SQLITE_OK, "Open migrated fixture for inspection")
            defer { sqlite3_close(handle) }
            guard sqlite3_prepare_v2(handle, sql, -1, &statement, nil) == SQLITE_OK else { return nil }
            defer { sqlite3_finalize(statement) }
            guard sqlite3_step(statement) == SQLITE_ROW else { return nil }
            return sqlite3_column_text(statement, 0).map { String(cString: $0) }
        }

        assertEqual(value(workingCopy.path, "PRAGMA user_version;"), "14", "Fixture starts at schema v14")
        let db = DatabaseEngine(path: workingCopy.path)
        try await db.open()
        assertEqual(
            value(workingCopy.path, "PRAGMA user_version;"), "29",
            "Fixture migrates cleanly to current schema v26 (#539)"
        )
        assertEqual(
            value(workingCopy.path, "PRAGMA auto_vacuum;"), "2",
            "Migrated fixture enables incremental auto_vacuum (#536)"
        )
        assertEqual(
            value(workingCopy.path, "PRAGMA quick_check;"), "ok",
            "Migrated fixture passes PRAGMA quick_check (#539)"
        )
        assertEqual(
            value(workingCopy.path, "PRAGMA foreign_key_check;"), nil,
            "Migrated fixture passes PRAGMA foreign_key_check (#539)"
        )

        let counts = try await db.counts()
        assertEqual(counts.total, 200, "Migrated fixture preserves all 200 articles")
        assertEqual(counts.unread, 150, "Migrated fixture preserves unread count (150)")
        assertEqual(counts.saved, 20, "Migrated fixture preserves saved count (20)")

        let fetched = try await db.fetchArticles(limit: 500)
        assertEqual(fetched.count, 200, "fetchArticles(limit: 500) returns all 200 migrated stories")
        let searchResults = try await db.searchArticles(query: "Observatory", limit: 500)
        assertEqual(searchResults.count, 200, "Migrated FTS5 index searches all 200 stories")
        let event = try await db.fetchEvent(id: "legacy-event-00")
        assertEqual(event?.memberArticleIDs.count, 3, "Migrated fixture preserves event memberships")
        await db.close()
    }

    /// Writes a new 10,000-story library for `script/launch_baseline.sh`: unread, recent and already clustered,
    /// so launch measures loading a steady-state archive rather than a first-run clustering backlog.
    static func seedLaunchLibrary(path: String) async throws {
        guard !FileManager.default.fileExists(atPath: path) else {
            throw StoryCorpus.Failure.invalid("Refusing to overwrite \(path)")
        }
        let db = DatabaseEngine(path: path)
        try await db.open()
        let now = Date()
        let prose = (1...20).map {
            "Researchers in London compared observation \($0) with the published evidence and documented the results."
        }.joined(separator: " ")
        let archive = (0..<10_000).map { index in
            FeedArticle(
                title: "Research report \(index)", link: "https://launch.invalid/article/\(index)",
                guid: "launch-\(index)",
                description: "Research evidence", pubDate: now.addingTimeInterval(-Double(index) * 15),
                source: "Publisher \(index % 20)", fullContent: prose,
                readerDocument: ReaderDocument(blocks: [ReaderBlock(kind: .paragraph, text: prose)]))
        }
        try await db.upsertArticles(archive, feedUrl: "https://launch.invalid/feed.xml")
        try await db.markEventMatchProcessed(archive.map(\.id), matcherVersion: EventMatcher.version, at: now)
        await db.close()
        print("Seeded \(archive.count) stories at \(path)")
    }

    /// Writes the sentence embedding of every authored-corpus article to `embedding-vectors.json` (#540), so a change
    /// to `SentenceEmbedder` can be compared vector by vector with the implementation before it.
    static func exportEmbeddingVectors(output: String) async throws {
        struct Item: Decodable { let id: String, title: String, description: String? }
        struct Fixture: Decodable { let articles: [Item] }
        let fixture = try JSONDecoder().decode(
            Fixture.self,
            from: Data(contentsOf: URL(fileURLWithPath: "Tests/Fixtures/story-corpus/matcher-regressions-v1.json")))
        let texts = fixture.articles.map {
            EventFeatures.matchingText(title: $0.title, description: $0.description ?? "")
        }
        let start = ProcessInfo.processInfo.systemUptime
        let vectors = await SentenceEmbedder.shared.embedBatch(texts)
        let elapsed = ProcessInfo.processInfo.systemUptime - start
        var byID: [String: [Float]] = [:]
        for (item, vector) in zip(fixture.articles, vectors) {
            guard let vector else { throw StoryCorpus.Failure.invalid("No embedding for \(item.id); nothing written") }
            byID[item.id] = vector
        }
        let file = try StoryCorpus.privateDirectory(output).appendingPathComponent("embedding-vectors.json")
        let data = try JSONSerialization.data(
            withJSONObject: byID.mapValues { $0.map(Double.init) }, options: [.sortedKeys])
        // An existing dump is the reference of a comparison, so it is never overwritten; use another directory.
        try StoryCorpus.writePrivate(data, to: file, replacing: false)
        print(
            String(
                format: "    embedded %d of %d texts in %.0f ms -> %@", byID.count, texts.count, elapsed * 1000,
                file.path))
    }

    /// Opt-in controlled service timings; not a rendered UI or network benchmark.
    @MainActor
    static func runPerformanceBaseline() async throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-baseline-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let suite = testDefaultsSuite("test.performance")
        let defaults = UserDefaults(suiteName: suite)!
        defer {
            removeTestDefaults(suite)
            try? FileManager.default.removeItem(at: directory)
        }
        let settings = AppSettings(defaults: defaults)
        settings.aiEnabled = false
        settings.notificationsEnabled = false
        settings.feedURLs = (0..<5).map { "https://baseline.example/feed-\($0)" }
        let db = DatabaseEngine(path: directory.appendingPathComponent("library.sqlite3").path)
        let store = ArticleStore(database: db)
        await store.initialize()
        let prose = (1...20).map {
            "Researchers in London compared observation \($0) with the published evidence and documented the results."
        }.joined(separator: " ")
        func article(_ index: Int) -> FeedArticle {
            let image = "https://baseline.example/media/publisher-\(index % 20).jpg"
            let document = ReaderDocument(
                blocks: [ReaderBlock(kind: .paragraph, text: prose)],
                images: [ReaderImageCandidate(url: image, origin: .body, width: 1200, height: 800)], leadImageURL: image
            )
            return FeedArticle(
                title: "Research report \(index)", link: "https://baseline.example/article/\(index)",
                guid: "baseline-\(index)", description: "Research evidence",
                pubDate: Date(timeIntervalSince1970: 1_800_000_000 + Double(index)),
                source: "Publisher \(index % 20)", imageUrl: image, fullContent: prose, readerDocument: document)
        }
        let archive = (0..<10_000).map(article)
        try await db.upsertArticles(archive)
        let clusterNow = Date(timeIntervalSince1970: 1_800_010_250)
        // Steady-state archive, rather than a first-launch clustering backlog competing with refresh.
        try await db.markEventMatchProcessed(archive.map(\.id), matcherVersion: EventMatcher.version, at: clusterNow)
        var measurements = [String: [Double]]()
        func record(_ name: String, from start: Double) {
            measurements[name, default: []].append((ProcessInfo.processInfo.systemUptime - start) * 1000)
        }
        let coldStart = ProcessInfo.processInfo.systemUptime
        assertTrue(await store.refreshState(), "Baseline snapshot hydrates")
        record("snapshot_first_500_ms", from: coldStart)
        assertEqual(store.articles.count, 500, "Baseline keeps the real snapshot limit")
        let batches = (0..<5).map { offset in (0..<50).map { article(10_000 + offset * 50 + $0) } }
        let manager = FeedManager(
            settings: settings, store: store, schedulesRefresh: false,
            fetchBatch: { urls, _ in
                zip(urls, batches).map { ($0.0, $0.1, nil, nil) }
            })
        for _ in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            await manager.fetchFeedsAsync()
            record("refresh_5_mocked_feeds_ms", from: start)
            assertEqual(manager.articles.count, 500, "Refresh publishes the bounded snapshot")
            await manager.waitForEventClustering()
        }
        assertEqual(try await db.counts().total, 10_250, "Repeated refreshes keep one row per document")
        manager.stopBackgroundWork()

        // Paired query comparison on one database/index; alternate order to avoid warm-cache bias.
        var comparisonHandle: OpaquePointer?
        assertEqual(
            sqlite3_open_v2(
                directory.appendingPathComponent("library.sqlite3").path, &comparisonHandle,
                SQLITE_OPEN_READONLY | SQLITE_OPEN_FULLMUTEX, nil), SQLITE_OK, "Open isolated candidate comparison")
        defer { sqlite3_close(comparisonHandle) }
        let probe = archive[9_800]
        let candidateQuery = "{title description} : (\"research\" OR \"report\")"
        func legacyCandidateRows() -> [[String?]] {
            let sql = """
                SELECT a.id, a.title, coalesce(a.description, ''), m.event_id
                FROM articles_fts fts JOIN articles a ON a.id = fts.article_id
                LEFT JOIN event_members m ON m.article_id = a.id
                LEFT JOIN events e ON e.id = m.event_id
                WHERE articles_fts MATCH ? AND a.id != ?
                    AND CASE WHEN a.published_at = \(DateParser.unknownDate.timeIntervalSince1970)
                        THEN a.created_at ELSE a.published_at END BETWEEN ? AND ?
                    AND NOT EXISTS (SELECT 1 FROM article_reconciliations r WHERE r.duplicate_id = a.id)
                    AND (m.event_id IS NULL OR e.updated_at >= ?)
                ORDER BY fts.rank, a.id LIMIT 80;
                """
            var statement: OpaquePointer?
            assertEqual(
                sqlite3_prepare_v2(comparisonHandle, sql, -1, &statement, nil), SQLITE_OK,
                "Prepare legacy candidate comparison")
            defer { sqlite3_finalize(statement) }
            let transient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)
            sqlite3_bind_text(statement, 1, candidateQuery, -1, transient)
            sqlite3_bind_text(statement, 2, probe.id, -1, transient)
            sqlite3_bind_double(statement, 3, probe.pubDate.timeIntervalSince1970 - 48 * 3600)
            sqlite3_bind_double(statement, 4, probe.pubDate.timeIntervalSince1970 + 48 * 3600)
            sqlite3_bind_double(statement, 5, clusterNow.timeIntervalSince1970 - 72 * 3600)
            var rows: [[String?]] = []
            var status = sqlite3_step(statement)
            while status == SQLITE_ROW {
                rows.append((0..<4).map { sqlite3_column_text(statement, Int32($0)).map { String(cString: $0) } })
                status = sqlite3_step(statement)
            }
            assertEqual(status, SQLITE_DONE, "Legacy candidate comparison completes")
            return rows
        }
        let expectedCandidates = legacyCandidateRows()
        assertEqual(expectedCandidates.count, 80, "Paired comparison returns the full candidate cap")
        func measureLegacy() {
            let start = ProcessInfo.processInfo.systemUptime
            let rows = legacyCandidateRows()
            record("event_candidate_legacy_join_ms", from: start)
            assertEqual(rows, expectedCandidates, "Legacy candidate comparison stays deterministic")
        }
        func measureMapped() async throws {
            let start = ProcessInfo.processInfo.systemUptime
            let rows = try await db.eventCandidateRows(
                matching: candidateQuery, around: probe.pubDate,
                window: 48 * 3600, activeSince: clusterNow.addingTimeInterval(-72 * 3600), excluding: probe.id,
                limit: 80)
            record("event_candidate_rowid_join_ms", from: start)
            assertEqual(
                rows.map { [$0.id, $0.title, $0.description, $0.eventID] }, expectedCandidates,
                "Durable rowid join preserves all ordered candidate fields")
        }
        for iteration in 0..<10 {
            if iteration.isMultiple(of: 2) {
                measureLegacy()
                try await measureMapped()
            } else {
                try await measureMapped()
                measureLegacy()
            }
        }
        for _ in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            let rows = try await db.searchArticles(query: "Research", limit: 100)
            record("fts_first_100_ms", from: start)
            assertEqual(rows.count, 100, "FTS benchmark returns expected rows")
        }
        let html =
            "<article><h2>Evidence</h2><p>\(prose)</p><figure><img src='/photo.jpg' width='1200' height='800'></figure><p>\(prose)</p></article>"
        for _ in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            assertTrue(
                ContentExtractionPipeline.shared.extractFromHTML(html, baseUrl: "https://baseline.example/story")
                    .isSuccess, "Benchmark extraction succeeds")
            record("html_extraction_ms", from: start)
            let analysisStart = ProcessInfo.processInfo.systemUptime
            let analysis = try await ArticleAnalyzer.shared.analyze(
                title: "Research evidence", content: prose, allowFoundationModels: false)
            record("natural_language_analysis_ms", from: analysisStart)
            assertFalse(analysis.summary.isEmpty, "Deterministic analysis returns publisher-derived text")
        }

        // Event clustering & feed grouping (#104, #153). Unchanged archives must do no matching work.
        try await db.markEventMatchProcessed(
            batches.flatMap { $0 }.map(\.id), matcherVersion: EventMatcher.version, at: clusterNow)
        for _ in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            let report = try await EventClusterer.run(in: db, now: clusterNow)
            record("event_clustering_unchanged_ms", from: start)
            assertEqual(report.processed, 0, "Unchanged refresh does not recompute the archive")
        }
        // Reset the same 200 rows for each dense candidate pass: equal work, not successive backlog slices.
        let denseIDs = archive.suffix(200).map(\.id)
        var processedRows: [Int] = []
        for _ in 0..<5 {
            try await db.markEventMatchProcessed(denseIDs, matcherVersion: 0, at: clusterNow)
            let start = ProcessInfo.processInfo.systemUptime
            let report = try await EventClusterer.run(in: db, now: clusterNow, limit: 200)
            record("event_clustering_dense_200_ms", from: start)
            processedRows.append(report.processed)
            assertEqual(report.processed, 200, "Each dense pass processes exactly the reset rows")
            assertTrue(
                try await db.pendingEventMatchRows(
                    activeSince: clusterNow.addingTimeInterval(-72 * 3600),
                    matcherVersion: EventMatcher.version, limit: 1
                ).isEmpty, "Dense pass drains its bounded work")
        }
        let snapshotArticles = Array(store.articles.prefix(500))
        let snapshotIDs = snapshotArticles.map(\.id)
        for _ in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            let summaries = try await store.eventFeedSummaries(for: snapshotIDs)
            let entries = EventFeedGrouping.entries(for: snapshotArticles, events: summaries, mode: .events)
            record("event_feed_grouping_ms", from: start)
            assertFalse(entries.isEmpty, "Grouped feed entries are not empty")
        }

        // Overview generation & cached lookup (#104, #153)
        let eventArticles = Array(archive.prefix(3))
        let queue = EnrichmentQueue(store: store)
        let coordinator = OverviewGenerationCoordinator(store: store, queue: queue)
        for i in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            let doc = await coordinator.requestOverview(
                eventID: "bench-event-\(i)",
                eventTitle: "Research report on observation",
                membershipVersion: 1,
                articles: eventArticles,
                priority: .visibleEvent
            )
            record("overview_generation_ms", from: start)
            assertTrue(doc != nil, "Benchmark overview generation succeeds")
        }
        for _ in 0..<10 {
            let start = ProcessInfo.processInfo.systemUptime
            let cached = try await store.fetchEventOverview(eventID: "bench-event-0")
            record("overview_cached_ms", from: start)
            assertTrue(cached != nil, "Cached overview lookup succeeds")
        }
        for _ in 0..<10 {
            let entered = TestCounter()
            let cancelledManager = FeedManager(
                settings: settings, store: store, schedulesRefresh: false,
                fetchBatch: { _, _ in
                    await entered.increment()
                    do { try await Task.sleep(nanoseconds: 60_000_000_000) } catch {}
                    return []
                })
            let refresh = Task { await cancelledManager.fetchFeedsAsync() }
            while await entered.value == 0 { await Task.yield() }
            let start = ProcessInfo.processInfo.systemUptime
            cancelledManager.stopBackgroundWork()
            await refresh.value
            record("refresh_cancel_mock_wait_ms", from: start)
        }
        // Embedding throughput (#540): a fresh embedder, model load included, over 2,000 archive texts.
        if await SentenceEmbedder.shared.isAvailable {
            let texts = archive.prefix(2_000).map {
                EventFeatures.matchingText(title: $0.title, description: $0.description)
            }
            let start = ProcessInfo.processInfo.systemUptime
            let vectors = await SentenceEmbedder().embedBatch(texts)
            record("embedding_cold_2000_ms", from: start)
            guard vectors.allSatisfy({ $0 != nil }) else { fatalError("Every archive text embeds") }
        }
        var usage = rusage()
        guard getrusage(RUSAGE_SELF, &usage) == 0 else { fatalError("Cannot obtain process memory high-water mark") }
        let report: [String: Any] = [
            "library_rows": 10_250, "publishers": 20, "snapshot_rows": 500,
            "feed_count": 5, "fresh_rows_per_feed": 50, "prose_characters": prose.count, "html_characters": html.count,
            "dense_clustering_processed_rows": processedRows,
            "candidate_comparison_rows": expectedCandidates.count,
            "sqlite_version": String(cString: sqlite3_libversion()),
            "peak_process_rss_bytes": usage.ru_maxrss, "measurements_ms": measurements,
            "os": ProcessInfo.processInfo.operatingSystemVersionString,
            "cpu_count": ProcessInfo.processInfo.processorCount,
            "physical_memory_bytes": ProcessInfo.processInfo.physicalMemory,
            "optimization": "-O (test.sh performance mode)",
        ]
        let data = try JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys])
        print("PERFORMANCE_BASELINE_JSON_BEGIN")
        print(String(decoding: data, as: UTF8.self))
        print("PERFORMANCE_BASELINE_JSON_END")
        await db.close()
    }

    @MainActor
    static func testReaderStoreUpdates() async {
        let suiteName = testDefaultsSuite("test.reader")
        let defaults = UserDefaults(suiteName: suiteName)!
        defer { removeTestDefaults(suiteName) }
        let store = ArticleStore(database: DatabaseEngine(path: ":memory:"))
        await store.initialize()
        let manager = FeedManager(settings: AppSettings(defaults: defaults), store: store, schedulesRefresh: false)
        let article = FeedArticle(
            title: "Report", link: "https://example.com/report", guid: "reader-test", description: "Preview",
            pubDate: Date(), source: "Publisher")
        await store.batchUpsert(articles: [article])
        await store.updateEnrichment(id: article.id, category: "Science", content: "The complete publisher article.")
        assertEqual(
            manager.articles.first?.fullContent, "The complete publisher article.",
            "Feed views receive extracted text immediately")
        assertEqual(
            manager.articles.first?.category, "Science", "Category changes propagate without another feed refresh")
        let classifiedRevision = store.revision
        var publications = 0
        let observation = store.$articles.dropFirst().sink { _ in publications += 1 }
        assertTrue(
            await store.updateEnrichment(id: article.id, category: "Science"), "Repeated classification persists")
        assertEqual(store.revision, classifiedRevision, "Unchanged enrichment does not invalidate feed or reader")
        assertEqual(publications, 0, "Unchanged enrichment does not republish the article collection")
        await store.updateEnrichment(id: article.id, category: "World")
        assertEqual(store.revision, classifiedRevision + 1, "A changed classification still invalidates queries")
        assertEqual(publications, 1, "A changed classification publishes once")
        observation.cancel()

        // Background classification publishes a burst together, with the latest state of every story (#778).
        let burst = (0..<5).map { index in
            FeedArticle(
                title: "Burst \(index)", link: "https://example.com/burst-\(index)", guid: "burst-\(index)",
                description: "Preview", pubDate: Date(), source: "Publisher")
        }
        await store.batchUpsert(articles: burst)
        let burstRevision = store.revision
        var burstPublications = 0
        let burstObservation = store.$articles.dropFirst().sink { _ in burstPublications += 1 }
        // The batch waits longer than the writes take on a loaded machine; the test publishes it explicitly.
        store.coalescedPublicationDelay = .seconds(600)
        for article in burst {
            await store.updateEnrichment(id: article.id, category: "Science", coalescesPublication: true)
        }
        await store.updateEnrichment(id: burst[0].id, category: "World", coalescesPublication: true)
        assertEqual(burstPublications, 0, "Background classification waits to be published together")
        assertEqual(store.revision, burstRevision, "Waiting classification does not reload queries yet")
        await store.flushPendingPublications()
        assertEqual(burstPublications, 1, "A classification burst publishes the article collection once")
        assertEqual(store.revision, burstRevision + 1, "A classification burst reloads queries once")
        assertEqual(
            store.articles.first { $0.title == "Burst 0" }?.category, "World",
            "The latest classification of a story is the one published")
        assertEqual(
            store.articles.filter { $0.title.hasPrefix("Burst ") && $0.title != "Burst 0" }.compactMap(\.category),
            Array(repeating: "Science", count: 4), "Every story of the burst is published")
        burstObservation.cancel()

        let delegate = SecureSessionDelegateCoordinator()
        let request = URLRequest(url: URL(string: "https://example.com")!)
        let task = URLSession.shared.dataTask(with: request)
        let response = HTTPURLResponse(url: request.url!, statusCode: 302, httpVersion: nil, headerFields: nil)!
        for destination in ["file:///etc/passwd", "https://example.com:22/story", "http://example.com/story"] {
            var rejected = false
            delegate.urlSession(
                .shared, task: task, willPerformHTTPRedirection: response,
                newRequest: URLRequest(url: URL(string: destination)!)
            ) { redirected in
                rejected = redirected == nil
            }
            assertTrue(rejected, "Unsafe redirect must be rejected before connection")
        }
        task.cancel()

        // Redirect safety state is keyed per task object, not by task identifier across sessions (#808). The
        // injected resolver keeps the allowed redirect off the network.
        let keyed = SecureSessionDelegateCoordinator(resolver: { _ in .allowed(ips: ["93.184.216.34"]) })
        let sessionConfig = URLSessionConfiguration.ephemeral
        let sessionA = URLSession(configuration: sessionConfig)
        let sessionB = URLSession(configuration: sessionConfig)
        defer {
            sessionA.invalidateAndCancel()
            sessionB.invalidateAndCancel()
        }
        let taskA = sessionA.dataTask(with: URL(string: "http://example.com/start")!)
        let taskB = sessionB.dataTask(with: URL(string: "https://example.com/start")!)
        assertEqual(
            taskA.taskIdentifier, taskB.taskIdentifier,
            "Two distinct sessions issue overlapping task identifiers starting at 1")

        let responseA = HTTPURLResponse(
            url: taskA.originalRequest!.url!, statusCode: 302, httpVersion: nil, headerFields: nil)!
        var redirectedA: URLRequest? = nil
        keyed.urlSession(
            sessionA, task: taskA, willPerformHTTPRedirection: responseA,
            newRequest: URLRequest(url: URL(string: "http://example.com/next")!)
        ) { redirectedA = $0 }
        assertTrue(redirectedA != nil, "Task A with HTTP scheme permits HTTP redirect")

        let responseB = HTTPURLResponse(
            url: taskB.originalRequest!.url!, statusCode: 302, httpVersion: nil, headerFields: nil)!
        var redirectedB: URLRequest? = nil
        keyed.urlSession(
            sessionB, task: taskB, willPerformHTTPRedirection: responseB,
            newRequest: URLRequest(url: URL(string: "http://example.com/downgrade")!)
        ) { redirectedB = $0 }
        assertTrue(
            redirectedB == nil,
            "Task B with HTTPS scheme refuses downgrade to HTTP despite matching task identifier")

        // Task B uses up its redirect depth, then task A completes; a dropped state would start B at zero again.
        let safe = URLRequest(url: URL(string: "https://example.com/safe")!)
        for _ in 1..<SecureHTTPClient.maxRedirects {
            keyed.urlSession(sessionB, task: taskB, willPerformHTTPRedirection: responseB, newRequest: safe) { _ in }
        }
        keyed.urlSession(sessionA, task: taskA, didCompleteWithError: nil)

        var redirectedB2: URLRequest? = URLRequest(url: URL(string: "https://example.com/unset")!)
        keyed.urlSession(sessionB, task: taskB, willPerformHTTPRedirection: responseB, newRequest: safe) {
            redirectedB2 = $0
        }
        assertTrue(
            redirectedB2 == nil,
            "Task B keeps its redirect count after task A completes, so the redirect past the limit is refused")

        taskA.cancel()
        taskB.cancel()

        // Proxy refresh is required whenever the gateway listener port changes (#807).
        assertTrue(
            WebPreviewPolicy.needsProxyRefresh(configuredPort: nil, currentPort: 8080),
            "Unconfigured port needs refresh")
        assertTrue(
            WebPreviewPolicy.needsProxyRefresh(configuredPort: 8080, currentPort: 8081), "Changed port needs refresh")
        assertFalse(
            WebPreviewPolicy.needsProxyRefresh(configuredPort: 8080, currentPort: 8080),
            "Unchanged port does not refresh")
        assertTrue(
            WebPreviewPolicy.needsProxyRefresh(configuredPort: UInt16(8080), currentPort: UInt16(8081)),
            "UInt16 changed port needs refresh")
        assertFalse(
            WebPreviewPolicy.needsProxyRefresh(configuredPort: UInt16(8080), currentPort: UInt16(8080)),
            "UInt16 unchanged port does not refresh")

        // A refused subframe is dropped quietly; only a refused main frame reports an error (#802).
        var insecureRefused = false
        do { try await SecureHTTPClient.shared.validateDestination(URL(string: "http://example.com/frame")!) } catch {
            insecureRefused = true
        }
        assertTrue(insecureRefused, "An http address is refused while insecure HTTP is off")
        assertTrue(
            WebPreviewPolicy.refusalMessage(isMainFrame: true) != nil, "A main-frame refusal reports an error")
        assertTrue(WebPreviewPolicy.refusalMessage(isMainFrame: false) == nil, "A subframe refusal is quiet")
        assertTrue(WebPreviewPolicy.isMainFrame(targetFrameIsMain: nil), "A new-window navigation counts as main frame")
    }

    @MainActor
    static func testProductionFollowupRegressions() async throws {
        print("  - Testing cache rollback, ordered mutations, saved analysis and update failures...")
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let path = directory.appendingPathComponent("regression.sqlite").path
        let db = DatabaseEngine(path: path)
        let store = ArticleStore(database: db)
        await store.initialize()
        assertTrue(store.migrationCoordinator == nil, "Injected stores must not migrate real user defaults or caches")
        let article = FeedArticle(
            title: "Archived report", link: "https://example.com/archive", guid: "archived", description: "Preview",
            pubDate: .distantPast, source: "Publisher", fullContent: "Preserve this body")
        await store.batchUpsert(articles: [article], feedUrl: "https://example.com/rss")
        let reads = ReadManager(articleStore: store)
        let saves = SavedStoriesManager(articleStore: store)
        for _ in 0..<20 {
            reads.toggleRead(article.id)
            saves.save(article)
            saves.remove(article)
        }
        reads.markAsRead(article.id)
        saves.save(article)
        await reads.waitForPendingChanges()
        await saves.waitForPendingChanges()
        assertTrue(try await db.isSaved(articleId: article.id), "Latest rapid save intent persists")
        assertTrue(try await db.getReadArticleIDs().contains(article.id), "Latest rapid read intent persists")
        let analysis = ArticleAnalysis(
            summary: "New summary", keyPoints: ["Finding"], entities: [], category: "Science", sentiment: nil,
            modelIdentifier: "test", analysisVersion: 2)
        await store.saveArticleAnalysis(analysis, for: article.id)
        assertEqual(store.savedArticles.first?.aiSummary, "New summary", "Saved snapshot receives new analysis")
        await store.setSaved(article: article, isSaved: false)
        var connection: OpaquePointer?
        assertEqual(sqlite3_open(path, &connection), SQLITE_OK, "Open isolated failure-injection database")
        defer { sqlite3_close(connection) }
        assertEqual(
            sqlite3_exec(
                connection,
                "CREATE TRIGGER fail_cache BEFORE DELETE ON article_enrichment BEGIN SELECT RAISE(ABORT, 'simulated disk failure'); END;",
                nil, nil, nil), SQLITE_OK, "Install rollback regression trigger")
        do {
            try await store.clearArticleCache()
            assertTrue(false, "Cache failures must reach the caller")
        } catch {
            // Failure is expected: the preceding assertion rejects an unexpected success.
        }
        let restored = try await db.fetchArticles(limit: 10)
        assertEqual(
            restored.first?.fullContent, "Preserve this body", "Failed cleanup rolls back the preceding content update")
        assertEqual(
            sqlite3_exec(connection, "DROP TRIGGER fail_cache;", nil, nil, nil), SQLITE_OK,
            "Remove isolated failure trigger")
        try await store.clearAllDatabaseCache()
        assertTrue(try await db.getReadArticleIDs().contains(article.id), "All-cache cleanup preserves read history")
        try await db.markAllRead(feedUrl: "https://example.com/rss")

        var recent: [FeedArticle] = []
        for number in 0..<510 {
            recent.append(
                FeedArticle(
                    title: "Recent \(number)", link: "https://example.com/\(number)", guid: "recent-\(number)",
                    description: "Recent", pubDate: Date(), source: "Publisher"))
        }
        try await db.upsertArticles(recent)
        let history = try await db.fetchArticles(isRead: true, limit: 200)
        assertTrue(
            history.contains(where: { $0.id == article.id }), "History queries include stories beyond the recent 500")
        let found = try await db.searchArticles(query: "Archived", limit: 200)
        assertEqual(found.first?.id, article.id, "Search reaches archived stories")
        assertEqual(
            try await db.searchArticles(query: "Archiv", limit: 200).first?.id, article.id,
            "FTS prefix search matches unfinished words")
        try await db.markRead(articleId: article.id, isRead: false)
        try await db.upsertArticles([article], feedUrl: "https://example.com/second-rss")
        try await db.markAllRead(feedUrl: "https://example.com/rss")
        assertTrue(
            try await db.getReadArticleIDs().contains(article.id),
            "Duplicate ingestion preserves original feed provenance")
        try await db.markRead(articleId: article.id, isRead: false)
        try await db.markAllRead(feedUrl: "https://example.com/second-rss")
        assertTrue(
            try await db.getReadArticleIDs().contains(article.id), "Shared stories belong to every originating feed")
        let firstPage = try await db.fetchArticles(limit: 200)
        let secondPage = try await db.fetchArticles(limit: 200, after: ArticleQueryCursor(firstPage.last!))
        let thirdPage = try await db.fetchArticles(limit: 200, after: ArticleQueryCursor(secondPage.last!))
        assertEqual(
            Set((firstPage + secondPage + thirdPage).map(\.id)).count, 511,
            "Keyset pages include all stories without duplicates at tied dates")
        let searchPage = try await db.searchArticles(query: "Recent", limit: 200)
        let searchNext = try await db.searchArticles(
            query: "Recent", limit: 400, after: ArticleQueryCursor(searchPage.last!))
        assertEqual(
            Set((searchPage + searchNext).map(\.id)).count, 510, "FTS rank cursor handles tied ranks without omissions")
        await db.close()

        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [MockURLProtocol.self]
        let testClient = mockHTTPClient(configuration: config)
        defer { MockURLProtocol.requestHandler = nil }
        let checker = UpdateChecker(httpClient: testClient)
        checker.updateAvailable = true
        checker.verifiedReleaseURL = URL(string: "https://github.com/marspater/NewsApp-macOS/releases/latest")
        MockURLProtocol.requestHandler = { _ in throw URLError(.notConnectedToInternet) }
        await checker.checkForUpdates(userInitiated: true)
        assertFalse(checker.updateAvailable, "Failed update checks clear stale availability")
        assertTrue(checker.verifiedReleaseURL == nil, "Failed update checks clear stale release links")
        MockURLProtocol.requestHandler = { request in
            (HTTPURLResponse(url: request.url!, statusCode: 404, httpVersion: nil, headerFields: nil)!, Data())
        }
        await checker.checkForUpdates(userInitiated: true)
        assertEqual(
            checker.statusMessage, "No published release is available to compare.",
            "Missing releases are not reported as up to date")

        let expectedUserAgent = "NewsApp/\(checker.currentAppVersion)"
        MockURLProtocol.requestHandler = { request in
            assertEqual(request.url?.host, "api.github.com", "Updates use the GitHub API")
            assertEqual(
                request.value(forHTTPHeaderField: "Accept"), "application/vnd.github+json",
                "Protected update requests preserve JSON negotiation")
            assertEqual(
                request.value(forHTTPHeaderField: "User-Agent"), expectedUserAgent,
                "Protected update requests preserve the app user agent")
            assertEqual(request.cachePolicy, .reloadIgnoringLocalCacheData, "Updates do not replay cached responses")
            assertEqual(request.timeoutInterval, 10, "Update requests retain their timeout")
            let payload = GitHubReleasePayload(
                tagName: "v999.0.0", name: nil,
                htmlUrl: "https://github.com/marspater/NewsApp-macOS/releases/tag/v999.0.0",
                body: "Release notes", publishedAt: nil)
            return (
                HTTPURLResponse(
                    url: request.url!, statusCode: 200, httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"])!, try JSONEncoder().encode(payload)
            )
        }
        await checker.checkForUpdates(userInitiated: true)
        assertTrue(checker.updateAvailable, "A valid newer release is offered through the protected client")
        assertEqual(checker.latestVersionString, "v999.0.0", "New release version is retained")
        assertEqual(checker.releaseNotes, "Release notes", "New release notes are retained")
        assertTrue(checker.verifiedReleaseURL != nil, "A trusted release link is retained")
        MockURLProtocol.requestHandler = { _ in
            assertTrue(false, "Automatic checks within six hours must not make another request")
            throw URLError(.cancelled)
        }
        await checker.checkForUpdates()
        assertTrue(checker.updateAvailable, "Throttling preserves the last successful result")

        MockURLProtocol.requestHandler = { request in
            (HTTPURLResponse(url: request.url!, statusCode: 503, httpVersion: nil, headerFields: nil)!, Data())
        }
        await checker.checkForUpdates(userInitiated: true)
        assertEqual(
            checker.statusMessage, "Update check failed (HTTP 503)",
            "Protected client HTTP failures retain their status")
        assertFalse(checker.updateAvailable, "HTTP failures clear stale availability")
        assertTrue(checker.verifiedReleaseURL == nil, "HTTP failures clear stale release links")

        MockURLProtocol.requestHandler = { request in
            (
                HTTPURLResponse(
                    url: request.url!, statusCode: 200, httpVersion: nil,
                    headerFields: ["Content-Type": "application/json", "Content-Length": "1048577"])!, Data()
            )
        }
        await checker.checkForUpdates(userInitiated: true)
        assertEqual(checker.statusMessage, "Unable to check for updates", "Oversized update responses are rejected")
        assertFalse(checker.updateAvailable, "Oversized responses cannot offer an update")

        MockURLProtocol.requestHandler = { request in
            let payload = GitHubReleasePayload(
                tagName: "v999.0.0", name: nil,
                htmlUrl: "https://example.com/releases/tag/v999.0.0", body: nil, publishedAt: nil)
            return (
                HTTPURLResponse(
                    url: request.url!, statusCode: 200, httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"])!, try JSONEncoder().encode(payload)
            )
        }
        await checker.checkForUpdates(userInitiated: true)
        assertEqual(checker.statusMessage, "Received untrusted release URL", "Untrusted release links are rejected")
        assertFalse(checker.updateAvailable, "Untrusted release links cannot offer an update")
        assertTrue(checker.verifiedReleaseURL == nil, "Untrusted release links are never retained")
    }

    static func testLiveReader(pagesOnly: Bool = false) async {
        for link in [
            "https://www.bbc.co.uk/news/articles/c6jdvmy1287yo", "https://www.bbc.co.uk/news/articles/cm750pyz5r0eo",
        ] {
            let outcome = await ContentExtractionPipeline.shared.extractArticleDetailed(from: link)
            guard case .success(let content, _, let document) = outcome else {
                assertTrue(false, "BBC reader regression must extract publisher prose")
                continue
            }
            assertTrue(document != nil, "Live publisher retains reader structure")
            print(
                "Live page: \(link), \(content.count) prose characters, \(document?.blocks.count ?? 0) blocks, \(document?.images?.count ?? 0) image candidates"
            )
            assertFalse(content.contains("Get in touch"), "BBC contact furniture excluded")
            assertFalse(content.contains("17:45 weekdays"), "BBC listening promotion excluded")
        }

        if pagesOnly { return }
        for url in [
            "https://www.theguardian.com/world/rss", "https://feeds.arstechnica.com/arstechnica/index",
            "https://www.nasa.gov/feed/",
        ] {
            let result = await FeedFetcher.shared.fetchSingleFeed(urlString: url)
            assertTrue(result.error == nil, "Live feed fetch must succeed for \(url)")
            guard let article = result.articles?.first else {
                assertTrue(false, "Live feed must contain an article")
                continue
            }
            let outcome = await ContentExtractionPipeline.shared.extractArticleDetailed(from: article.link)
            let content = article.fullContent ?? outcome.content ?? ""
            assertFalse(
                ArticleContentRedactor.redactAndSplit(content).isEmpty,
                "Live publisher article must provide readable prose for \(url)")
            print(
                "  - Live reader: \(URL(string: url)!.host!), \(result.articles!.count) items, \(content.count) body characters; extraction success: \(outcome.isSuccess)"
            )
        }
    }

    static func testReaderParsingRegressions() async {
        for (identifier, excluded) in [
            ("article-commentary", false), ("comment-thread", true),
            ("RELATED-ARTICLES", true), ("unrelated-content", false),
        ] {
            let node = DOMElementNode(tag: "div", attributes: ["class": identifier], text: "Publisher prose")
            assertEqual(
                node.isReaderExcluded, excluded, "Cached exclusion regex preserves token boundaries and case matching")
        }
        let topic = await ArticleClassifier.shared.classify(
            title: "NASA launches space telescope", description: "Astronomy mission")
        assertEqual(topic.category, "Science", "Cheap ingestion classification works without generative inference")
        let pipeline = ContentExtractionPipeline.shared
        assertEqual(
            HTMLDOMBuilder.parse(html: "<p>Before<!-- hidden\ncomment --> after.</p>").combinedText(),
            "Before after.", "Cached comment regex removes multiline comments")
        let encodedHTML = "<p>Publisher caf\u{00e9}</p>"
        let latin1Data = encodedHTML.data(using: .isoLatin1)!
        let latin1Response = HTTPURLResponse(
            url: URL(string: "https://example.com/article")!,
            statusCode: 200, httpVersion: nil, headerFields: ["Content-Type": "text/html; CHARSET='ISO-8859-1'"])!
        assertEqual(
            pipeline.decodeHTML(data: latin1Data, response: latin1Response), encodedHTML,
            "Cached header regex preserves case-insensitive quoted charset decoding")
        for meta in ["<meta charset='iso-8859-1'>", "<meta content='text/html;charset=iso-8859-1'>"] {
            let document = meta + encodedHTML
            assertEqual(
                pipeline.decodeHTML(data: document.data(using: .isoLatin1)!), document,
                "Cached meta regexes preserve both charset declarations")
        }
        // #819: one stray byte in a UTF-8 page, and a prefix fetch cut inside a character, keep UTF-8 text.
        var strayByte = Data("<p>It\u{2019}s caf\u{00e9} ".utf8)
        strayByte.append(0xFF)
        strayByte.append(contentsOf: Data("na\u{00ef}ve</p>".utf8))
        assertEqual(
            pipeline.decodeHTML(data: strayByte), "<p>It\u{2019}s caf\u{00e9} \u{FFFD}na\u{00ef}ve</p>",
            "An undeclared UTF-8 page with one invalid byte is not decoded as Latin-1")
        let utf8Response = HTTPURLResponse(
            url: URL(string: "https://example.com/article")!,
            statusCode: 200, httpVersion: nil, headerFields: ["Content-Type": "text/html; charset=utf-8"])!
        assertEqual(
            pipeline.decodeHTML(data: strayByte, response: utf8Response),
            "<p>It\u{2019}s caf\u{00e9} \u{FFFD}na\u{00ef}ve</p>", "A declared UTF-8 page decodes leniently")
        let cut = Data("<p>caf\u{00e9} \u{2019}".utf8).dropLast(2)
        assertEqual(
            pipeline.decodeHTML(data: Data(cut), response: utf8Response), "<p>caf\u{00e9} ",
            "A trailing partial sequence from a prefix fetch is trimmed")
        assertEqual(
            pipeline.decodeHTML(data: "<p>caf\u{00e9} na\u{00ef}ve</p>".data(using: .isoLatin1)!),
            "<p>caf\u{00e9} na\u{00ef}ve</p>", "An undeclared Latin-1 page still decodes as Latin-1")
        assertEqual(
            pipeline.decodeHTML(data: Data("<p>caf\u{00e9} \u{FFFD}</p>".utf8)), "<p>caf\u{00e9} \u{FFFD}</p>",
            "Valid UTF-8 containing a literal replacement character stays UTF-8")
        var tied = Data("<p>caf\u{00e9} ".utf8)
        tied.append(0xFF)
        assertEqual(
            pipeline.decodeHTML(data: tied), "<p>caf\u{00e9} \u{FFFD}",
            "One valid multi-byte character against one invalid byte keeps UTF-8")
        assertEqual(
            pipeline.decodeHTML(data: "<p>na\u{00ef}ve \u{00ff}".data(using: .isoLatin1)!), "<p>na\u{00ef}ve \u{00ff}",
            "A trailing byte that cannot start a UTF-8 sequence is not trimmed from a Latin-1 page")
        let inline = "<p>The <strong>central bank</strong> raised <a href='/rate'>rates</a> today.</p>"
        assertEqual(
            HTMLDOMBuilder.parse(html: inline).combinedText(), "The central bank raised rates today.",
            "Inline text retains publisher order and punctuation")
        let prose =
            "The central bank published its quarterly report with detailed forecasts for inflation and employment across the economy."
        let second =
            "Independent economists reviewed the figures and described the outlook as stable, with further updates expected next month."
        let html = "<SCRIPT>ignored()</SCRIPT><ARTICLE><P>\(prose)<P>\(second)</ARTICLE>"
        assertEqual(
            pipeline.extractFromHTML(html).content, "\(prose)\n\n\(second)",
            "Uppercase raw tags and optional paragraph endings preserve the body")
        let third =
            "Officials said the review would continue into next year, and a public consultation is planned before any decision."
        let threeParagraphs = "<p>\(prose)</p><p>\(second)</p><p>\(third)</p>"
        assertEqual(
            pipeline.extractFromHTML(
                "<script>document.write('<script src=\"/jquery.js\">\\x3C/script>')</script><article>\(threeParagraphs)</article>"
            ).content, "\(prose)\n\n\(second)\n\n\(third)",
            "Markup written inside a script does not swallow the page (Africanews, CNA, Science News)")
        assertEqual(
            pipeline.extractFromHTML(
                "<style>a::before { content: '<style>'; } /* </b> */</style><script>var s = '</div>';</script><article>\(threeParagraphs)</article>"
            ).content, "\(prose)\n\n\(second)\n\n\(third)",
            "Style and script end at their own first closing tag, whatever markup they contain")
        assertEqual(
            pipeline.extractFromHTML(
                "<nav><nav><p>Menu link text that is long enough to read as prose here.</p></nav></nav><article>\(threeParagraphs)</article>"
            )
            .content, "\(prose)\n\n\(second)\n\n\(third)",
            "Nested ignored elements still close by depth")
        assertEqual(
            pipeline.extractFromHTML(
                "<div class='menu'><h3>Topics</h3><h3>Sections</h3></div><div class='entry-content'><figure><img src='https://news.example/a.jpg' width='1200' height='800'></figure>\(threeParagraphs)</div>"
            ).content, "\(prose)\n\n\(second)\n\n\(third)",
            "An explicit publisher body keeps every paragraph (NASA)")
        assertEqual(
            pipeline.extractFromHTML(
                "<div class='menu'><h3>Topics</h3><h3>Sections</h3><p>Top Programming Languages</p></div><div class='body-description'>\(threeParagraphs)</div>"
            ).content, "\(prose)\n\n\(second)\n\n\(third)",
            "A RebelMouse body beats the site menu (IEEE Spectrum)")
        assertEqual(
            pipeline.extractFromHTML(
                "<article><p>\(prose)</p><div class='pmc-paywall'><p>\(second)</p><p>\(third)</p></div></article>"
            )
            .content, "\(prose)\n\n\(second)\n\n\(third)",
            "A metering wrapper holding the story stays (Variety)")
        assertEqual(
            pipeline.extractFromHTML(
                "<article>\(threeParagraphs)<div class='paywall'><p>Subscribe today for unlimited access to every story we publish.</p></div></article>"
            ).content, "\(prose)\n\n\(second)\n\n\(third)",
            "A paywall prompt without the story is still furniture")
        assertEqual(
            pipeline.extractFromHTML(
                "<article><div x-cloak class='panel'><label>Size</label><select><option>Small</option><option>Standard</option><option>Large</option></select> Links Standard Orange</div>\(threeParagraphs)</article>"
            ).content, "\(prose)\n\n\(second)\n\n\(third)",
            "Script-only panels and form controls are not story text (Ars Technica)")
        assertEqual(
            pipeline.extractFromHTML(
                "<article><div class='story'>\(threeParagraphs)<p>\(prose)</p><p>\(second)</p></div><div class='article-body'><p>Sponsored: a short report on how security teams measure the defenses they deploy.</p><p>Download the free report today to compare your scores with industry peers.</p></div></article>"
            ).content?.hasPrefix(prose), true,
            "A small box with an explicit body class does not replace the story (BleepingComputer)")
        let standfirst = "Officials expect the review to shape spending plans for the coming decade across the region."
        let guardianLike = pipeline.extractFromHTML(
            "<article><div data-gu-name='media'><figure><img src='https://news.example/lead.jpg' width='1200' height='800'><figcaption>Crews at work.</figcaption></figure></div><div class='player-note'><p>This story is voiced by an automated narrator for listeners on the go.</p></div><div data-gu-name='standfirst'><p>\(standfirst)</p></div><div class='article-body-commercial-selector'>\(threeParagraphs)</div></article>"
        )
        assertEqual(
            guardianLike.content, "\(standfirst)\n\n\(prose)\n\n\(second)\n\n\(third)",
            "An explicit body keeps the article's standfirst but not other lead-in text (the Guardian)")
        assertEqual(
            pipeline.extractFromHTML(
                "<article><header><h1>Review shapes plans</h1><p class='standfirst'>\(standfirst)</p></header><div class='entry-content'>\(threeParagraphs)</div></article>"
            ).content, "\(standfirst)\n\n\(prose)\n\n\(second)\n\n\(third)",
            "A standfirst in the article's own header survives the explicit-body repair")
        assertEqual(
            pipeline.extractFromHTML(
                "<article><h3>Email Story</h3><p>Join our Whatsapp Channel</p>\(threeParagraphs)</article>"
            )
            .content, "\(prose)\n\n\(second)\n\n\(third)",
            "Sharing and channel prompts are not story text (Dawn)")
        if case .success(_, _, let document) = guardianLike {
            assertEqual(
                document?.blocks.first?.imageURL, "https://news.example/lead.jpg",
                "An explicit body keeps the article's lead figure")
        } else {
            assertTrue(false, "The Guardian-like page extracts")
        }
        assertTrue(
            pipeline.extractFromHTML("<article><div>\(prose)</div><div>\(second)</div></article>").isSuccess,
            "Div-only articles remain readable")
        // #242: the region stops at the article body, and repeated page furniture no longer rejects the page.
        let body = (1...6).map { "<p>Paragraph \($0): \(prose)</p>" }.joined()
        let teasers = (1...12).map {
            "<div class=\"card\"><a href=\"/story/\($0)\"><h3>Other headline number \($0) about a different event entirely</h3></a></div>"
        }.joined()
        let wrapped = pipeline.extractFromHTML(
            "<div class=\"site\"><article><div class=\"article__text\">\(body)</div><h2>Most Popular</h2>\(teasers)</article></div>"
        )
        assertEqual(
            wrapped.content?.components(separatedBy: "\n\n").count, 6,
            "A link-heavy wrapper cannot outscore the article body")
        assertFalse(wrapped.content?.contains("Other headline") ?? true, "Teaser links stay out of the reader")
        let cited = (1...6).map {
            "<p>Section two, point \($0): officials cited <a href=\"/a/\($0)\">the published quarterly inflation report from the central bank</a> and <a href=\"/b/\($0)\">the independent employment survey released last week</a> today.</p>"
        }.joined()
        let sectioned = pipeline.extractFromHTML(
            "<article><section>\(body)</section><section>\(cited)</section><section><p>Closing: \(second)</p></section></article>"
        )
        assertEqual(
            sectioned.content?.components(separatedBy: "\n\n").count, 13,
            "Heavily cited prose keeps every section of the article")
        let halfCited = pipeline.extractFromHTML(
            "<article><section>" + (1...5).map { "<p>Paragraph \($0): \(prose)</p>" }.joined() + "</section>"
                + cited.components(separatedBy: "</p>").prefix(5).map { $0 + "</p>" }.joined() + "</article>")
        assertEqual(
            halfCited.content?.components(separatedBy: "\n\n").count, 10,
            "Citations never trigger the link-density penalty")
        let cards =
            "<ul>"
            + (1...10).map {
                "<li><a href=\"/related/\($0)\">Related story number \($0): a long headline about another event in a different country entirely</a> Two hours ago, from our foreign desk.</li>"
            }.joined() + "</ul>"
        let carded = pipeline.extractFromHTML(
            "<div class=\"site\"><article><div class=\"body\">\(body)</div>\(cards)</article></div>")
        assertFalse(
            carded.content?.contains("Related story") ?? true,
            "Teaser cards dominated by one headline link stay navigation")
        let citedList =
            "<ul>" + cited.replacingOccurrences(of: "<p>", with: "<li>").replacingOccurrences(of: "</p>", with: "</li>")
            + "</ul>"
        let listed = pipeline.extractFromHTML(
            "<article><section>\(body)</section><section>\(citedList)</section><section><p>Closing: \(second)</p></section></article>"
        )
        assertEqual(
            listed.content?.components(separatedBy: "\n\n").count, 13, "Cited list items count as prose, not navigation"
        )
        // #246: widgets inside an article must not make its final sections lose to the first section.
        let widget = "<div class=\"related-stories\">" + teasers + "</div>"
        let interrupted = pipeline.extractFromHTML(
            "<article><section>\(body)</section>\(widget)<section><p>Ending one: \(prose)</p><p>Ending two: \(second)</p></section></article>"
        )
        assertEqual(
            interrupted.content?.components(separatedBy: "\n\n").count, 8,
            "An inline related widget keeps both surrounding article sections")
        let splitCards = (1...10).map {
            "<li class=\"story-card\"><a href=\"/category/\($0)\">World news and politics</a> <a href=\"/other/\($0)\">Other headline number \($0) about another country</a> <a href=\"/publisher/\($0)\">The international reporting desk</a> Published this morning with the latest updates and background.</li>"
        }.joined()
        let splitCarded = pipeline.extractFromHTML(
            "<article><section>\(body)</section><ul>\(splitCards)</ul></article>")
        assertEqual(
            splitCarded.content?.components(separatedBy: "\n\n").count, 6,
            "Split-link teaser cards cannot masquerade as cited prose")
        assertFalse(
            splitCarded.content?.contains("Other headline") ?? true, "Card markup excludes multi-anchor teaser text")
        assertEqual(
            HTMLDOMBuilder.parse(html: "<a class=\"card\" href=\"/story\">Linked card headline</a>").combinedText(),
            "Linked card headline", "A link styled as a card is traversed without recursive self-inspection")
        let editorialCard = pipeline.extractFromHTML(
            "<article><div class=\"card\"><p>\(prose) See <a href=\"/report\">the report</a>.</p><p>\(second) See <a href=\"/survey\">the survey</a>.</p></div></article>"
        )
        assertTrue(
            editorialCard.isSuccess, "Presentation cards containing mostly publisher prose retain inline citations")
        let placeholder =
            "<p>To view this video please enable JavaScript, and consider upgrading to a web browser that supports HTML5 video</p>"
        let pullQuote =
            "<p>“\(second) This is the line the editors chose to repeat as a pull quote in the middle of the story.”</p>"
        let furnished = pipeline.extractFromHTML(
            "<article>\(placeholder)\(body)\(placeholder)\(pullQuote)\(placeholder)\(pullQuote)</article>")
        assertFalse(
            furnished.content?.contains("enable JavaScript") ?? true,
            "Repeated short furniture is removed instead of rejecting the page")
        assertEqual(
            furnished.content?.components(separatedBy: "pull quote").count, 2,
            "A repeated prose-length block keeps one occurrence")
        let aside = "<p>(The report was updated on Tuesday.)</p>"
        let asided = pipeline.extractFromHTML("<article>\(body)\(aside)\(aside)</article>")
        assertEqual(
            asided.content?.components(separatedBy: "updated on Tuesday").count, 2,
            "Sentence punctuation before a closing parenthesis is prose")
        let shortQuote = "<p>“We will not back down,” the minister said.</p>"
        let quoted = pipeline.extractFromHTML(
            "<article>\(body)\(shortQuote)<blockquote>\(shortQuote)</blockquote><p>Read more</p><p>Read more</p></article>"
        )
        assertEqual(
            quoted.content?.components(separatedBy: "We will not back down").count, 2,
            "A short repeated sentence keeps one occurrence")
        assertFalse(quoted.content?.contains("Read more") ?? true, "Repeated labels are removed")
        let crowded = pipeline.extractFromHTML(
            "<article>" + String(repeating: placeholder, count: 5)
                + (1...3).map { "<p>Paragraph \($0): \(prose)</p>" }.joined() + "</article>")
        assertEqual(
            crowded.content?.components(separatedBy: "\n\n").count, 3,
            "Labels are removed before the repetition check, even when they outnumber the prose")
        let loop = String(repeating: "<p>\(prose)</p>", count: 4)
        assertFalse(
            pipeline.extractFromHTML("<article>\(loop)<p>\(second)</p></article>").isSuccess,
            "A page that is mostly one repeated paragraph is still a loop")
        let hiddenHTML =
            "<article><p>\(prose)</p><p>\(second)</p><div hidden><p>Hidden subscription announcement that should never appear in a reader.</p></div><div aria-hidden='true'>Another hidden panel with a substantial amount of text.</div><button>Follow this publisher for personalized updates and notifications.</button></article>"
        assertEqual(
            pipeline.extractFromHTML(hiddenHTML).content, "\(prose)\n\n\(second)",
            "Hidden panels and button labels cannot leak into publisher prose")
        let atom = """
            <atom:feed xmlns:atom="http://www.w3.org/2005/Atom"><atom:title>Daily</atom:title><atom:entry>
            <atom:id>item-1</atom:id><atom:title>Report</atom:title>
            <atom:link href="/report"/><atom:link rel="self" href="/api/report"/>
            <atom:published>2026-09-20T10:00:00Z</atom:published><atom:updated>2026-09-21T10:00:00Z</atom:updated>
            <atom:content type="xhtml"><div xmlns="http://www.w3.org/1999/xhtml"><p>First <b>important</b> paragraph.</p><p>Second paragraph.</p></div></atom:content>
            </atom:entry></atom:feed>
            """
        let article = FeedXMLParser(data: Data(atom.utf8), feedURL: "https://example.com/feed").parse().first
        assertEqual(article?.link, "https://example.com/report", "Atom self links cannot replace article links")
        assertEqual(
            article?.fullContent, "First important paragraph.\n\nSecond paragraph.",
            "Atom XHTML preserves paragraph boundaries")
        assertEqual(
            article?.pubDate, DateParser.parse("2026-09-20T10:00:00Z"),
            "Published and updated dates are not concatenated")
        // #115: Ekonomichna Pravda sends plain text in content:encoded, paragraphs separated by blank lines.
        let plainEncoded = """
            <rss xmlns:content="http://purl.org/rss/1.0/modules/content/"><channel><title>Daily</title><item><title>Report</title>
            <link>https://example.com/plain</link><content:encoded><![CDATA[ \(prose)


            Officials said the agreement &amp; its annexes wouldn&#8217;t be published&nbsp;before the parliamentary review next week.


            \(second)]]></content:encoded></item></channel></rss>
            """
        let plainArticle = FeedXMLParser(data: Data(plainEncoded.utf8)).parse().first
        assertEqual(
            plainArticle.map { ArticleContentRedactor.redactAndSplit($0.fullContent ?? "") },
            [
                prose,
                "Officials said the agreement & its annexes wouldn\u{2019}t be published before the parliamentary review next week.",
                second,
            ],
            "Plain-text content:encoded keeps its paragraph breaks and decodes entities")
        assertTrue(
            plainArticle?.readerDocument == nil,
            "Plain feed text is no reader document, so the reader fetches the page's structure")
        let rss =
            "<rss><channel><title>News</title><image><title>News logo</title></image><item><title>Story</title><link>https://example.com/story</link></item></channel></rss>"
        assertEqual(
            FeedXMLParser(data: Data(rss.utf8)).parse().first?.source, "News",
            "Feed image title cannot contaminate publisher name")
        let broken = FeedXMLParser(data: Data("<rss><channel><item>".utf8))
        assertTrue(broken.parse().isEmpty && broken.parseError != nil, "Malformed feeds report a parsing failure")
        let json = """
            {"version":"https://jsonfeed.org/version/1.1","items":[{"id":"1","url":"https://example.com/1","content_text":"Use x < y and y > z.","summary":"Use x < y and y > z. Keep &amp; literal."},{"id":"2","url":"https://example.com/2","description":"<p>Legacy <b>HTML</b> &amp; text.</p>"}]}
            """
        let textArticle = JSONFeedParser.parse(data: Data(json.utf8), feedURL: "https://example.com/feed")?.first
        assertEqual(
            textArticle?.fullContent, "Use x < y and y > z.", "JSON plain text must never pass through HTML stripping")
        assertEqual(textArticle?.contentFetched, true, "Short explicit feed content is readable")
        assertEqual(
            textArticle?.description, "Use x < y and y > z. Keep &amp; literal.",
            "JSON summaries preserve plain text comparisons and literal entities")
        let legacyArticle = JSONFeedParser.parse(data: Data(json.utf8), feedURL: "https://example.com/feed")?.last
        assertEqual(legacyArticle?.description, "Legacy HTML & text.", "Legacy JSON descriptions retain HTML cleanup")
        let unidentified = """
            {"version":"https://jsonfeed.org/version/1.1","items":[{"id":"1","url":"https://example.com/1","title":"Kept"},{"title":"No id or URL","content_text":"Dropped"}]}
            """
        assertEqual(
            JSONFeedParser.parse(data: Data(unidentified.utf8), feedURL: "https://example.com/feed")?.map(\.title),
            ["Kept"], "An item with neither id nor URL is skipped instead of getting a random identity on every refresh"
        )
    }

    static func testStructuredReaderAndTags() async {
        let first =
            "The central bank published its quarterly report with detailed forecasts for inflation and employment across the economy."
        let second =
            "Independent economists reviewed the figures and described the outlook as stable, with further updates expected next month."
        let html = """
            <main><article><p>\(first)</p><h2>What changes?</h2><p>\(second)</p>
            <ol start="3"><li>Lower fees</li><li>Faster payments</li></ol>
            <blockquote><p>The outlook remains stable.</p><p>We will review it in December.</p></blockquote>
            <pre>let rate = 2\nprint(rate)</pre>
            <div class="reader-comments"><div class="article-body"><p>\(first) USER COMMENT MUST NOT APPEAR.</p></div></div>
            <div data-component="links-block"><h2>Related reports</h2><p><a href="/other">Other report headline</a>17 hours ago</p></div>
            <p><a href="/another">Another report headline about employment and the economy</a><span>1 day ago</span></p>
            <p>Sign up for our Economics newsletter to keep up with the news.</p>
            <div data-block="eventPromo"><p>PODCAST PROMOTION that does not belong in publisher prose.</p></div>
            <div data-block="topicList"><h2>Related topics</h2><p>Topic navigation that does not belong in publisher prose.</p></div>
            <div data-block="promoList"><h2>More on this story</h2><p>More publisher teasers that do not belong in the body.</p></div>
            <div data-block="uploaderEmbed"><h2>Get in touch</h2><p>What are your views on the triple lock?</p></div>
            <p>Listen to Newsbeat <a href="/sounds/play/live:bbc_radio_one">live</a> at 12:45 and 17:45 weekdays - or listen back <a href="/programmes/b006wkry/episodes/player">here</a>.</p>
            <p>Listen to Newsbeat was the instruction discussed by the researcher in the report.</p>
            <section class="commentary"><p>\(second) Editorial commentary belongs here.</p></section>
            </article></main>
            """
        let outcome = ContentExtractionPipeline.shared.extractFromHTML(html)
        guard case .success(let content, _, let document) = outcome, let document else {
            assertTrue(false, "Structured reader fixture must extract successfully")
            return
        }
        assertEqual(
            document.blocks.filter { $0.kind == .heading }.map(\.text), ["What changes?"],
            "Short publisher headings survive")
        assertEqual(
            document.blocks.filter { $0.kind == .listItem }.map(\.ordinal), [3, 4], "Ordered lists retain numbering")
        assertTrue(
            document.blocks.contains { $0.kind == .quote && $0.text.contains("stable.\nWe") },
            "Quote paragraphs keep their break")
        assertTrue(document.blocks.contains { $0.kind == .code && $0.text.contains("\n") }, "Code retains line breaks")
        for unwanted in [
            "USER COMMENT", "Other report", "Another report", "newsletter", "PODCAST", "Related topics",
            "More on this story", "Get in touch", "views on the triple lock", "17:45 weekdays",
        ] {
            assertFalse(content.contains(unwanted), "Publisher furniture excluded: \(unwanted)")
        }
        assertTrue(
            content.contains("instruction discussed by the researcher"),
            "Editorial references to a programme remain eligible")
        assertTrue(content.contains("Editorial commentary"), "Comment filtering must not remove editorial commentary")

        // #330: BBC's live layout wraps a newsletter banner and its signup prose in ordinary image and text blocks.
        func bbcBlock(_ kind: String, _ inner: String) -> String {
            "<div data-block=\"\(kind)\" class=\"ssrcss-vxwoax-ComponentWrapper\"><div class=\"ssrcss-126h8e-Spacer\">\(inner)</div></div>"
        }
        func bbcFigure(_ alt: String, _ caption: String) -> String {
            bbcBlock(
                "image",
                "<div data-testid=\"image\"><figure class=\"ssrcss-hc6arm-StyledFigure\"><div><span><picture>"
                    + "<img alt=\"\(alt)\" src=\"https://ichef.bbci.co.uk/ace/standard/976/cpsprodpb/\(caption.count)/live/photo.jpg\" width=\"976\" height=\"549\"/>"
                    + "</picture></span></div>\(caption.isEmpty ? "" : "<figcaption>\(caption)</figcaption>")</figure></div>"
            )
        }
        let bbcText = { (inner: String) in
            bbcBlock(
                "text",
                "<div data-testid=\"rich-text\"><div class=\"ssrcss-nqezkk-RichTextContainer\"><p>\(inner)</p></div></div>"
            )
        }
        let newsletterHTML =
            "<main><article>" + bbcText(first)
            + bbcFigure("Officials outside the central bank in London", "The bank's headquarters in the City of London")
            + bbcText(second)
            + bbcText(
                "A separate newsletter sent to investors last week warned that rates could rise again before the summer."
            )
            + bbcFigure(
                "A thin, grey banner promoting the US Politics Unspun newsletter. The banner reads: “The newsletter that cuts through the noise.”",
                "")
            + bbcText(
                "Follow the twists and turns with the US Politics Unspun newsletter. Readers in the UK can <a href=\"/newsletters/zgmn46f\">sign up here</a>. Those outside the UK can <a href=\"/news/articles/c2lkky9zngvo\">sign up here</a>."
            )
            + bbcText(
                "Sign up here to get the latest royal stories every week with our Royal Watch <a href=\"https://www.bbc.co.uk/newsletters/zkp3wsg\">newsletter</a>."
            )
            + "</article></main>"
        guard
            case .success(let newsletterContent, _, let newsletterDocument) = ContentExtractionPipeline.shared
                .extractFromHTML(newsletterHTML),
            let newsletterDocument
        else {
            assertTrue(false, "BBC newsletter fixture must extract successfully")
            return
        }
        let figures = newsletterDocument.blocks.filter { $0.kind == .figure }
        assertEqual(
            figures.map(\.imageAlt), ["Officials outside the central bank in London"],
            "Newsletter banners are removed; editorial figures stay")
        assertEqual(figures.first?.text, "The bank's headquarters in the City of London", "Editorial captions stay")
        for unwanted in ["Politics Unspun", "Royal Watch", "sign up"] {
            assertFalse(newsletterContent.contains(unwanted), "Plain text excludes newsletter signup: \(unwanted)")
            assertFalse(
                newsletterDocument.blocks.contains { $0.text.contains(unwanted) },
                "Structured reader excludes newsletter signup: \(unwanted)")
        }
        assertTrue(
            newsletterContent.contains("separate newsletter sent to investors"),
            "Editorial mentions of newsletters stay")
        let extremeList = HTMLDOMBuilder.parse(html: "<ol start='\(Int.max)'><li>First</li><li>Second</li></ol>")
        assertEqual(extremeList.readingBlocks().count, 2, "Untrusted extreme list numbering must not overflow")
        let tags = EntityResult.readerTags(from: [
            EntityResult(name: "Healey", type: .person), EntityResult(name: "John Healey", type: .person),
            EntityResult(name: " JOHN  HEALEY ", type: .person),
            EntityResult(name: "Stanford University", type: .organization),
            EntityResult(name: "AI on Employment Among Recent College Graduates", type: .unknown),
        ])
        assertEqual(
            tags.map(\.name), ["John Healey", "Stanford University"],
            "Tags resolve aliases and reject document-title fragments")
        let ambiguous = EntityResult.readerTags(from: [
            EntityResult(name: "Smith", type: .person), EntityResult(name: "John Smith", type: .person),
            EntityResult(name: "Jane Smith", type: .person),
        ])
        assertEqual(ambiguous.count, 3, "An ambiguous surname must not be merged into a guessed identity")

        let path = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-reader-\(UUID().uuidString).sqlite3"
        ).path
        defer { for suffix in ["", "-wal", "-shm"] { try? FileManager.default.removeItem(atPath: path + suffix) } }
        let database = DatabaseEngine(path: path)
        do {
            try await database.open()
            var article = FeedArticle(
                title: "Report", link: "https://example.com/structured", guid: "reader-structure",
                description: "Preview", pubDate: Date(), source: "Test", fullContent: content)
            try await database.upsertArticles([article])
            try await database.markRead(articleId: article.id, isRead: true)
            try await database.setSaved(articleId: article.id, isSaved: true)
            await database.close()
            var handle: OpaquePointer?
            assertEqual(sqlite3_open(path, &handle), SQLITE_OK, "Open migration fixture")
            assertEqual(
                sqlite3_exec(
                    handle,
                    "DROP TABLE article_reconciliation_history; DROP TABLE article_reconciliations; DROP TABLE article_aliases; DROP TABLE article_feeds; ALTER TABLE articles DROP COLUMN reader_document; ALTER TABLE article_enrichment DROP COLUMN key_points; ALTER TABLE article_enrichment DROP COLUMN category; ALTER TABLE article_enrichment DROP COLUMN confidence; ALTER TABLE article_enrichment DROP COLUMN model_identifier; ALTER TABLE article_enrichment DROP COLUMN analysis_version; PRAGMA user_version = 1;",
                    nil, nil, nil), SQLITE_OK, "Prepare v1 fixture")
            sqlite3_close(handle)
            try await database.open()
            let migrated = try await database.fetchArticles()
            assertEqual(migrated.first?.fullContent, content, "Migration preserves old body text")
            assertTrue(try await database.isSaved(articleId: article.id), "Migration preserves saved state")
            assertTrue(try await database.isRead(articleId: article.id), "Migration preserves read state")
            try await database.updateEnrichment(
                articleId: article.id, update: .init(content: content, readerDocument: document))
            article.fullContent = "A later feed teaser must not overwrite the extracted document."
            try await database.upsertArticles([article])
            await database.close()
            try await database.open()
            let restored = try await database.fetchArticles()
            assertEqual(restored.first?.readerDocument, document, "Reader structure survives reopen and feed refresh")
            assertEqual(restored.first?.fullContent, content, "Body and structure remain consistent after feed refresh")
            let search = try await database.searchArticles(query: "inflation")
            assertEqual(search.first?.readerDocument, document, "FTS results retain reader structure")
            await database.close()
        } catch {
            await database.close()
            assertTrue(false, "Structured persistence failed: \(error)")
        }
    }

    static func testURLNormalization() async {
        print("  - Testing URL Normalization...")

        let url1 = "https://example.com/story?utm_source=feed&utm_medium=rss&ref=share"
        assertEqual(
            ArticleIdentity.canonicalizeURL(url1), "https://example.com/story", "Should strip tracking query parameters"
        )

        let url2 = "https://example.com/path/"
        assertEqual(ArticleIdentity.canonicalizeURL(url2), "https://example.com/path", "Should strip trailing slashes")

        let url3 = "https://EXamPLE.COm/Path/"
        assertEqual(
            ArticleIdentity.canonicalizeURL(url3), "https://example.com/Path",
            "Should lowercase the host and strip trailing slash")

        let url4 = "http://example.com/path"
        assertEqual(ArticleIdentity.canonicalizeURL(url4), "https://example.com/path", "Should upgrade scheme to https")
    }

    static func testSSRFValidation() async {
        print("  - Testing SSRF block list...")

        assertTrue(FeedManager.isBlockedLocalAddress("localhost"), "Should block localhost")
        assertTrue(FeedManager.isBlockedLocalAddress("127.0.0.1"), "Should block 127.0.0.1")
        assertTrue(FeedManager.isBlockedLocalAddress("10.0.1.5"), "Should block private range 10.x")
        assertTrue(FeedManager.isBlockedLocalAddress("192.168.1.100"), "Should block private range 192.168.x")
        assertTrue(FeedManager.isBlockedLocalAddress("172.20.5.5"), "Should block private range 172.16-31.x")
        assertTrue(FeedManager.isBlockedLocalAddress("::1"), "Should block IPv6 loopback")
        assertTrue(FeedManager.isBlockedLocalAddress("fe80::1"), "Should block IPv6 link-local")

        assertTrue(FeedManager.isBlockedLocalAddress("192.0.0.88"), "Should block IETF special-use 192.0.0.0/24")
        // Hostname allowance depends on the local resolver, so it runs only with controlled network checks.
        if ProcessInfo.processInfo.environment["NEWS_LIVE_READER_CHECK"] == "1" {
            assertFalse(FeedManager.isBlockedLocalAddress("google.com"), "Should allow public hostnames")
        }
        assertFalse(FeedManager.isBlockedLocalAddress("8.8.8.8"), "Should allow public IPs")
        assertFalse(FeedManager.isBlockedLocalAddress("172.15.2.2"), "Should allow public range outside 172.16-31")
    }

    static func testIsBlockedIPv4() async {
        print("  - Testing isBlockedIPv4 directly...")

        func makeInAddr(_ ipString: String) -> in_addr {
            var sin = in_addr()
            inet_pton(AF_INET, ipString, &sin)
            return sin
        }

        // Loopback
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("127.0.0.1")) != nil, "127.0.0.1 must be blocked")

        // Current network
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("0.0.0.0")) != nil, "0.0.0.0 must be blocked")

        // Private
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("10.0.0.1")) != nil, "10.0.0.1 must be blocked")
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("172.16.0.1")) != nil, "172.16.0.1 must be blocked")
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("192.168.0.1")) != nil, "192.168.0.1 must be blocked")

        // Link-Local
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("169.254.0.1")) != nil, "169.254.0.1 must be blocked")

        // Carrier-Grade NAT
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("100.64.0.1")) != nil, "100.64.0.1 must be blocked")

        // Multicast
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("224.0.0.1")) != nil, "224.0.0.1 must be blocked")

        // Broadcast
        assertTrue(
            IPAddressValidator.isBlockedIPv4(makeInAddr("255.255.255.255")) != nil, "255.255.255.255 must be blocked")

        // Valid
        assertTrue(IPAddressValidator.isBlockedIPv4(makeInAddr("8.8.8.8")) == nil, "8.8.8.8 must be allowed")
    }

    static func testIPAddressValidatorDeep() async {
        print("  - Testing IPAddressValidator (IPv4, IPv6, mapped IPv6, DNS)...")

        for host in ["localhost", "printer.local", "127.0.0.1", "169.254.169.254", "[::1]"] {
            let result = IPAddressValidator.validateHost(
                host,
                resolver: { _ in
                    assertTrue(false, "Blocked destinations never reach an injected resolver")
                    return .allowed(ips: ["8.8.8.8"])
                })
            assertTrue(
                {
                    if case .blocked = result { return true }
                    return false
                }(), "Injected DNS cannot bypass hostname/literal guards")
        }
        for (host, address) in [("93.184.216.34", "93.184.216.34"), ("[2606:4700::1111]", "2606:4700::1111")] {
            let result = IPAddressValidator.validateHost(
                host,
                resolver: { _ in
                    assertTrue(false, "Public literals never depend on host DNS or configured address families")
                    return .unresolvable(reason: "No IPv4 interface configured")
                })
            assertEqual(result, .allowed(ips: [address]), "A public literal pins itself without resolution")
        }

        // 1. Literal IPv4 Loopback & Private
        assertTrue(IPAddressValidator.checkLiteralIP("127.0.0.1") != nil, "127.0.0.1 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("127.255.255.255") != nil, "127.255.255.255 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("0.0.0.0") != nil, "0.0.0.0 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("10.254.1.2") != nil, "10.254.1.2 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("172.16.0.1") != nil, "172.16.0.1 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("172.31.255.254") != nil, "172.31.255.254 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("192.168.0.1") != nil, "192.168.0.1 must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("169.254.169.254") != nil, "169.254.169.254 link-local must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("224.0.0.1") != nil, "224.0.0.1 multicast must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("255.255.255.255") != nil, "255.255.255.255 broadcast must be blocked")

        // 2. Allowed Public IPv4
        assertTrue(IPAddressValidator.checkLiteralIP("93.184.216.34") == nil, "example.com public IP must be allowed")
        assertTrue(IPAddressValidator.checkLiteralIP("1.1.1.1") == nil, "1.1.1.1 public IP must be allowed")
        assertTrue(IPAddressValidator.checkLiteralIP("8.8.8.8") == nil, "8.8.8.8 public IP must be allowed")

        // 3. Literal IPv6 Loopback, ULA, Link-Local
        assertTrue(IPAddressValidator.checkLiteralIP("::1") == "IPv6 loopback (::1)", "::1 must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("::") != nil, ":: must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("fe80::1") != nil, "fe80::1 link-local must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("fc00::1") != nil, "fc00::1 ULA must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("fd12:3456::1") != nil, "fd12:3456::1 ULA must be blocked")
        assertTrue(IPAddressValidator.checkLiteralIP("ff02::1") != nil, "ff02::1 multicast must be blocked")

        // 4. IPv4-mapped IPv6 normalization
        assertTrue(
            IPAddressValidator.checkLiteralIP("::ffff:127.0.0.1") != nil,
            "::ffff:127.0.0.1 mapped loopback must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("::ffff:192.168.1.1") != nil,
            "::ffff:192.168.1.1 mapped private must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("::ffff:10.0.0.1") != nil,
            "::ffff:10.0.0.1 mapped private must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("::ffff:93.184.216.34") == nil,
            "::ffff:93.184.216.34 mapped public must be allowed")

        // 5. NAT64 IPv6 normalization
        assertTrue(
            IPAddressValidator.checkLiteralIP("64:ff9b::127.0.0.1")
                == "NAT64 IPv6 (IPv4 loopback address (127.0.0.0/8))",
            "64:ff9b::127.0.0.1 NAT64 loopback must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("64:ff9b::192.168.1.1")
                == "NAT64 IPv6 (RFC 1918 private network (192.168.0.0/16))",
            "64:ff9b::192.168.1.1 NAT64 private must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("64:ff9b::10.0.0.1")
                == "NAT64 IPv6 (RFC 1918 private network (10.0.0.0/8))",
            "64:ff9b::10.0.0.1 NAT64 private must be blocked")
        assertTrue(
            IPAddressValidator.checkLiteralIP("64:ff9b::93.184.216.34") == nil,
            "64:ff9b::93.184.216.34 NAT64 public must be allowed")

        // 6. Hostname string validation
        if case .blocked = IPAddressValidator.validateHost("localhost") {
            // expected
        } else {
            print("❌ validateHost('localhost') was not blocked")
            exit(1)
        }

        if case .blocked = IPAddressValidator.validateHost("test.local") {
            // expected
        } else {
            print("❌ validateHost('test.local') was not blocked")
            exit(1)
        }

        if case .blocked = IPAddressValidator.validateHost("router.internal") {
            // expected
        } else {
            print("❌ validateHost('router.internal') was not blocked")
            exit(1)
        }

        // 7. Socket Address Validation (validateSocketAddress)
        var loopbackAddress = sockaddr_in()
        loopbackAddress.sin_family = sa_family_t(AF_INET)
        inet_pton(AF_INET, "127.0.0.1", &loopbackAddress.sin_addr)
        let blockedLoopback = withUnsafePointer(to: &loopbackAddress) { ptr -> String? in
            ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockaddrPtr in
                IPAddressValidator.validateSocketAddress(sockaddrPtr)
            }
        }
        assertTrue(blockedLoopback != nil, "127.0.0.1 socket address must be blocked")

        var publicAddress = sockaddr_in()
        publicAddress.sin_family = sa_family_t(AF_INET)
        inet_pton(AF_INET, "8.8.8.8", &publicAddress.sin_addr)
        let allowedPublic = withUnsafePointer(to: &publicAddress) { ptr -> String? in
            ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockaddrPtr in
                IPAddressValidator.validateSocketAddress(sockaddrPtr)
            }
        }
        assertTrue(allowedPublic == nil, "8.8.8.8 socket address must be allowed")

        var loopbackIPv6Address = sockaddr_in6()
        loopbackIPv6Address.sin6_family = sa_family_t(AF_INET6)
        inet_pton(AF_INET6, "::1", &loopbackIPv6Address.sin6_addr)
        let blockedLoopback6 = withUnsafePointer(to: &loopbackIPv6Address) { ptr -> String? in
            ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockaddrPtr in
                IPAddressValidator.validateSocketAddress(sockaddrPtr)
            }
        }
        assertTrue(blockedLoopback6 != nil, "::1 socket address must be blocked")

        var publicIPv6Address = sockaddr_in6()
        publicIPv6Address.sin6_family = sa_family_t(AF_INET6)
        inet_pton(AF_INET6, "2606:4700:4700::1111", &publicIPv6Address.sin6_addr)
        let allowedPublic6 = withUnsafePointer(to: &publicIPv6Address) { ptr -> String? in
            ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockaddrPtr in
                IPAddressValidator.validateSocketAddress(sockaddrPtr)
            }
        }
        assertTrue(allowedPublic6 == nil, "2606:4700:4700::1111 socket address must be allowed")

        var unsupportedAddress = sockaddr()
        unsupportedAddress.sa_family = sa_family_t(AF_UNIX)
        let allowedUnsupported = withUnsafePointer(to: &unsupportedAddress) { ptr -> String? in
            IPAddressValidator.validateSocketAddress(ptr)
        }
        assertTrue(allowedUnsupported == nil, "Unsupported family socket address must return nil")
    }

    static func testSecureHTTPClientFetchImage() async {
        print("  - Testing SecureHTTPClient fetchImage with MockURLProtocol...")

        // Setup custom configuration with MockURLProtocol
        let config = URLSessionConfiguration.default
        config.protocolClasses = [MockURLProtocol.self]
        let client = mockHTTPClient(configuration: config)

        let targetURL = URL(string: "https://reader.invalid/test-image.jpg")!

        // Test 1: Successful image fetch
        let mockData = Data(repeating: 0xAA, count: 1024)
        MockURLProtocol.requestHandler = { request in
            let response = HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: nil)!
            return (response, mockData)
        }

        do {
            let (data, response) = try await client.fetchImage(from: targetURL)
            assertEqual(data.count, 1024, "Should download exact mock bytes")
            assertEqual(response.statusCode, 200, "Should get 200 status code")
        } catch {
            print("❌ Unexpected error in fetchImage success test: \(error)")
            exit(1)
        }

        // #794: an http image address is requested over HTTPS instead of being refused.
        let requestedScheme = SocketObservation()
        MockURLProtocol.requestHandler = { request in
            requestedScheme.recordText(request.url?.scheme ?? "")
            let response = HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: nil)!
            return (response, mockData)
        }
        do {
            let (data, _) = try await client.fetchImage(from: URL(string: "http://reader.invalid/test-image.jpg")!)
            assertEqual(data.count, 1024, "An http image address still loads")
            assertEqual(requestedScheme.hosts, ["https"], "An http image address is requested over HTTPS")
        } catch {
            assertTrue(false, "An http image address is upgraded, not refused: \(error)")
        }
        assertEqual(
            SecureHTTPClient.upgradedToHTTPS(URL(string: "http://img.example:80/a.jpg?v=1")!).absoluteString,
            "https://img.example/a.jpg?v=1", "The upgrade drops the default http port and keeps the query")
        assertEqual(
            SecureHTTPClient.upgradedToHTTPS(URL(string: "https://img.example/a.jpg")!).absoluteString,
            "https://img.example/a.jpg", "An https image address is unchanged")

        // Test 2: Image too large
        let maxAllowed = Int(SecureHTTPClient.defaultImageLimit)
        let tooLargeDataSize = maxAllowed + 1024
        MockURLProtocol.requestHandler = { request in
            let response = HTTPURLResponse(
                url: request.url!,
                statusCode: 200,
                httpVersion: nil,
                headerFields: ["Content-Length": "\(tooLargeDataSize)"]
            )!
            let largeData = Data(repeating: 0xBB, count: tooLargeDataSize)
            return (response, largeData)
        }

        do {
            _ = try await client.fetchImage(from: targetURL)
            print("❌ Expected fetchImage to throw responseTooLarge error")
            exit(1)
        } catch let error as FeedError {
            if case .responseTooLarge(let bytes, let maxAllowedLimit) = error {
                assertEqual(Int(bytes), tooLargeDataSize, "Expected byte size in error")
                assertEqual(Int(maxAllowedLimit), maxAllowed, "Expected max limit in error")
            } else {
                print("❌ Expected responseTooLarge error, got: \(error)")
                exit(1)
            }
        } catch {
            print("❌ Unexpected error type: \(error)")
            exit(1)
        }

        // Cleanup MockURLProtocol state
        MockURLProtocol.requestHandler = nil
    }

    static func testSecureHTTPClientPolicies() async {
        print("  - Testing SecureHTTPClient security policies...")

        // 1. Insecure scheme rejection (e.g. file://, javascript://)
        do {
            _ = try await SecureHTTPClient.shared.fetchData(from: URL(string: "file:///etc/passwd")!, maxBytes: 1024)
            print("❌ file:///etc/passwd should have thrown an insecureScheme error")
            exit(1)
        } catch let err as FeedError {
            if case .insecureScheme = err {
                // expected
            } else {
                print("❌ Unexpected error for file scheme: \(err)")
                exit(1)
            }
        } catch {
            print("❌ Unexpected error type: \(error)")
            exit(1)
        }

        // 2. Blocked port rejection (e.g. port 22, port 6379)
        do {
            _ = try await SecureHTTPClient.shared.fetchData(
                from: URL(string: "https://example.com:22/feed")!, maxBytes: 1024)
            print("❌ Port 22 should have been blocked")
            exit(1)
        } catch let err as FeedError {
            if case .blockedPort(let p) = err {
                assertEqual(p, 22, "Should block port 22")
            } else {
                print("❌ Unexpected error for blocked port: \(err)")
                exit(1)
            }
        } catch {
            print("❌ Unexpected error: \(error)")
            exit(1)
        }

        // 3. Blocked host rejection (e.g. localhost)
        do {
            _ = try await SecureHTTPClient.shared.fetchData(
                from: URL(string: "https://localhost/feed")!, maxBytes: 1024)
            print("❌ https://localhost should have been blocked")
            exit(1)
        } catch let err as FeedError {
            if case .blockedHost = err {
                // expected
            } else {
                print("❌ Unexpected error for localhost: \(err)")
                exit(1)
            }
        } catch {
            print("❌ Unexpected error: \(error)")
            exit(1)
        }
    }

    static func testFeedErrorHierarchy() async {
        print("  - Testing FeedError localized descriptions...")

        let err1 = FeedError.malformedURL("bad-url")
        assertTrue(err1.errorDescription?.contains("Malformed URL") == true, "Malformed URL message")

        let err2 = FeedError.blockedHost(host: "evil.com", reason: "Private subnet")
        assertTrue(err2.errorDescription?.contains("evil.com") == true, "Blocked host message")

        let err3 = FeedError.responseTooLarge(bytes: 20 * 1024 * 1024, maxAllowed: 10 * 1024 * 1024)
        assertTrue(err3.errorDescription?.contains("20.0 MB exceeds 10.0 MB") == true, "Response too large message")

        let err4 = FeedError.dnsRebindingDetected(host: "rebind.example", ip: "127.0.0.1")
        assertTrue(err4.errorDescription?.contains("DNS rebinding") == true, "DNS rebinding message")
    }

