        assertEqual(AppLayout.sidebarInset, 12.0, "AppLayout.sidebarInset should be 12.0")
        assertEqual(AppLayout.cardGap, 16.0, "AppLayout.cardGap should be 16.0")
        assertEqual(AppLayout.readingMeasure, 720.0, "AppLayout.readingMeasure should be 720.0")
        assertEqual(AppLayout.listMaxWidth, 1000.0, "AppLayout.listMaxWidth should be 1000.0")
        assertEqual(AppLayout.gridColumnMinimum, 300.0, "AppLayout.gridColumnMinimum should be 300.0")
        assertEqual(AppLayout.gridColumnMaximum, 420.0, "AppLayout.gridColumnMaximum should be 420.0")
        assertEqual(AppSpacing.textStack, 2.0, "AppSpacing.textStack should be 2.0")
        assertEqual(AppSpacing.eyebrowGap, 6.0, "AppSpacing.eyebrowGap should be 6.0")
        assertEqual(AppTypography.eyebrowTracking, 0.5, "AppTypography.eyebrowTracking should be 0.5")

        // 4. Ghost Typography Theme tokens
        assertEqual(AppTypography.bodyLineSpacing(for: .casper), 10.0, "Casper theme line spacing should be 10")
        assertEqual(AppTypography.bodyLineSpacing(for: .edition), 8.0, "Edition theme line spacing should be 8")
        assertEqual(AppTypography.bodyLineSpacing(for: .alto), 12.0, "Alto theme line spacing should be 12")

        await testTagTextContrast()

        // 4. ArticleFilterQuery structured parsing
        let complexQuery = "source:Bloomberg category:Tech is:unread apple silicon"
        let parsed = ArticleFilterQuery.parse(complexQuery)
        assertEqual(parsed.sourceFilter, "bloomberg", "Should parse source: operator")
        assertEqual(parsed.categoryFilter, "tech", "Should parse category: operator")
        assertEqual(parsed.isReadFilter, false, "Should parse is:unread operator")
        assertEqual(parsed.terms, ["apple", "silicon"], "Should extract search terms")

        // 5. Article matching logic
        let art1 = FeedArticle(
            title: "Apple introduces M4 Max Silicon",
            link: "https://bloomberg.com/news/apple-m4",
            guid: "test-art-1",
            description: "New chip delivers record performance",
            pubDate: Date(),
            source: "Bloomberg",
            category: "Technology"
        )
        let art2 = FeedArticle(
            title: "Federal Reserve holds interest rates steady",
            link: "https://wsj.com/fed-rates",
            guid: "test-art-2",
            description: "Central bank maintains current policy stance",
            pubDate: Date(),
            source: "Wall Street Journal",
            category: "Economy"
        )

        assertTrue(parsed.matches(article: art1, isRead: false, isSaved: false), "Article 1 should match query")
        assertFalse(
            parsed.matches(article: art1, isRead: true, isSaved: false), "Article 1 should fail because it is read")
        assertFalse(
            parsed.matches(article: art2, isRead: false, isSaved: false), "Article 2 should fail source/terms match")

        // 6. Settings Pane Bounds and Section Header Tracking (#475)
        assertEqual(AppLayout.settingsPaneWidth, 720.0, "AppLayout.settingsPaneWidth should be 720.0")
        assertEqual(AppLayout.settingsPaneHeight, 560.0, "AppLayout.settingsPaneHeight should be 560.0")
        assertEqual(AppTypography.sectionHeaderTracking, 0.6, "AppTypography.sectionHeaderTracking should be 0.6")

        // 7. ArchiveSearchToken Semantic Display Names and Symbols (#475)
        let unreadToken = ArchiveSearchToken(completedExpression: "is:unread")!
        assertEqual(unreadToken.displayName, "Unread", "Unread token has display name Unread")
        assertEqual(unreadToken.systemImage, "circle.circle", "Unread token uses circle.circle")

        let readToken = ArchiveSearchToken(completedExpression: "is:read")!
        assertEqual(readToken.displayName, "Read", "Read token has display name Read")
        assertEqual(readToken.systemImage, "checkmark.circle", "Read token uses checkmark.circle")

        let savedToken = ArchiveSearchToken(completedExpression: "is:saved")!
        assertEqual(savedToken.displayName, "Saved", "Saved token has display name Saved")
        assertEqual(savedToken.systemImage, "bookmark", "Saved token uses bookmark")

        let sourceToken = ArchiveSearchToken(completedExpression: "source:reuters")!
        assertEqual(sourceToken.displayName, "Source: reuters", "Source token has formatted display name")
        assertEqual(sourceToken.systemImage, "newspaper", "Source token uses newspaper")

        let categoryToken = ArchiveSearchToken(completedExpression: "category:science")!
        assertEqual(categoryToken.displayName, "Category: science", "Category token has formatted display name")
        assertEqual(categoryToken.systemImage, "tag", "Category token uses tag")

        let fallbackToken = ArchiveSearchToken(expression: "custom:term")
        assertEqual(fallbackToken.displayName, "custom:term", "Fallback token keeps raw expression")
        assertEqual(fallbackToken.systemImage, "magnifyingglass", "Fallback token uses magnifyingglass")
    }

    static func testDistributionAndEntitlementsIntegrity() async {
        print("  - Testing Distribution, Entitlements & Privacy Manifest Integrity...")

        let fileManager = FileManager.default
        let currentDir = fileManager.currentDirectoryPath
        let entitlementsPath = (currentDir as NSString).appendingPathComponent("News.entitlements")

        assertTrue(fileManager.fileExists(atPath: entitlementsPath), "News.entitlements must exist in project root")
        for file in ["PrivacyInfo.xcprivacy", "container-migration.plist"] {
            let data = fileManager.contents(atPath: (currentDir as NSString).appendingPathComponent(file))
            let plist = data.flatMap { try? PropertyListSerialization.propertyList(from: $0, options: [], format: nil) }
            assertTrue(plist is [String: Any], "Distribution manifest must be a valid property list: \(file)")
        }

        assertEqual(
            Int64(NotificationService.attachmentLimit), SecureHTTPClient.defaultImageLimit,
            "The notification attachment ceiling equals the image fetch limit")

        guard let data = fileManager.contents(atPath: entitlementsPath) else {
            assertEqual(true, false, "Failed to read News.entitlements data")
            return
        }

        do {
            guard
                let plist = try PropertyListSerialization.propertyList(from: data, options: [], format: nil)
                    as? [String: Any]
            else {
                assertEqual(true, false, "News.entitlements is not a valid dictionary plist")
                return
            }

            assertEqual(plist["com.apple.security.app-sandbox"] as? Bool, true, "Sandbox must be enabled")
            // Validate minimal required entitlements
            assertEqual(
                plist["com.apple.security.network.client"] as? Bool, true,
                "com.apple.security.network.client must be enabled")
            assertEqual(
                plist["com.apple.security.files.user-selected.read-write"] as? Bool, true,
                "com.apple.security.files.user-selected.read-write must be enabled")

            // Validate that unnecessary/unsafe entitlements are NOT present
            assertEqual(
                plist["com.apple.security.network.server"] as? Bool, true,
                "Loopback gateway requires listener permission")
            assertFalse(
                plist.keys.contains("com.apple.security.device.camera"), "Camera entitlement should not be granted")
            assertFalse(
                plist.keys.contains("com.apple.security.device.microphone"),
                "Microphone entitlement should not be granted")
            assertFalse(
                plist.keys.contains("com.apple.security.personal-information.location"),
                "Location entitlement should not be granted")
            assertFalse(
                plist.keys.contains("com.apple.security.personal-information.addressbook"),
                "Contacts entitlement should not be granted")
            assertFalse(
                plist.keys.contains("com.apple.security.files.all"), "All files entitlement should not be granted")
        } catch {
            assertEqual(true, false, "Failed to parse News.entitlements: \(error)")
        }

        // Validate release packaging files exist
        let releaseBuildScript = (currentDir as NSString).appendingPathComponent("build_release.sh")
        let packageDmgScript = (currentDir as NSString).appendingPathComponent("script/distribution/package_dmg.sh")
        let notarizeScript = (currentDir as NSString).appendingPathComponent("script/distribution/notarize.sh")
        let packageSwift = (currentDir as NSString).appendingPathComponent("Package.swift")
        let privacyDoc = (currentDir as NSString).appendingPathComponent("PRIVACY.md")

        assertTrue(fileManager.fileExists(atPath: releaseBuildScript), "build_release.sh must exist")
        assertTrue(fileManager.isExecutableFile(atPath: releaseBuildScript), "build_release.sh must be executable")

        assertTrue(fileManager.fileExists(atPath: packageDmgScript), "package_dmg.sh must exist")
        assertTrue(fileManager.isExecutableFile(atPath: packageDmgScript), "package_dmg.sh must be executable")

        assertTrue(fileManager.fileExists(atPath: notarizeScript), "notarize.sh must exist")
        assertTrue(fileManager.isExecutableFile(atPath: notarizeScript), "notarize.sh must be executable")

        assertTrue(fileManager.fileExists(atPath: packageSwift), "Package.swift must exist")
        assertTrue(fileManager.fileExists(atPath: privacyDoc), "PRIVACY.md must exist")
    }

    static func testStrictSemVerAndReleaseSecurity() async {
        print("  - Testing Strict SemVer Parsing & Release URL Security...")

        // 1. Valid SemVer strings
        assertEqual(
            SemanticVersion.parse("v2.0.1"), SemanticVersion(major: 2, minor: 0, patch: 1), "v2.0.1 should parse")
        assertEqual(SemanticVersion.parse("2.0.1"), SemanticVersion(major: 2, minor: 0, patch: 1), "2.0.1 should parse")
        assertEqual(
            SemanticVersion.parse("10.12.3"), SemanticVersion(major: 10, minor: 12, patch: 3), "10.12.3 should parse")
        assertEqual(SemanticVersion.parse("0.1.0"), SemanticVersion(major: 0, minor: 1, patch: 0), "0.1.0 should parse")
        assertEqual(
            SemanticVersion.parse("v0.0.1"), SemanticVersion(major: 0, minor: 0, patch: 1), "v0.0.1 should parse")

        // 2. Invalid tags should be rejected (ignored)
        assertEqual(SemanticVersion.parse("release-2.0.1"), nil, "release- prefix should be rejected")
        assertEqual(SemanticVersion.parse("v2.0"), nil, "Missing patch should be rejected")
        assertEqual(SemanticVersion.parse("2"), nil, "Single integer should be rejected")
        assertEqual(SemanticVersion.parse("foo"), nil, "Arbitrary string should be rejected")
        assertEqual(SemanticVersion.parse("v2.0.1-beta"), nil, "Non-numeric suffix should be rejected")

        // 3. Leading zeros must be rejected per SemVer 2.0.0
        assertEqual(SemanticVersion.parse("001.002.003"), nil, "Components with leading zeros must be rejected")
        assertEqual(SemanticVersion.parse("01.0.0"), nil, "Major with leading zero must be rejected")
        assertEqual(SemanticVersion.parse("1.02.0"), nil, "Minor with leading zero must be rejected")
        assertEqual(SemanticVersion.parse("1.0.03"), nil, "Patch with leading zero must be rejected")

        // 4. Numeric tuple comparison
        assertTrue(
            SemanticVersion(major: 2, minor: 0, patch: 1) > SemanticVersion(major: 2, minor: 0, patch: 0),
            "2.0.1 > 2.0.0")
        assertTrue(
            SemanticVersion(major: 2, minor: 1, patch: 0) > SemanticVersion(major: 2, minor: 0, patch: 9),
            "2.1.0 > 2.0.9")
        assertTrue(
            SemanticVersion(major: 3, minor: 0, patch: 0) > SemanticVersion(major: 2, minor: 9, patch: 9),
            "3.0.0 > 2.9.9")
        assertFalse(
            SemanticVersion(major: 2, minor: 0, patch: 0) > SemanticVersion(major: 2, minor: 0, patch: 1),
            "2.0.0 is not > 2.0.1")
        assertEqual(
            SemanticVersion(major: 2, minor: 0, patch: 0), SemanticVersion(major: 2, minor: 0, patch: 0),
            "Equality check")

        // 5. Release URL Domain & Path Prefix Security
        let validURL1 = URL(string: "https://github.com/marspater/NewsApp-macOS/releases/tag/v2.1.0")!
        let validURL2 = URL(string: "https://github.com/marspater/NewsApp-macOS/releases/latest")!
        let validURL3 = URL(string: "https://github.com/marspater/NewsApp-macOS/releases")!
        let invalidPrefix = URL(string: "https://github.com/marspater/NewsApp-macOS/releasesomething")!
        let invalidScheme = URL(string: "http://github.com/marspater/NewsApp-macOS/releases/tag/v2.1.0")!
        let evilDomain = URL(string: "https://evil-github.com/marspater/NewsApp-macOS/releases/tag/v2.1.0")!
        let otherRepo = URL(string: "https://github.com/malicious/phishing/releases/tag/v2.1.0")!

        assertTrue(UpdateChecker.isValidReleaseURL(validURL1), "Valid release URL should be approved")
        assertTrue(UpdateChecker.isValidReleaseURL(validURL2), "Valid latest URL should be approved")
        assertTrue(UpdateChecker.isValidReleaseURL(validURL3), "Exact releases URL should be approved")
        assertFalse(UpdateChecker.isValidReleaseURL(invalidPrefix), "Sibling path /releasesomething must be rejected")
        assertFalse(UpdateChecker.isValidReleaseURL(invalidScheme), "Insecure HTTP release URL must be rejected")
        assertFalse(UpdateChecker.isValidReleaseURL(evilDomain), "Spoofed domain must be rejected")
        assertFalse(UpdateChecker.isValidReleaseURL(otherRepo), "Non-matching repository path must be rejected")
    }

    @MainActor
    static func testUpdateCheckerThrottleWithClock() async {
        print("  - Testing UpdateChecker 6-Hour Throttle Advancement with TestClock...")

        let baseEpoch = Date(timeIntervalSince1970: 1_700_000_000)
        let testClock = TestClock(baseEpoch)

        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [MockURLProtocol.self]
        let testClient = mockHTTPClient(configuration: config)
        defer { MockURLProtocol.requestHandler = nil }

        var networkRequestCount = 0
        let makeReleasePayload: (String) -> Data = { versionTag in
            let payload = GitHubReleasePayload(
                tagName: versionTag,
                name: "Release \(versionTag)",
                htmlUrl: "https://github.com/marspater/NewsApp-macOS/releases/tag/\(versionTag)",
                body: "Release notes for \(versionTag)",
                publishedAt: nil
            )
            return try! JSONEncoder().encode(payload)
        }

        let checker = UpdateChecker(
            httpClient: testClient,
            now: { testClock.now },
            currentAppVersion: "2.0.0"
        )

        // 1. Initial check updates lastCheckDate
        assertTrue(checker.lastCheckDate == nil, "Initial checker has nil lastCheckDate")
        MockURLProtocol.requestHandler = { request in
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.0.0")
            )
        }
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 1, "Initial automatic check executes network request")
        assertEqual(checker.lastCheckDate, baseEpoch, "Initial check sets lastCheckDate to clock.now")
        assertFalse(checker.updateAvailable, "v2.0.0 matches currentAppVersion 2.0.0 -> no update")
        assertEqual(checker.statusMessage, "NewsApp is up to date (v2.0.0)", "Status confirms up to date")

        // 2. Check at +5h59m is skipped (throttled)
        testClock.advance(by: (5 * 3600) + (59 * 60))  // +21,540s
        MockURLProtocol.requestHandler = { _ in
            assertTrue(false, "Throttled automatic check within 6 hours must not make network request")
            throw URLError(.cancelled)
        }
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 1, "Network request count remains 1 (skipped)")
        assertEqual(checker.lastCheckDate, baseEpoch, "lastCheckDate remains baseEpoch when throttled")

        // 3. User-initiated check at +5h59m executes immediately
        let userCheckTime = testClock.now
        MockURLProtocol.requestHandler = { request in
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.0.0")
            )
        }
        await checker.checkForUpdates(userInitiated: true)
        assertEqual(networkRequestCount, 2, "User-initiated check bypasses 6-hour throttle")
        assertEqual(checker.lastCheckDate, userCheckTime, "User check updates lastCheckDate to current time")

        // 4. Automatic check at +6h01m executes
        testClock.advance(by: (6 * 3600) + 60)  // +21,660s past userCheckTime
        let nextCheckTime = testClock.now
        MockURLProtocol.requestHandler = { request in
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.0.0")
            )
        }
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 3, "Automatic check after 6h01m executes network request")
        assertEqual(checker.lastCheckDate, nextCheckTime, "lastCheckDate updates to new check time")

        // 5. Automatic check when update is available updates state non-modally
        testClock.advance(by: (6 * 3600) + 1)
        let updateCheckTime = testClock.now
        MockURLProtocol.requestHandler = { request in
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.1.0")
            )
        }
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 4, "Automatic check after 6h executes network request")
        assertEqual(checker.lastCheckDate, updateCheckTime, "lastCheckDate updates on successful update detection")
        assertTrue(checker.updateAvailable, "Automatic check detects newer release v2.1.0")
        assertEqual(checker.latestVersionString, "v2.1.0", "Latest version string set")
        assertEqual(checker.statusMessage, "Version v2.1.0 available", "Status indicates version available")
        assertEqual(
            checker.verifiedReleaseURL?.absoluteString,
            "https://github.com/marspater/NewsApp-macOS/releases/tag/v2.1.0", "Release URL verified")
    }

    @MainActor
    static func testUpdateCheckerVersionComparisonAndErrors() async {
        print("  - Testing UpdateChecker Version Comparison Against Release 2.0.0 & Error States...")

        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [MockURLProtocol.self]
        let testClient = mockHTTPClient(configuration: config)
        defer { MockURLProtocol.requestHandler = nil }

        let basePayload = { (tag: String, url: String) in
            GitHubReleasePayload(
                tagName: tag,
                name: "Release \(tag)",
                htmlUrl: url,
                body: "Release notes for \(tag)",
                publishedAt: "2026-10-25T12:00:00Z"
            )
        }

        // 1. Local 2.0.0 vs Remote 2.0.0 -> Up to date (updateAvailable == false)
        do {
            let payload = basePayload("2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Local 2.0.0 vs Remote 2.0.0 must report up to date")
            assertEqual(checker.statusMessage, "NewsApp is up to date (v2.0.0)", "Status confirms up to date")
            assertTrue(checker.verifiedReleaseURL == nil, "Release URL is nil when up to date")
            assertTrue(checker.latestVersionString == nil, "Version string is nil when up to date")
        }

        // 1b. Local 2.0.0 vs Remote v2.0.0 (with 'v' prefix) -> Up to date
        do {
            let payload = basePayload("v2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/v2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Local 2.0.0 vs Remote v2.0.0 must report up to date")
            assertEqual(
                checker.statusMessage, "NewsApp is up to date (v2.0.0)", "Status confirms up to date for v2.0.0")
        }

        // 2. Local 1.9.0 vs Remote 2.0.0 -> Update available (updateAvailable == true)
        do {
            let payload = basePayload("2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "1.9.0")
            await checker.checkForUpdates(userInitiated: true)
            assertTrue(checker.updateAvailable, "Local 1.9.0 vs Remote 2.0.0 must report update available")
            assertEqual(checker.latestVersionString, "2.0.0", "Latest version is 2.0.0")
            assertEqual(checker.releaseNotes, "Release notes for 2.0.0", "Release notes captured")
            assertEqual(
                checker.verifiedReleaseURL?.absoluteString,
                "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0", "Release URL matches")
            assertEqual(checker.statusMessage, "Version 2.0.0 available", "Status message indicates update")
        }

        // 2b. Local 1.9.9 vs Remote v2.0.0 -> Update available
        do {
            let payload = basePayload("v2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/v2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "1.9.9")
            await checker.checkForUpdates(userInitiated: true)
            assertTrue(checker.updateAvailable, "Local 1.9.9 vs Remote v2.0.0 must report update available")
            assertEqual(checker.latestVersionString, "v2.0.0", "Latest version is v2.0.0")
            assertEqual(
                checker.statusMessage, "Version v2.0.0 available", "Status message indicates update for v2.0.0")
        }

        // 3. Local 2.1.0 vs Remote 2.0.0 -> Up to date (updateAvailable == false)
        do {
            let payload = basePayload("2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.1.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Local 2.1.0 vs Remote 2.0.0 must report up to date")
            assertEqual(
                checker.statusMessage, "NewsApp is up to date (v2.1.0)", "Status confirms up to date for 2.1.0")
            assertTrue(checker.verifiedReleaseURL == nil, "Release URL is nil when 2.1.0 is up to date")
        }

        // 3b. Local 2.0.1 vs Remote 2.0.0 -> Up to date (updateAvailable == false)
        do {
            let payload = basePayload("2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.1")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Local 2.0.1 vs Remote 2.0.0 must report up to date")
            assertEqual(
                checker.statusMessage, "NewsApp is up to date (v2.0.1)", "Status confirms up to date for 2.0.1")
        }

        // 4. Remote Invalid SemVer Tags (Leading zeros, non-conforming formats)
        let invalidTags = [
            "02.0.0",  // leading zero in major
            "2.00.0",  // leading zero in minor
            "2.0.01",  // leading zero in patch
            "001.002.003",  // leading zeros in all parts
            "release-2.0.0",  // non-conforming prefix
            "v2.0",  // missing patch
            "2",  // single integer
            "v2.0.0-beta",  // non-numeric suffix
            "2.0.0-rc1",  // prerelease string
            "foo",  // arbitrary string
            "2..0",  // empty component
        ]

        for invalidTag in invalidTags {
            let payload = basePayload(
                invalidTag, "https://github.com/marspater/NewsApp-macOS/releases/tag/\(invalidTag)")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "1.9.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(
                checker.updateAvailable, "Invalid remote tag '\(invalidTag)' must not flag update available")
            assertEqual(checker.statusMessage, "No valid updates found", "Status indicates no valid updates")
            assertTrue(checker.latestVersionString == nil, "Latest version is nil for invalid SemVer")
            assertTrue(checker.verifiedReleaseURL == nil, "Release URL is nil for invalid SemVer")
        }

        // 5. Local Invalid SemVer (Configuration error)
        do {
            let payload = basePayload("2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0-beta")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Invalid local version must not flag update available")
            assertEqual(
                checker.statusMessage, "App version configuration error",
                "Status indicates configuration error for invalid local version")
        }

        // 6. Network Failure State: HTTP 404 (No published release available)
        do {
            MockURLProtocol.requestHandler = { request in
                (HTTPURLResponse(url: request.url!, statusCode: 404, httpVersion: nil, headerFields: nil)!, Data())
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "404 response must not flag update available")
            assertEqual(
                checker.statusMessage, "No published release is available to compare.",
                "Status indicates 404 missing release")
            assertTrue(checker.lastCheckDate != nil, "404 updates lastCheckDate to throttle retries")
        }

        // 7. Network Failure State: HTTP 500 / 503
        do {
            MockURLProtocol.requestHandler = { request in
                (HTTPURLResponse(url: request.url!, statusCode: 503, httpVersion: nil, headerFields: nil)!, Data())
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "503 response must not flag update available")
            assertEqual(
                checker.statusMessage, "Update check failed (HTTP 503)", "Status indicates HTTP 503")
        }

        // 8. Network Failure State: Payload > 1MB via Content-Length header
        do {
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json", "Content-Length": "1048577"])!,
                    Data()
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Oversized Content-Length must not flag update available")
            assertEqual(
                checker.statusMessage, "Unable to check for updates",
                "Status indicates oversized response rejected")
        }

        // 8b. Network Failure State: Payload > 1MB via streaming body
        do {
            let oversizedData = Data(repeating: 0x20, count: 1024 * 1024 + 1)
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    oversizedData
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Oversized stream must not flag update available")
            assertEqual(
                checker.statusMessage, "Unable to check for updates",
                "Status indicates oversized stream rejected")
        }

        // 9. Network Failure State: Timeout
        do {
            MockURLProtocol.requestHandler = { _ in
                throw URLError(.timedOut)
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Timeout must not flag update available")
            assertEqual(
                checker.statusMessage, "Unable to check for updates", "Status indicates timeout")
        }

        // 10. Content-Type Mismatch: Non-JSON response
        do {
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "text/html"])!,
                    Data("<html>Portal</html>".utf8)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "2.0.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "HTML content type must be rejected")
            assertEqual(
                checker.statusMessage, "Invalid response content type", "Status indicates HTML rejected")
        }

        // 11. Untrusted Release URL Security
        do {
            let maliciousPayload = basePayload("2.0.0", "https://malicious.example.com/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(maliciousPayload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "1.9.0")
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Untrusted release URL must not be accepted")
            assertEqual(
                checker.statusMessage, "Received untrusted release URL",
                "Status indicates untrusted release URL rejected")
            assertTrue(checker.verifiedReleaseURL == nil, "Untrusted release URL is not stored")
        }

        // 12. State Cleanup on Failure: Stale availability reset
        do {
            let payload = basePayload("2.0.0", "https://github.com/marspater/NewsApp-macOS/releases/tag/2.0.0")
            MockURLProtocol.requestHandler = { request in
                (
                    HTTPURLResponse(
                        url: request.url!, statusCode: 200, httpVersion: nil,
                        headerFields: ["Content-Type": "application/json"])!,
                    try! JSONEncoder().encode(payload)
                )
            }
            let checker = UpdateChecker(httpClient: testClient, currentAppVersion: "1.9.0")
            await checker.checkForUpdates(userInitiated: true)
            assertTrue(checker.updateAvailable, "Initial check finds update available")

            MockURLProtocol.requestHandler = { _ in throw URLError(.timedOut) }
            await checker.checkForUpdates(userInitiated: true)
            assertFalse(checker.updateAvailable, "Failed subsequent check clears updateAvailable")
            assertTrue(checker.verifiedReleaseURL == nil, "Release URL cleared after failure")
            assertTrue(
                checker.latestVersionString == nil, "Latest version cleared after failure")
        }
    }

    @MainActor
    static func testUpdateCheckerAdversarialEdgeCases() async {
        print("  - Testing UpdateChecker Adversarial Edge Cases (Time Leaps, Concurrency, Loops)...")

        let baseEpoch = Date(timeIntervalSince1970: 1_700_000_000)
        let testClock = TestClock(baseEpoch)

        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [MockURLProtocol.self]
        let testClient = mockHTTPClient(configuration: config)
        defer { MockURLProtocol.requestHandler = nil }

        var networkRequestCount = 0
        let makeReleasePayload: (String) -> Data = { versionTag in
            let payload = GitHubReleasePayload(
                tagName: versionTag,
                name: "Release \(versionTag)",
                htmlUrl: "https://github.com/marspater/NewsApp-macOS/releases/tag/\(versionTag)",
                body: "Release notes for \(versionTag)",
                publishedAt: nil
            )
            return try! JSONEncoder().encode(payload)
        }

        MockURLProtocol.requestHandler = { request in
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.0.0")
            )
        }

        let checker = UpdateChecker(
            httpClient: testClient,
            now: { testClock.now },
            currentAppVersion: "2.0.0"
        )

        // Baseline initial check
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 1, "Baseline automatic check succeeds")
        assertEqual(checker.lastCheckDate, baseEpoch, "lastCheckDate is set to baseEpoch")

        // ====================================================================
        // 1. Time Leaps Backwards (DST rollback, clock drift, NTP adjustments)
        // ====================================================================

        // 1a. Clock drifts 1 hour backwards (DST rollback)
        testClock.advance(by: -3600)
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 1, "Automatic check is throttled during 1-hour backward DST drift")
        assertEqual(checker.lastCheckDate, baseEpoch, "lastCheckDate remains unchanged during backward drift")

        // Clock advances to 6h01m past baseEpoch (+25261s from current -1h time)
        testClock.advance(by: 3600 + 21601)
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 2, "Automatic check executes once clock advances past 6-hour threshold")

        // 1b. Severe backward leap (30 days in the past)
        testClock.advance(by: -(30 * 86400))
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 2, "Automatic check is throttled during large backward leap")

        // User manual check bypasses throttle and resynchronizes lastCheckDate to rolled-back clock
        let rolledBackTime = testClock.now
        await checker.checkForUpdates(userInitiated: true)
        assertEqual(networkRequestCount, 3, "User-initiated check executes and resets lastCheckDate")
        assertEqual(checker.lastCheckDate, rolledBackTime, "lastCheckDate matches current rolled-back clock")

        // Check within 6 hours of new rolled-back time is throttled
        testClock.advance(by: 3600)
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 3, "Subsequent check is throttled relative to resynchronized clock")

        // ====================================================================
        // 2. Time Leaps Far Forward (30 days, 10 years)
        // ====================================================================

        // 2a. Leap 30 days forward
        testClock.advance(by: 30 * 86400)
        let forward30Time = testClock.now
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 4, "Automatic check executes after 30-day forward leap")
        assertEqual(checker.lastCheckDate, forward30Time, "lastCheckDate updates to 30-day future date")

        // Check 1 minute later is throttled
        testClock.advance(by: 60)
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 4, "Check 1 minute after 30-day leap is throttled")

        // 2b. Leap 10 years forward
        testClock.advance(by: 10 * 365 * 86400)
        let forward10yTime = testClock.now
        await checker.checkForUpdates(userInitiated: false)
        assertEqual(networkRequestCount, 5, "Automatic check executes after 10-year leap without overflow")
        assertEqual(checker.lastCheckDate, forward10yTime, "lastCheckDate updates to 10-year future date")

        // ====================================================================
        // 3. Rapid Successive Checks
        // ====================================================================

        let countBeforeLoop = networkRequestCount
        for _ in 0..<100 {
            await checker.checkForUpdates(userInitiated: false)
        }
        assertEqual(networkRequestCount, countBeforeLoop, "Rapid automatic checks in tight loop are 100% throttled")

        for _ in 0..<5 {
            await checker.checkForUpdates(userInitiated: true)
        }
        assertEqual(networkRequestCount, countBeforeLoop + 5, "Rapid sequential manual checks bypass throttle")

        // ====================================================================
        // 4. Concurrent Checks & In-Flight Gate Deduplication
        // ====================================================================

        testClock.advance(by: 7 * 3600)  // Expire throttle
        let gateSemaphore = DispatchSemaphore(value: 0)

        MockURLProtocol.requestHandler = { request in
            _ = gateSemaphore.wait(timeout: .now() + 5.0)
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.1.0")
            )
        }

        // Launch background check task
        let inFlightTask = Task { @MainActor in
            await checker.checkForUpdates(userInitiated: false)
        }

        // Wait until task is suspended waiting on gateSemaphore
        for _ in 0..<100 {
            if checker.isChecking { break }
            try? await Task.sleep(nanoseconds: 5_000_000)
        }
        assertTrue(checker.isChecking, "isChecking is true while in-flight network call is pending")
        assertEqual(checker.statusMessage, "Checking for updates...", "statusMessage indicates checking in-flight")

        // Concurrent automatic check while in-flight returns immediately without duplicate network call
        await checker.checkForUpdates(userInitiated: false)

        // Concurrent user-initiated check while in-flight also returns immediately
        await checker.checkForUpdates(userInitiated: true)

        // Release the network mock
        gateSemaphore.signal()
        _ = await inFlightTask.value

        assertFalse(checker.isChecking, "isChecking is false after in-flight check completes")
        assertTrue(checker.updateAvailable, "Update detected by in-flight check")
        assertEqual(
            networkRequestCount, countBeforeLoop + 6, "In-flight deduplication prevented duplicate network calls")

        // ====================================================================
        // 5. Immediate Foregrounding Loops
        // ====================================================================

        testClock.advance(by: 7 * 3600)  // Expire throttle
        MockURLProtocol.requestHandler = { request in
            networkRequestCount += 1
            return (
                HTTPURLResponse(
                    url: request.url!,
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: ["Content-Type": "application/json"]
                )!,
                makeReleasePayload("v2.1.0")
            )
        }

        // Simulate 20 foreground events fired concurrently
        await withTaskGroup(of: Void.self) { group in
            for _ in 0..<20 {
                group.addTask { @MainActor in
                    await checker.checkForUpdates(userInitiated: false)
                }
            }
        }
        assertEqual(
            networkRequestCount, countBeforeLoop + 7,
            "20 concurrent foregrounding events produce exactly 1 network request")
    }

    @MainActor
    static func testNewsURLParserAndSchemeRouting() async {
        print("  - Testing NewsURLParser URL Schemes, Insecure HTTP Gating, and Deep Linking...")

        // 1. Standard feed:// scheme normalizes to https://
        let u1 = URL(string: "feed://example.com/rss.xml")!
        let d1 = NewsURLParser.parse(url: u1, allowInsecureHTTP: false)
        assertEqual(
            d1, .addFeed(url: URL(string: "https://example.com/rss.xml")!),
            "Standard feed:// normalizes to https://")

        // 2. feed:https:// scheme
        let u2 = URL(string: "feed:https://example.com/feed.atom")!
        let d2 = NewsURLParser.parse(url: u2, allowInsecureHTTP: false)
        assertEqual(
            d2, .addFeed(url: URL(string: "https://example.com/feed.atom")!),
            "feed:https:// normalizes cleanly")

        // 3. feed://https:// double-slash composite scheme
        let u3 = URL(string: "feed://https://example.com/feed.atom")!
        let d3 = NewsURLParser.parse(url: u3, allowInsecureHTTP: false)
        assertEqual(
            d3, .addFeed(url: URL(string: "https://example.com/feed.atom")!),
            "feed://https:// normalizes cleanly")

        // 4. Insecure HTTP upgrade when allowInsecureHTTP is false
        let u4 = URL(string: "feed:http://insecure.example.com/rss")!
        let d4 = NewsURLParser.parse(url: u4, allowInsecureHTTP: false)
        assertEqual(
            d4, .addFeed(url: URL(string: "https://insecure.example.com/rss")!),
            "feed:http:// upgraded to https:// when insecure HTTP disallowed")

        let u4b = URL(string: "feed://http://insecure.example.com/rss")!
        let d4b = NewsURLParser.parse(url: u4b, allowInsecureHTTP: false)
        assertEqual(
            d4b, .addFeed(url: URL(string: "https://insecure.example.com/rss")!),
            "feed://http:// upgraded to https:// when insecure HTTP disallowed")

        // 5. Insecure HTTP preserved when allowInsecureHTTP is true
        let u5 = URL(string: "feed:http://insecure.example.com/rss")!
        let d5 = NewsURLParser.parse(url: u5, allowInsecureHTTP: true)
        assertEqual(
            d5, .addFeed(url: URL(string: "http://insecure.example.com/rss")!),
            "feed:http:// preserved when insecure HTTP allowed")

        let u5b = URL(string: "feed://http://insecure.example.com/rss")!
        let d5b = NewsURLParser.parse(url: u5b, allowInsecureHTTP: true)
        assertEqual(
            d5b, .addFeed(url: URL(string: "http://insecure.example.com/rss")!),
            "feed://http:// preserved when insecure HTTP allowed")

        // 6. Slashed feeds retain meaningful trailing slash
        let u6 = URL(string: "feed://example.com/feed/")!
        let d6 = NewsURLParser.parse(url: u6, allowInsecureHTTP: false)
        assertEqual(
            d6, .addFeed(url: URL(string: "https://example.com/feed/")!),
            "Meaningful trailing slash preserved")

        // 7. Feeds with custom ports
        let u7 = URL(string: "feed://example.com:8080/feed.xml")!
        let d7 = NewsURLParser.parse(url: u7, allowInsecureHTTP: false)
        assertEqual(
            d7, .addFeed(url: URL(string: "https://example.com:8080/feed.xml")!),
            "Port 8080 preserved in normalized feed URL")

        // 8. Story deep linking: news://story/<id>
        let u8 = URL(string: "news://story/story-uuid-1234")!
        let d8 = NewsURLParser.parse(url: u8, allowInsecureHTTP: false)
        assertEqual(
            d8, .story(id: "story-uuid-1234"),
            "news://story/<id> extracts story ID")

        // 9. Story deep linking with trailing slash
        let u9 = URL(string: "news://story/story-uuid-5678/")!
        let d9 = NewsURLParser.parse(url: u9, allowInsecureHTTP: false)
        assertEqual(
            d9, .story(id: "story-uuid-5678"),
            "Trailing slash trimmed from story ID")

        // 10. Story deep linking with percent encoding
        let u10 = URL(string: "news://story/story%20id%20with%20spaces")!
        let d10 = NewsURLParser.parse(url: u10, allowInsecureHTTP: false)
        assertEqual(
            d10, .story(id: "story id with spaces"),
            "Percent-encoded story ID decoded")

        // 11. Malformed and empty feeds safely rejected
        assertEqual(NewsURLParser.parse(urlString: "feed:", allowInsecureHTTP: false), nil, "Bare feed: rejected")
        assertEqual(NewsURLParser.parse(urlString: "feed://", allowInsecureHTTP: false), nil, "Bare feed:// rejected")
        assertEqual(NewsURLParser.parse(urlString: "feed:///", allowInsecureHTTP: false), nil, "Bare feed:/// rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "feed://   ", allowInsecureHTTP: false), nil, "Whitespace feed rejected")

        // 12. Disallowed protocols rejected
        assertEqual(
            NewsURLParser.parse(urlString: "feed:javascript:alert(1)", allowInsecureHTTP: false), nil,
            "javascript: rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "feed:file:///etc/passwd", allowInsecureHTTP: false), nil, "file: rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "feed://ftp://example.com/feed", allowInsecureHTTP: false), nil,
            "ftp: rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "feed:data:text/html,bad", allowInsecureHTTP: false), nil, "data: rejected")

        // 13. Malformed news URLs rejected
        assertEqual(
            NewsURLParser.parse(urlString: "news://story", allowInsecureHTTP: false), nil, "Missing ID rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "news://story/", allowInsecureHTTP: false), nil, "Slash with no ID rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "news://article/123", allowInsecureHTTP: false), nil,
            "Wrong host 'article' rejected")
        assertEqual(
            NewsURLParser.parse(urlString: "news://settings/account", allowInsecureHTTP: false), nil,
            "Wrong host 'settings' rejected")

        // 14. Unrelated schemes rejected
        assertEqual(
            NewsURLParser.parse(urlString: "https://example.com/rss", allowInsecureHTTP: false), nil,
            "Direct https scheme rejected by parser")
        assertEqual(
            NewsURLParser.parse(urlString: "http://example.com/rss", allowInsecureHTTP: false), nil,
            "Direct http scheme rejected by parser")
        assertEqual(NewsURLParser.parse(urlString: "", allowInsecureHTTP: false), nil, "Empty string rejected")

        // 15. Duplicate feed prevention
        let suiteName = testDefaultsSuite("test.url.duplicate.prevention")
        let tempDefaults = UserDefaults(suiteName: suiteName)!
        defer { removeTestDefaults(suiteName) }
        let settings = AppSettings(defaults: tempDefaults)

        let addResult1 = settings.addFeed(url: "https://example.com/rss.xml")
        assertEqual(addResult1, "https://example.com/rss.xml", "First feed subscription succeeds")
        assertTrue(settings.hasFeed("https://example.com/rss.xml"), "Settings reports hasFeed as true")

        let addResult2 = settings.addFeed(url: "https://example.com/rss.xml")
        assertEqual(addResult2, nil, "Duplicate subscription attempt returns nil")

        let addResult3 = settings.addFeed(url: "https://example.com/rss.xml/")
        assertEqual(addResult3, nil, "Duplicate subscription attempt with slash variant returns nil")
    }

    @MainActor
    static func testAppIntentsExecutionAndValidation() async {
        print("  - Testing App Intents Execution, Validation, Gating and Resolution...")

        // 1. RefreshFeedsIntent: verify title, openAppWhenRun, isolated execution and dialog
        assertEqual(RefreshFeedsIntent.title, "Refresh Feeds", "RefreshFeedsIntent title is 'Refresh Feeds'")
        assertFalse(RefreshFeedsIntent.openAppWhenRun, "RefreshFeedsIntent does not open app")

        let refreshSuite = testDefaultsSuite("test.intent.refresh")
        let refreshDefaults = UserDefaults(suiteName: refreshSuite)!
        defer { removeTestDefaults(refreshSuite) }
        let refreshSettings = AppSettings(defaults: refreshDefaults)
        let refreshStore = ArticleStore(database: DatabaseEngine(path: ":memory:"))
        await refreshStore.initialize()
        let refreshFeedManager = FeedManager(settings: refreshSettings, store: refreshStore, schedulesRefresh: false)

        let refreshIntent = RefreshFeedsIntent(feedManager: refreshFeedManager)
        do {
            let result = try await refreshIntent.perform()
            let dialogText = extractDialogText(from: result)
            assertTrue(
                dialogText != nil && dialogText!.contains("Feeds refreshed successfully"),
                "RefreshFeedsIntent returns confirmation dialog")
        } catch {
            assertTrue(false, "RefreshFeedsIntent perform threw: \(error)")
        }

        // Test RefreshFeedsIntent via IntentDependencyResolver
        IntentDependencyResolver.feedManagerOverride = refreshFeedManager
        defer { IntentDependencyResolver.feedManagerOverride = nil }
        let defaultRefreshIntent = RefreshFeedsIntent()
        do {
            let result = try await defaultRefreshIntent.perform()
            let dialogText = extractDialogText(from: result)
            assertTrue(
                dialogText != nil && dialogText!.contains("Feeds refreshed successfully"),
                "Default RefreshFeedsIntent uses IntentDependencyResolver")
        } catch {
            assertTrue(false, "Default RefreshFeedsIntent perform threw: \(error)")
        }

        // 2. AddFeedIntent: parameters, validation, duplicate prevention, and insecure HTTP gating
        assertEqual(AddFeedIntent.title, "Add Feed", "AddFeedIntent title is 'Add Feed'")
        assertFalse(AddFeedIntent.openAppWhenRun, "AddFeedIntent does not open app")

        let addSuite = testDefaultsSuite("test.intent.addfeed")
        let addDefaults = UserDefaults(suiteName: addSuite)!
        defer { removeTestDefaults(addSuite) }
        let addSettings = AppSettings(defaults: addDefaults)

        // Valid feed URL with default settings (allowInsecureHTTP = false)
        let validURL = URL(string: "https://example.com/rss.xml")!
        let addIntent1 = AddFeedIntent(url: validURL, appSettings: addSettings)
        do {
            let res1 = try await addIntent1.perform()
            assertEqual(res1.value, true, "AddFeedIntent with valid URL returns true")
            assertTrue(addSettings.hasFeed("https://example.com/rss.xml"), "Feed is registered in AppSettings")
            let dialog1 = extractDialogText(from: res1)
            assertTrue(
                dialog1 != nil && dialog1!.contains("Subscribed to feed"),
                "AddFeedIntent returns subscription dialog")
        } catch {
            assertTrue(false, "AddFeedIntent 1 threw: \(error)")
        }

        // Duplicate subscription rejection
        let addIntentDup = AddFeedIntent(url: validURL, appSettings: addSettings)
        do {
            let resDup = try await addIntentDup.perform()
            assertEqual(resDup.value, false, "Duplicate subscription returns false")
            let dialogDup = extractDialogText(from: resDup)
            assertTrue(
                dialogDup != nil && dialogDup!.contains("Could not subscribe"),
                "Duplicate subscription returns failure dialog")
        } catch {
            assertTrue(false, "AddFeedIntent duplicate threw: \(error)")
        }

        // Trailing slash variant is recognized as duplicate
        let slashURL = URL(string: "https://example.com/rss.xml/")!
        let addIntentSlash = AddFeedIntent(url: slashURL, appSettings: addSettings)
        do {
            let resSlash = try await addIntentSlash.perform()
            assertEqual(resSlash.value, false, "Trailing slash duplicate returns false")
        } catch {
            assertTrue(false, "AddFeedIntent trailing slash threw: \(error)")
        }

        // Insecure HTTP URL upgraded when allowInsecureHTTP is false
        let httpURL = URL(string: "http://insecure-feed.org/feed.xml")!
        let addIntentHTTP = AddFeedIntent(url: httpURL, appSettings: addSettings)
        do {
            let resHTTP = try await addIntentHTTP.perform()
            assertEqual(resHTTP.value, true, "HTTP feed subscription succeeds via HTTPS upgrade")
            assertTrue(addSettings.hasFeed("https://insecure-feed.org/feed.xml"), "Feed was upgraded to HTTPS")
            assertFalse(addSettings.hasFeed("http://insecure-feed.org/feed.xml"), "HTTP URL was not preserved")
        } catch {
            assertTrue(false, "AddFeedIntent HTTP upgrade threw: \(error)")
        }

        // Insecure HTTP URL preserved when allowInsecureHTTP is true
        let insecureSuite = testDefaultsSuite("test.intent.insecure")
        let insecureDefaults = UserDefaults(suiteName: insecureSuite)!
        defer { removeTestDefaults(insecureSuite) }
        let insecureSettings = AppSettings(defaults: insecureDefaults)
        insecureSettings.setAllowInsecureHTTP(true)

        let plainHTTPURL = URL(string: "http://plain-http.org/feed.xml")!
        let addIntentPlain = AddFeedIntent(url: plainHTTPURL, appSettings: insecureSettings)
        do {
            let resPlain = try await addIntentPlain.perform()
            assertEqual(resPlain.value, true, "Plain HTTP feed subscription succeeds when allowed")
            assertTrue(insecureSettings.hasFeed("http://plain-http.org/feed.xml"), "Plain HTTP URL preserved")
        } catch {
            assertTrue(false, "AddFeedIntent plain HTTP threw: \(error)")
        }

        // Invalid scheme / unparseable URL returns false
        let invalidURL = URL(string: "file:///etc/passwd")!
        let addIntentInvalid = AddFeedIntent(url: invalidURL, appSettings: addSettings)
        do {
            let resInvalid = try await addIntentInvalid.perform()
            assertEqual(resInvalid.value, false, "file:// URL scheme rejected")
        } catch {
            assertTrue(false, "AddFeedIntent invalid threw: \(error)")
        }

        // AddFeedIntent via IntentDependencyResolver
        IntentDependencyResolver.appSettingsOverride = addSettings
        defer { IntentDependencyResolver.appSettingsOverride = nil }
        let resolverFeedURL = URL(string: "https://resolver-test.com/feed.xml")!
        let resolverAddIntent = AddFeedIntent(url: resolverFeedURL)
        do {
            let resResolver = try await resolverAddIntent.perform()
            assertEqual(resResolver.value, true, "AddFeedIntent uses IntentDependencyResolver appSettingsOverride")
            assertTrue(addSettings.hasFeed("https://resolver-test.com/feed.xml"), "Feed registered via resolver")
        } catch {
            assertTrue(false, "AddFeedIntent resolver threw: \(error)")
        }

        // 3. OpenSectionIntent: AppSection enumeration and navigation routing
        assertEqual(OpenSectionIntent.title, "Open Section", "OpenSectionIntent title is 'Open Section'")
        assertTrue(OpenSectionIntent.openAppWhenRun, "OpenSectionIntent opens app in foreground")

        let sections: [AppSection] = [.today, .unread, .briefing, .savedStories]
        for section in sections {
            var routedSection: AppSection?
            let openIntent = OpenSectionIntent(section: section) { s in
                routedSection = s
            }
            do {
                _ = try await openIntent.perform()
                assertEqual(routedSection, section, "OpenSectionIntent routes to \(section.rawValue)")
            } catch {
                assertTrue(false, "OpenSectionIntent for \(section) threw: \(error)")
            }
        }

        // OpenSectionIntent via IntentDependencyResolver.sectionNavigationHandler
        var ambientRouted: AppSection?
        IntentDependencyResolver.sectionNavigationHandler = { s in
            ambientRouted = s
        }
        defer { IntentDependencyResolver.sectionNavigationHandler = nil }
        let ambientOpenIntent = OpenSectionIntent(section: .briefing)
        do {
            _ = try await ambientOpenIntent.perform()
            assertEqual(ambientRouted, .briefing, "OpenSectionIntent routes through IntentDependencyResolver")
        } catch {
            assertTrue(false, "Ambient OpenSectionIntent threw: \(error)")
        }

        // 4. MarkAllAsReadIntent: unread count clearing, idempotency, and dialog
        assertEqual(MarkAllAsReadIntent.title, "Mark All as Read", "MarkAllAsReadIntent title is 'Mark All as Read'")
        assertFalse(MarkAllAsReadIntent.openAppWhenRun, "MarkAllAsReadIntent does not open app")

        let markStore = ArticleStore(database: DatabaseEngine(path: ":memory:"))
        await markStore.initialize()
        let sample1 = FeedArticle(
            title: "Story 1", link: "https://example.com/1", guid: "g1", description: "D1", pubDate: Date(),
            source: "Publisher")
        let sample2 = FeedArticle(
            title: "Story 2", link: "https://example.com/2", guid: "g2", description: "D2", pubDate: Date(),
            source: "Publisher")
        await markStore.batchUpsert(articles: [sample1, sample2])
        assertEqual(markStore.unreadCount, 2, "2 unread stories before MarkAllAsReadIntent")

        let markIntent = MarkAllAsReadIntent(articleStore: markStore)
        do {
            let resMark = try await markIntent.perform()
            assertEqual(markStore.unreadCount, 0, "Unread count is 0 after MarkAllAsReadIntent")
            let dialogMark = extractDialogText(from: resMark)
            assertTrue(
                dialogMark != nil && dialogMark!.contains("All visible stories marked as read"),
                "MarkAllAsReadIntent returns confirmation dialog")
        } catch {
            assertTrue(false, "MarkAllAsReadIntent perform threw: \(error)")
        }

        // Idempotent execution when unread is already 0
        do {
            let resMark2 = try await markIntent.perform()
            assertEqual(markStore.unreadCount, 0, "Unread count remains 0 on repeat MarkAllAsReadIntent")
            let dialogMark2 = extractDialogText(from: resMark2)
            assertTrue(
                dialogMark2 != nil && dialogMark2!.contains("All visible stories marked as read"),
                "Confirmation dialog returned on idempotent run")
        } catch {
            assertTrue(false, "MarkAllAsReadIntent repeat threw: \(error)")
        }

        // MarkAllAsReadIntent via IntentDependencyResolver
        IntentDependencyResolver.articleStoreOverride = markStore
        defer { IntentDependencyResolver.articleStoreOverride = nil }
        let ambientMarkIntent = MarkAllAsReadIntent()
        do {
            let resAmbientMark = try await ambientMarkIntent.perform()
            let dialogAmbient = extractDialogText(from: resAmbientMark)
            assertTrue(
                dialogAmbient != nil && dialogAmbient!.contains("All visible stories marked as read"),
                "Ambient MarkAllAsReadIntent succeeds via resolver")
        } catch {
            assertTrue(false, "Ambient MarkAllAsReadIntent threw: \(error)")
        }

        // 5. NewBriefingIntent: edition reset and dialog
        assertEqual(NewBriefingIntent.title, "New Briefing", "NewBriefingIntent title is 'New Briefing'")
        assertFalse(NewBriefingIntent.openAppWhenRun, "NewBriefingIntent does not open app")

        var customResetTriggered = false
        let customBriefingIntent = NewBriefingIntent(resetAction: {
            customResetTriggered = true
        })
        do {
            let resBriefing = try await customBriefingIntent.perform()
            assertTrue(customResetTriggered, "NewBriefingIntent custom reset action executed")
            let dialogBriefing = extractDialogText(from: resBriefing)
            assertTrue(
                dialogBriefing != nil && dialogBriefing!.contains("New briefing generated"),
                "NewBriefingIntent dialog confirms generation")
        } catch {
            assertTrue(false, "NewBriefingIntent custom action threw: \(error)")
        }

        // Default NewBriefingIntent resets UserDefaults
        let defaultBriefingIntent = NewBriefingIntent()
        do {
            let resDefaultBriefing = try await defaultBriefingIntent.perform()
            assertTrue(
                UserDefaults.standard.double(forKey: "briefingEditionSelectedAt") > 0,
                "briefingEditionSelectedAt timestamp updated in UserDefaults")
            assertEqual(
                UserDefaults.standard.string(forKey: "briefingEditionArticleIDs"), "",
                "briefingEditionArticleIDs cleared in UserDefaults")
            let dialogDefault = extractDialogText(from: resDefaultBriefing)
            assertTrue(
                dialogDefault != nil && dialogDefault!.contains("New briefing generated"),
                "NewBriefingIntent default execution dialog")
        } catch {
            assertTrue(false, "Default NewBriefingIntent threw: \(error)")
        }
    }

    private static func extractDialogText(from result: some IntentResult) -> String? {
        let mirror = Mirror(reflecting: result)
        for child in mirror.children where child.label == "dialog" {
            let desc = String(describing: child.value)
            if desc.starts(with: "nil") || desc == "Optional(nil)" { return nil }
            return desc
        }
        return nil
    }

    private static func shortcutMetadata(from shortcut: AppShortcut) -> (
        shortTitle: String, systemImage: String, phrases: [String]
    ) {
        let mirror = Mirror(reflecting: shortcut)
        var title = ""
        var image = ""
        var phrases: [String] = []
        for child in mirror.children {
            if child.label == "shortTitle" {
                title = String(describing: child.value)
            } else if child.label == "systemImageName" {
                if let opt = child.value as? String? {
                    image = opt ?? ""
                }
            } else if child.label == "basePhraseTemplates" {
                if let list = child.value as? [String] {
                    phrases = list
                }
            }
        }
        return (title, image, phrases)
    }

    @MainActor
    static func testAppShortcutsProviderDeclarations() async {
        print("  - Testing NewsShortcuts AppShortcutsProvider Declarations & Terminology...")

        // 1. Shortcut tile color
        assertEqual(NewsShortcuts.shortcutTileColor, .navy, "NewsShortcuts tile color is navy")

        // 2. Exactly 5 shortcuts
        let shortcuts = NewsShortcuts.appShortcuts
        assertEqual(shortcuts.count, 5, "NewsShortcuts defines exactly 5 App Shortcuts")

        // 3. Inspect each shortcut declaration
        let refreshMeta = shortcutMetadata(from: shortcuts[0])
        assertTrue(refreshMeta.shortTitle.contains("Refresh Feeds"), "Shortcut 0 shortTitle contains 'Refresh Feeds'")
        assertEqual(refreshMeta.systemImage, "arrow.clockwise", "Shortcut 0 icon is arrow.clockwise")
        assertTrue(refreshMeta.phrases.contains("Refresh ${applicationName}"), "Shortcut 0 contains refresh phrase")

        let addFeedMeta = shortcutMetadata(from: shortcuts[1])
        assertTrue(addFeedMeta.shortTitle.contains("Add Feed"), "Shortcut 1 shortTitle contains 'Add Feed'")
        assertEqual(addFeedMeta.systemImage, "plus", "Shortcut 1 icon is plus")

        let openSectionMeta = shortcutMetadata(from: shortcuts[2])
        assertTrue(openSectionMeta.shortTitle.contains("Open Section"), "Shortcut 2 shortTitle contains 'Open Section'")
        assertEqual(openSectionMeta.systemImage, "sidebar.left", "Shortcut 2 icon is sidebar.left")

        let markReadMeta = shortcutMetadata(from: shortcuts[3])
        assertTrue(
            markReadMeta.shortTitle.contains("Mark All as Read"), "Shortcut 3 shortTitle contains 'Mark All as Read'")
        assertEqual(markReadMeta.systemImage, "checkmark.circle", "Shortcut 3 icon is checkmark.circle")

        let newBriefingMeta = shortcutMetadata(from: shortcuts[4])
        assertTrue(newBriefingMeta.shortTitle.contains("New Briefing"), "Shortcut 4 shortTitle contains 'New Briefing'")
        assertEqual(newBriefingMeta.systemImage, "text.book.closed", "Shortcut 4 icon is text.book.closed")

        // 4. Terminology review: ensure strictly 'story'/'stories' and never 'article' in shortcut titles and phrases
        for (idx, shortcut) in shortcuts.enumerated() {
            let meta = shortcutMetadata(from: shortcut)
            assertFalse(
                meta.shortTitle.lowercased().contains("article"),
                "Shortcut [\(idx)] title '\(meta.shortTitle)' must not contain 'article'"
            )
            for phrase in meta.phrases {
                assertFalse(
                    phrase.lowercased().contains("article"),
                    "Shortcut [\(idx)] phrase '\(phrase)' must not contain 'article'"
                )
            }
        }
    }

    @MainActor
    static func testNotificationModeTriageAndGrammar() async {
        print("  - Testing NotificationMode Triage, Privacy & Singular/Plural Grammar...")

        var identified = FeedArticle(
            title: "Story", link: "https://example.com/a", guid: "a", description: "", pubDate: Date(), source: "P")
        identified.storedID = "stable-id"
        assertEqual(
            NotificationService.notificationIdentifier(for: identified), "news-stable-id",
            "Notification identifiers come from the stored story identity, not the per-process hash seed")

        // 1. Singular/Plural grammar helper
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 1, uniqueSourcesCount: 1),
            "1 new article from 1 source", "Singular article and source")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 2, uniqueSourcesCount: 1),
            "2 new articles from 1 source", "Plural articles, singular source")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 3, uniqueSourcesCount: 2),
            "3 new articles across 2 sources", "Plural articles, plural sources")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 10, uniqueSourcesCount: 4),
            "10 new articles across 4 sources", "Multi-source plural formatting")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 1, uniqueSourcesCount: 0),
            "1 new article across 0 sources", "Edge case: 1 article, 0 sources")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 0, uniqueSourcesCount: 0),
            "0 new articles across 0 sources", "Edge case: 0 articles, 0 sources")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 0, uniqueSourcesCount: 1),
            "0 new articles from 1 source", "Edge case: 0 articles, 1 source")

        // 2. AppSettings Migration Semantics
        let suiteName = testDefaultsSuite("test.notifications.migration")
        let tempDefaults = UserDefaults(suiteName: suiteName)!
        defer { removeTestDefaults(suiteName) }

        // Case A: legacy privateNotificationsEnabled = true -> migrates to .private
        tempDefaults.set(true, forKey: AppSettings.privateNotificationsEnabledKey)
        let settingsA = AppSettings(defaults: tempDefaults)
        assertEqual(
            settingsA.notificationMode, AppSettings.NotificationMode.privacy,
            "Legacy private flag should migrate to .private mode")
        assertEqual(
            tempDefaults.string(forKey: AppSettings.notificationModeKey), "private",
            "Migrated key should be written to defaults")

        // Case B: legacy privateNotificationsEnabled = false -> migrates to .full
        let suiteNameB = testDefaultsSuite("test.notifications.migration.b")
        let tempDefaultsB = UserDefaults(suiteName: suiteNameB)!
        defer { removeTestDefaults(suiteNameB) }
        tempDefaultsB.set(false, forKey: AppSettings.privateNotificationsEnabledKey)
        let settingsB = AppSettings(defaults: tempDefaultsB)
        assertEqual(
            settingsB.notificationMode, AppSettings.NotificationMode.full,
            "Legacy non-private flag should migrate to .full mode")
        assertEqual(
            tempDefaultsB.string(forKey: AppSettings.notificationModeKey), "full",
            "Migrated key should be written to defaults")

        // Case C: mutation API updates both mode and legacy private flag
        settingsB.setNotificationMode(.minimal)
        assertEqual(settingsB.notificationMode, AppSettings.NotificationMode.minimal, "Mode should update to .minimal")
        assertEqual(
            tempDefaultsB.string(forKey: AppSettings.notificationModeKey), "minimal", "Key should update to minimal")

        // Starred feeds persist and go with an unsubscribed feed (#588).
        settingsB.feedURLs = ["https://example.com/feed"]
        settingsB.setFeedStarred("https://example.com/feed", true)
        assertEqual(
            AppSettings(defaults: tempDefaultsB).starredFeedURLs, ["https://example.com/feed"], "A star is stored")
        settingsB.setFeedStarred("https://example.com/feed", false)
        assertTrue(AppSettings(defaults: tempDefaultsB).starredFeedURLs.isEmpty, "Unstarring is stored")
        settingsB.setFeedStarred("https://example.com/feed", true)
        settingsB.removeFeed(url: "https://example.com/feed")
        assertTrue(settingsB.starredFeedURLs.isEmpty, "Unsubscribing removes the star")

        // At most three feeds are starred: a fourth star is refused, not swapped in (#588).
        let capped = (1...4).map { "https://cap\($0).invalid/feed" }
        for url in capped.prefix(3) { assertTrue(settingsB.setFeedStarred(url, true), "Stars up to the limit") }
        assertFalse(settingsB.setFeedStarred(capped[3], true), "A fourth star is refused")
        assertEqual(settingsB.starredFeedURLs, Set(capped.prefix(3)), "The three stars stay; none is replaced")
        assertEqual(
            AppSettings(defaults: tempDefaultsB).starredFeedURLs, Set(capped.prefix(3)),
            "The refused star is not stored")
        assertTrue(settingsB.setFeedStarred(capped[0], true), "Re-starring a starred feed at the limit is fine")
        settingsB.setFeedStarred(capped[0], false)
        assertTrue(settingsB.setFeedStarred(capped[3], true), "Unstarring frees a place")
    }

    actor FeedDeliveryGate {
        private var continuation: CheckedContinuation<Void, Never>?
        var started = false
        func wait() async {
            started = true
            await withCheckedContinuation { continuation = $0 }
        }
        func deliver() {
            continuation?.resume()
            continuation = nil
        }
    }

    @MainActor
    static func testFeedRemovalAndShutdown() async throws {
        let suite = testDefaultsSuite("test.feed-lifecycle")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        settings.feedURLs = ["https://example.com/feed"]
        settings.aiEnabled = false
        settings.notificationsEnabled = false
        let db = DatabaseEngine(path: ":memory:")
        let store = ArticleStore(database: db)
        await store.initialize()
        let article = FeedArticle(
            title: "Late delivery", link: "https://example.com/late", guid: "late", description: "Report",
            pubDate: Date(), source: "Test")
        for shutdown in 0...2 {
            settings.feedURLs = ["https://example.com/feed"]
            let gate = FeedDeliveryGate()
            let manager = FeedManager(
                settings: settings, store: store, schedulesRefresh: false,
                fetchBatch: { urls, _ in
                    guard let url = urls.first else { return [] }
                    await gate.wait()
                    return [(url, [article], nil, nil)]
                })
            let refresh = Task { await manager.fetchFeedsAsync() }
            while !(await gate.started) { await Task.yield() }
            switch shutdown {
            case 0: manager.removeFeed(url: "https://example.com/feed")
            case 1: manager.stopBackgroundWork()
            default: NotificationCenter.default.post(name: NSApplication.willTerminateNotification, object: nil)
            }
            await gate.deliver()
            await refresh.value
            assertTrue(
                try await db.fetchArticles().isEmpty, "Late feed delivery after removal or shutdown must not be stored")
            manager.stopBackgroundWork()
        }
        let cancelled = Task {
            do {
                try await db.upsertArticles([article])
                return false
            } catch is CancellationError { return true } catch { return false }
        }
        cancelled.cancel()
        assertTrue(await cancelled.value, "Cancelled database ingestion propagates cancellation")
        assertTrue(try await db.fetchArticles().isEmpty, "Cancelled ingestion rolls back its transaction")
        let panelURL = TensionMethodology.v1.panel[0].url
        let panelArticle = FeedArticle(
            storedID: "subscription-scope", title: "Subscription scope fixture",
            link: "https://example.com/subscription-scope", guid: "subscription-scope",
            description: "Panel report", pubDate: Date(), source: "Test")
        _ = try await db.upsertArticles([panelArticle], feedUrl: panelURL)
        settings.feedURLs = []
        let manager = FeedManager(settings: settings, store: store, schedulesRefresh: false)
        await eventually("Initial subscription scope hides panel-only reports") {
            (try? await db.fetchArticles())?.contains { $0.id == panelArticle.id } == false
        }
        settings.feedURLs = [panelURL]
        await eventually("Adding a subscription reveals its previously collected panel reports") {
            (try? await db.fetchArticles())?.contains { $0.id == panelArticle.id } == true
        }
        settings.feedURLs = []
        settings.feedURLs = [panelURL]
        settings.feedURLs = []
        await eventually("Rapid subscription changes apply the latest panel scope") {
            (try? await db.fetchArticles())?.contains { $0.id == panelArticle.id } == false
        }
        manager.stopBackgroundWork()
        settings.feedURLs = [panelURL]
        await manager.fetchFeedsAsync()
        assertFalse(
            try await db.fetchArticles().contains { $0.id == panelArticle.id },
            "Stopped managers no longer observe subscription changes")
        await db.close()
    }

    actor RefreshCalls {
        private(set) var count = 0
        func next() -> Int {
            count += 1
            return count
        }
    }

    @MainActor
    static func testSleepAndWakeRefresh() async throws {
        print("  - Testing sleep and wake: interrupted refreshes store nothing, stale feeds refresh after wake...")
        let suite = testDefaultsSuite("test.sleep-wake")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        settings.feedURLs = ["https://example.com/feed"]
        settings.aiEnabled = false
        settings.notificationsEnabled = false
        settings.fetchIntervalMinutes = 30
        let db = DatabaseEngine(path: ":memory:")
        let store = ArticleStore(database: db)
        await store.initialize()
        let article = FeedArticle(
            title: "Overnight report", link: "https://example.com/overnight", guid: "overnight",
            description: "Report", pubDate: Date(), source: "Test")
        let center = NotificationCenter()
        let calls = RefreshCalls()
        let gate = FeedDeliveryGate()
        var clock = Date(timeIntervalSince1970: 1_800_000_000)
        let manager = FeedManager(
            settings: settings, store: store, schedulesRefresh: false,
            fetchBatch: { urls, _ in
                guard let url = urls.first else { return [] }
                if await calls.next() == 1 { await gate.wait() }
                return [(url, [article], nil, nil)]
            },
            powerEvents: center, wakeRefreshDelay: .milliseconds(10), now: { clock })
        func sleepAndWake() async {
            center.post(name: NSWorkspace.willSleepNotification, object: nil)
            center.post(name: NSWorkspace.didWakeNotification, object: nil)
            await manager.waitForWakeRefresh()
        }

        let interrupted = Task { await manager.fetchFeedsAsync() }
        while !(await gate.started) { await Task.yield() }
        center.post(name: NSWorkspace.willSleepNotification, object: nil)
        assertFalse(manager.isAnyFeedLoading, "Sleep ends the loading state of the refresh it cancels")
        assertFalse(manager.feedStatuses.values.contains(.loading), "No feed stays marked as loading after sleep")
        await gate.deliver()
        await interrupted.value
        assertTrue(try await db.fetchArticles().isEmpty, "A refresh cut off by sleep stores nothing")

        center.post(name: NSWorkspace.didWakeNotification, object: nil)
        center.post(name: NSWorkspace.willSleepNotification, object: nil)
        await manager.waitForWakeRefresh()
        assertEqual(await calls.count, 1, "Sleeping again before the wake delay ends refreshes nothing")

        center.post(name: NSWorkspace.didWakeNotification, object: nil)
        await manager.waitForWakeRefresh()
        assertEqual(await calls.count, 2, "An interrupted refresh is repeated after wake")
        assertEqual(try await db.fetchArticles().map(\.title), ["Overnight report"], "The wake refresh stores the feed")
        assertFalse(manager.isAnyFeedLoading, "The wake refresh ends the loading state")

        clock = clock.addingTimeInterval(5 * 60)
        await sleepAndWake()
        assertEqual(await calls.count, 2, "A refresh newer than the interval is not repeated after wake")
        clock = clock.addingTimeInterval(31 * 60)
        await sleepAndWake()
        assertEqual(await calls.count, 3, "A feed older than the interval refreshes after wake")

        manager.stopBackgroundWork()
        clock = clock.addingTimeInterval(60 * 60)
        await sleepAndWake()
        assertEqual(await calls.count, 3, "A stopped manager ignores wake")
        await db.close()
    }

    @MainActor
    static func testRetentionPruneAfterRefresh() async throws {
        print(
            "  - Testing retention: read, unsaved stories older than the setting are deleted once a day after a refresh..."
        )
        let suite = testDefaultsSuite("test.retention")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        assertEqual(settings.articleRetentionDays, 30, "Read stories are kept for 30 days by default")
        settings.feedURLs = ["https://example.com/feed"]
        settings.aiEnabled = false
        settings.notificationsEnabled = false
        let db = DatabaseEngine(path: ":memory:")
        let store = ArticleStore(database: db)
        await store.initialize()
        // Pruning compares against the wall clock; the injected clock only drives the once-a-day throttle.
        var clock = Date()
        let manager = FeedManager(
            settings: settings, store: store, schedulesRefresh: false,
            fetchBatch: { urls, _ in urls.map { ($0, [], nil, nil) } }, imageFinder: .unavailable, now: { clock })
        func storeOldStory(_ name: String, read: Bool, saved: Bool = false) async throws -> String {
            let article = FeedArticle(
                title: name, link: "https://example.com/\(name)", guid: name, description: name,
                pubDate: clock.addingTimeInterval(-40 * 86400), source: "Test")
            await store.batchUpsert(articles: [article], feedUrl: settings.feedURLs[0])
            guard let id = try await db.fetchArticles().first(where: { $0.title == name })?.id else {
                assertTrue(false, "Stored the \(name) story")
                return ""
            }
            if read { try await db.markRead(articleId: id, isRead: true) }
            if saved { _ = try await db.toggleSaved(articleId: id) }
            return id
        }
        func stored(_ id: String) async throws -> Bool { try await db.fetchArticles().contains { $0.id == id } }

        let read = try await storeOldStory("read", read: true)
        let saved = try await storeOldStory("saved", read: true, saved: true)
        let unread = try await storeOldStory("unread", read: false)
        await manager.fetchFeedsAsync()
        assertFalse(try await stored(read), "A read, unsaved story older than 30 days is deleted after the refresh")
        let savedKept = try await stored(saved)
        let unreadKept = try await stored(unread)
        assertTrue(savedKept && unreadKept, "Saved and unread stories are kept")

        let later = try await storeOldStory("later", read: true)
        clock = clock.addingTimeInterval(6 * 3600)
        await manager.fetchFeedsAsync()
        assertTrue(try await stored(later), "Retention runs at most once a day")
        clock = clock.addingTimeInterval(19 * 3600)
        await manager.fetchFeedsAsync()
        assertFalse(try await stored(later), "The next day's refresh prunes again")

        settings.setArticleRetentionDays(0)
        assertEqual(AppSettings(defaults: defaults).articleRetentionDays, 0, "The retention setting persists")
        let kept = try await storeOldStory("kept", read: true)
        clock = clock.addingTimeInterval(25 * 3600)
        await manager.fetchFeedsAsync()
        assertTrue(try await stored(kept), "Never keeps every story")
        manager.stopBackgroundWork()
        await db.close()
    }

    @MainActor
    static func testCancelledRefreshCarriesNotifications() async throws {
        print(
            "  - Testing a refresh cancelled by a subscription change: stories it stored are notified by the next run..."
        )
        let suite = testDefaultsSuite("test.cancelled-refresh-notifications")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        settings.feedURLs = ["https://example.com/one", "https://example.com/two"]
        settings.aiEnabled = false
        settings.notificationsEnabled = true
        let db = DatabaseEngine(path: ":memory:")
        let store = ArticleStore(database: db)
        await store.initialize()
        let stories = [
            "https://example.com/one": "first", "https://example.com/two": "second",
            "https://example.com/three": "third",
        ]
        var notified: [String] = []
        let manager = FeedManager(
            settings: settings, store: store, schedulesRefresh: false,
            fetchBatch: { urls, _ in
                urls.map { url in
                    let name = stories[url] ?? "other"
                    let article = FeedArticle(
                        title: name, link: "https://example.com/\(name)", guid: name, description: name,
                        pubDate: Date(),
                        source: "Test")
                    return (url, [article], nil, nil)
                }
            },
            notifyBatch: { articles, _ in notified.append(contentsOf: articles.map(\.id)) }, imageFinder: .unavailable)

        let first = Task { await manager.fetchFeedsAsync() }
        // Cancel once the first feed's story is committed and before the run can notify it.
        while try await db.fetchArticles().isEmpty { await Task.yield() }
        manager.addFeed(url: "https://example.com/three")
        assertFalse(manager.isAnyFeedLoading, "Cancelling a refresh ends its loading state")
        await first.value
        // The subscription change started the next refresh; its caller runs triage after clustering.
        for _ in 0..<2000 where notified.count < 3 { try await Task.sleep(for: .milliseconds(5)) }
        let expected = stories.map { ArticleIdentity.scopedGUID($0.value, feedURL: $0.key)! }
        assertEqual(Set(notified), Set(expected), "Stories stored by the cancelled run and by the new run are notified")
        assertEqual(notified.count, 3, "Each story is notified once")
        manager.stopBackgroundWork()
        await db.close()
    }

    static func testUndatedStoriesInPublicationWindow() async throws {
        print("  - Testing undated stories fall into a publication window by ingestion time...")
        let db = DatabaseEngine(path: ":memory:")
        try await db.open()
        let undated = FeedArticle(
            title: "Undated", link: "https://example.com/undated", guid: "undated", description: "",
            pubDate: DateParser.unknownDate, source: "Test")
        let old = FeedArticle(
            title: "Old", link: "https://example.com/old", guid: "old", description: "",
            pubDate: Date().addingTimeInterval(-3 * 86400), source: "Test")
        try await db.upsertArticles([undated, old], feedUrl: "https://example.com/feed")
        let now = Date()
        let window = try await db.fetchArticles(
            publicationWindow: now.addingTimeInterval(-3600)...now.addingTimeInterval(60))
        assertEqual(
            window.map(\.title), ["Undated"],
            "An undated story stored now is within the last hour; a three-day-old story is not")
        assertTrue(
            window.first.map { abs($0.orderDate.timeIntervalSince(now)) < 60 } ?? false,
            "orderDate falls back to ingestion time for an undated story")
        await db.close()
    }

    final class SocketObservation: @unchecked Sendable {
        private let lock = NSLock()
        private var targets: [String] = []
        private var completed = false
        func recordText(_ value: String) { lock.withLock { targets.append(value) } }
        func record(_ host: NWEndpoint.Host) { lock.withLock { targets.append(String(describing: host)) } }
        var count: Int { lock.withLock { targets.count } }
        var hosts: [String] { lock.withLock { targets } }
        func claim() -> Bool {
            lock.withLock {
                if completed { return false }
                completed = true
                return true
            }
        }
    }

    static func socketSend(_ connection: NWConnection, _ data: Data) async throws {
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            connection.send(
                content: data,
                completion: .contentProcessed { error in
                    if let error { continuation.resume(throwing: error) } else { continuation.resume() }
                })
        }
    }

    static func socketRead(_ connection: NWConnection, count: Int) async throws -> Data {
        var data = Data()
        while data.count < count {
            let next: Data = try await withCheckedThrowingContinuation { continuation in
                let once = SocketObservation()
                DispatchQueue.global().asyncAfter(deadline: .now() + 5) {
                    if once.claim() {
                        connection.cancel()
                        continuation.resume(throwing: FeedError.timeout)
                    }
                }
                connection.receive(minimumIncompleteLength: 1, maximumLength: count - data.count) {
                    bytes, _, eof, error in
                    guard once.claim() else { return }
                    if let error {
                        continuation.resume(throwing: error)
                    } else if let bytes, !bytes.isEmpty {
                        continuation.resume(returning: bytes)
                    } else {
                        continuation.resume(throwing: eof ? FeedError.network("EOF") : FeedError.timeout)
                    }
                }
            }
            data.append(next)
        }
        return data
    }

    static func socksConnect(_ proxy: NetworkBoundaryProxy, host: String, command: UInt8 = 1, port: UInt16 = 80)
        async throws -> (NWConnection, Data)
    {
        let endpoint = try await proxy.port()
        let client = NWConnection(host: "127.0.0.1", port: NWEndpoint.Port(rawValue: endpoint)!, using: .tcp)
        // A loopback connect can fail with EADDRINUSE when parallel runs churn ephemeral ports. NWConnection
        // then parks in .waiting and never completes a send, so surface that state instead of hanging.
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            let once = SocketObservation()
            client.stateUpdateHandler = { state in
                switch state {
                case .ready: if once.claim() { continuation.resume() }
                case .waiting(let error), .failed(let error): if once.claim() { continuation.resume(throwing: error) }
                case .cancelled: if once.claim() { continuation.resume(throwing: CancellationError()) }
                default: break
                }
            }
            client.start(queue: .global())
        }
        client.stateUpdateHandler = nil
        try await socketSend(client, Data([5, 1, 0]))
        assertEqual(try await socketRead(client, count: 2), Data([5, 0]), "SOCKS greeting succeeds")
        let hostBytes = Data(host.utf8)
        var request = Data([5, command, 0, 3, UInt8(hostBytes.count)])
        request.append(hostBytes)
        request.append(contentsOf: [UInt8(port >> 8), UInt8(port & 255)])
        // Fragment across every protocol boundary, not just a single network packet.
        try await socketSend(client, Data(request.prefix(1)))
        try await socketSend(client, Data(request.dropFirst()))
        return (client, try await socketRead(client, count: 10))
    }

    /// Hold a real HTTP response open until cancellation closes the upstream socket.
    static func holdCancellationResponse(
        _ connection: NWConnection, ready: SocketObservation,
        closed: SocketObservation, request: Data = Data()
    ) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 32768) { bytes, _, eof, error in
            guard error == nil, !eof, let bytes else {
                connection.cancel()
                return
            }
            let request = request + bytes
            guard request.range(of: Data("\r\n\r\n".utf8)) != nil else {
                holdCancellationResponse(connection, ready: ready, closed: closed, request: request)
                return
            }
            let header = String(decoding: request, as: UTF8.self)
            if header.hasPrefix("GET /drain ") {
                ready.recordText("drain")
                connection.receive(minimumIncompleteLength: 1, maximumLength: 32768) { bytes, _, eof, error in
                    assertTrue(
                        error == nil && eof && (bytes?.isEmpty ?? true),
                        "The proxy forwards the client's write-close before the response")
                    connection.send(
                        content: Data(repeating: 120, count: 65536), contentContext: .finalMessage,
                        completion: .contentProcessed { error in
                            assertTrue(error == nil, "The upstream sends its complete response after request EOF")
                            closed.recordText("drain")
                            connection.cancel()
                        })
                }
                return
            }
            assertTrue(
                header.hasPrefix("GET /headers/") || header.hasPrefix("GET /body/"),
                "Only the cancellation fixture is requested")
            let waitForClose: @Sendable () -> Void = {
                ready.recordText(header)
                connection.receive(minimumIncompleteLength: 1, maximumLength: 32768) { _, _, eof, error in
                    assertTrue(eof || error != nil, "Cancellation closes the upstream transport")
                    closed.recordText(header)
                    connection.cancel()
                }
            }
            if header.hasPrefix("GET /body/") {
                // The response starts but cannot complete: only 4 KiB of the declared 1 MiB is sent.
                var response = Data(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/rss+xml\r\nContent-Length: 1048576\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n"
                        .utf8)
                response.append(Data(repeating: 32, count: 4096))
                connection.send(
                    content: response,
                    completion: .contentProcessed { error in
                        assertTrue(error == nil, "The partial HTTP body is written before cancellation")
                        waitForClose()
                    })
            } else {
                waitForClose()
            }
        }
    }

    @MainActor
    static func testTransportCancellation() async throws {
        print("  - Testing refresh shutdown over real HTTP/SOCKS sockets...")
        let upstream = try NWListener(using: .tcp, on: .any)
        let queue = DispatchQueue(label: "test.cancellation.upstream")
        let ready = SocketObservation()
        let closed = SocketObservation()
        upstream.newConnectionHandler = { connection in
            connection.start(queue: queue)
            holdCancellationResponse(connection, ready: ready, closed: closed)
        }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            let once = SocketObservation()
            upstream.stateUpdateHandler = { state in
                if case .ready = state, once.claim() { continuation.resume() }
                if case .failed(let error) = state, once.claim() { continuation.resume(throwing: error) }
            }
            queue.asyncAfter(deadline: .now() + 5) {
                if once.claim() {
                    upstream.cancel()
                    continuation.resume(throwing: FeedError.timeout)
                }
            }
            upstream.start(queue: queue)
        }
        defer { upstream.cancel() }
        let port = upstream.port!
        let observed = SocketObservation()
        let proxy = NetworkBoundaryProxy(connector: { host, _ in
            observed.record(host)
            return NWConnection(host: "127.0.0.1", port: port, using: .tcp)
        })
        let (halfClosed, reply) = try await socksConnect(proxy, host: "93.184.216.34")
        assertEqual(reply[1], 0, "The drain control uses the protected socket")
        try await socketSend(halfClosed, Data("GET /drain HTTP/1.1\r\nHost: 93.184.216.34\r\n\r\n".utf8))
        await eventually("The drain fixture receives the request before its write-close") { ready.count == 1 }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            halfClosed.send(
                content: nil, contentContext: .finalMessage,
                completion: .contentProcessed { error in
                    if let error { continuation.resume(throwing: error) } else { continuation.resume() }
                })
        }
        assertEqual(
            try await socketRead(halfClosed, count: 65536), Data(repeating: 120, count: 65536),
            "A half-closed request drains the entire response across relay buffers")
        do {
            _ = try await socketRead(halfClosed, count: 1)
            assertTrue(false, "The response ends with forwarded EOF")
        } catch let error as FeedError {
            assertEqual(error, .network("EOF"), "The upstream write-close reaches the client after all response bytes")
        }
        halfClosed.cancel()
        let configuration = URLSessionConfiguration.ephemeral
        configuration.proxyConfigurations = [try await proxy.configuration()]
        let client = SecureHTTPClient(configuration: configuration)
        var samples: [String: [Double]] = [:]
        for phase in ["headers", "body"] {
            for index in 0..<5 {
                let db = DatabaseEngine(path: ":memory:")
                let store = ArticleStore(database: db)
                await store.initialize()
                let suite = testDefaultsSuite("test.transport-cancellation")
                defer { removeTestDefaults(suite) }
                let defaults = UserDefaults(suiteName: suite)!
                let settings = AppSettings(defaults: defaults)
                let feed = "http://93.184.216.34/\(phase)/\(index).xml"
                settings.feedURLs = [feed]
                settings.allowInsecureHTTP = true
                settings.aiEnabled = false
                let fetcher = FeedFetcher(client: client)
                let manager = FeedManager(
                    settings: settings, store: store, schedulesRefresh: false,
                    fetchBatch: { urls, allowHTTP in
                        await fetcher.fetchAllFeeds(urls: urls, allowHTTP: allowHTTP, state: db)
                    },
                    notifyBatch: { _, _ in })
                let done = SocketObservation()
                let count = ready.count
                let refresh = Task {
                    await manager.fetchFeedsAsync()
                    let end = ContinuousClock.now
                    done.recordText("finished")
                    return end
                }
                await eventually("The real HTTP request reaches the held response") { ready.count == count + 1 }
                assertTrue(manager.isAnyFeedLoading, "A stalled response keeps refresh active")
                assertEqual(done.count, 0, "The incomplete HTTP response cannot finish before shutdown")
                let start = ContinuousClock.now
                manager.stopBackgroundWork()
                await eventually("Shutdown completes without waiting for the network timeout", timeout: .seconds(2)) {
                    done.count == 1
                }
                let duration = start.duration(to: await refresh.value)
                let milliseconds =
                    Double(duration.components.seconds) * 1000 + Double(duration.components.attoseconds) / 1e15
                samples[phase, default: []].append(milliseconds)
                await eventually("Shutdown closes the protected upstream socket", timeout: .seconds(2)) {
                    closed.count == count + 1
                }
                assertFalse(manager.isAnyFeedLoading, "Shutdown clears refresh loading")
                assertEqual(try await db.counts().total, 0, "Cancellation ingests no partial articles")
                assertEqual(
                    try await db.feedFetchStates()[feed], nil, "Cancellation records no feed failure or validators")
                await db.close()
            }
        }
        assertEqual(observed.count, 11, "The drain control and each cancellation sample use one protected connection")
        assertTrue(
            observed.hosts.allSatisfy { $0 == "93.184.216.34" },
            "Production resolution pins the public numeric address before fixture routing")
        await proxy.stop()
        let report: [String: Any] = [
            "samples_ms": samples, "samples_per_phase": 5,
            "transport": "URLSession -> production SOCKS proxy -> controlled TCP fixture",
            "response_bytes_sent": 4096, "response_bytes_declared": 1_048_576,
        ]
        let data = try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys])
        print("TRANSPORT_CANCELLATION_REPORT " + String(decoding: data, as: UTF8.self))
    }

    /// Opt-in and live: refreshes the twelve panel feeds over the production client (real DNS, TLS and publishers),
    /// then stops refreshes at staggered offsets so shutdowns land during handshakes, transfers, parsing or ingestion.
    @MainActor
    static func testPublisherCancellation() async throws {
        let feeds = TensionMethodology.v1.panel.map(\.url)
        print("  - Live: refreshing and cancelling \(feeds.count) publisher feeds over HTTPS...")
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(
            "news-publisher-cancel-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        func run(_ label: String, cancelAfter offset: Duration?) async throws -> [String: Any] {
            let path = directory.appendingPathComponent("\(label).sqlite3").path
            let db = DatabaseEngine(path: path)
            let store = ArticleStore(database: db)
            await store.initialize()
            let suite = testDefaultsSuite("test.publisher-cancellation")
            let defaults = UserDefaults(suiteName: suite)!
            defer { removeTestDefaults(suite) }
            let settings = AppSettings(defaults: defaults)
            settings.feedURLs = feeds
            settings.aiEnabled = false
            settings.notificationsEnabled = false
            let fetcher = FeedFetcher()
            let manager = FeedManager(
                settings: settings, store: store, schedulesRefresh: false,
                fetchBatch: { urls, allowHTTP in
                    await fetcher.fetchAllFeeds(urls: urls, allowHTTP: allowHTTP, state: db)
                },
                notifyBatch: { _, _ in
                    // Notifications are off and out of scope for this measurement.
                })
            let done = SocketObservation()
            let started = ContinuousClock.now
            let refresh = Task {
                await manager.fetchFeedsAsync()
                let end = ContinuousClock.now
                done.recordText("finished")
                return end
            }
            var result: [String: Any] = ["label": label]
            if let offset {
                try await Task.sleep(for: offset)
                let finishedFirst = done.count == 1
                result["finished_before_cancel"] = finishedFirst
                let cancelled = ContinuousClock.now
                manager.stopBackgroundWork()
                await eventually("Shutdown of a live refresh completes within its deadline", timeout: .seconds(2)) {
                    done.count == 1
                }
                let end = await refresh.value
                if !finishedFirst { result["stop_ms"] = milliseconds(cancelled.duration(to: end)) }
                assertFalse(manager.isAnyFeedLoading, "Shutdown clears refresh loading")
            } else {
                result["refresh_ms"] = milliseconds(started.duration(to: await refresh.value))
                manager.stopBackgroundWork()
            }
            result["articles"] = try await db.counts().total
            result["feed_states"] = try await db.feedFetchStates().count
            await db.close()
            // Validators are only ever stored with the articles they describe, so a later 304 cannot hide unsaved items.
            var handle: OpaquePointer?
            assertEqual(
                sqlite3_open_v2(path, &handle, SQLITE_OPEN_READONLY, nil), SQLITE_OK, "Open the temporary library")
            defer { sqlite3_close(handle) }
            var statement: OpaquePointer?
            sqlite3_prepare_v2(
                handle,
                """
                SELECT COUNT(*) FROM feeds f WHERE (f.etag IS NOT NULL OR f.last_modified IS NOT NULL)
                AND NOT EXISTS (SELECT 1 FROM article_feeds af WHERE af.feed_url = f.url);
                """, -1, &statement, nil)
            assertEqual(sqlite3_step(statement), SQLITE_ROW, "Count validators without articles")
            assertEqual(sqlite3_column_int(statement, 0), 0, "\(label): no feed keeps validators without its articles")
            sqlite3_finalize(statement)
            sqlite3_prepare_v2(handle, "PRAGMA integrity_check;", -1, &statement, nil)
            assertEqual(sqlite3_step(statement), SQLITE_ROW, "Run the integrity check")
            assertEqual(
                sqlite3_column_text(statement, 0).map { String(cString: $0) }, "ok",
                "\(label): the library stays intact")
            sqlite3_finalize(statement)
            return result
        }
        func milliseconds(_ duration: Duration) -> Double {
            Double(duration.components.seconds) * 1000 + Double(duration.components.attoseconds) / 1e15
        }
        var samples: [[String: Any]] = []
        for index in 0..<2 { samples.append(try await run("full-\(index)", cancelAfter: nil)) }
        for offset in [25, 75, 150, 300, 600, 1200] {
            samples.append(try await run("cancel-\(offset)ms", cancelAfter: .milliseconds(offset)))
        }
        // Ordinary completion within the deadline is not evidence: require stops that interrupted live work.
        let full = samples.prefix(2).compactMap { $0["articles"] as? Int }.min() ?? 0
        let active = samples.filter { $0["stop_ms"] != nil }
        assertFalse(active.isEmpty, "At least one stop lands while the refresh is still running")
        assertTrue(
            active.contains { ($0["articles"] as? Int) == 0 && ($0["feed_states"] as? Int) == 0 } && full > 0,
            "A stop during the network phase stores no articles and records no feed outcome")
        for sample in active {
            assertTrue(
                (sample["stop_ms"] as? Double ?? .infinity) < 250,
                "\(sample["label"] ?? ""): the refresh stops promptly")
        }
        let report: [String: Any] = [
            "feeds": feeds.count, "samples": samples, "client": "SecureHTTPClient.shared (production proxy, live TLS)",
        ]
        let data = try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys])
        print("PUBLISHER_CANCELLATION_REPORT " + String(decoding: data, as: UTF8.self))
    }

    @MainActor
    final class WebBoundaryProbe: NSObject, WKNavigationDelegate {
        static func permitsNavigation(_ url: URL) -> Bool {
            url.scheme == "http" && url.host == "rebind.invalid" && url.path == "/page"
                && (url.port == nil || url.port == 80) && url.user == nil && url.password == nil
        }
        func webView(
            _ _: WKWebView, decidePolicyFor navigationAction: WKNavigationAction,
            decisionHandler: @escaping @MainActor @Sendable (WKNavigationActionPolicy) -> Void
        ) {
            guard let url = navigationAction.request.url, Self.permitsNavigation(url) else {
                decisionHandler(.cancel)
                return
            }
            decisionHandler(.allow)
        }
        let once = SocketObservation()
        var complete: ((Result<Void, Error>) -> Void)?
        func webView(_ _: WKWebView, didFinish _: WKNavigation!) {
            if once.claim() { complete?(.success(())) }
        }
        func webView(_ _: WKWebView, didFailProvisionalNavigation _: WKNavigation!, withError error: Error) {
            if once.claim() { complete?(.failure(error)) }
        }
    }

    @MainActor
    static func verifyWebKitBoundary(proxy: ProxyConfiguration) async throws {
        for address in [
            "http://127.0.0.1/page", "https://rebind.invalid/page", "http://rebind.invalid/other",
            "http://rebind.invalid:8080/page", "http://user@rebind.invalid/page",
        ] {
            assertFalse(
                WebBoundaryProbe.permitsNavigation(URL(string: address)!),
                "Probe rejects navigation outside its exact fixture")
        }
        assertTrue(
            WebBoundaryProbe.permitsNavigation(URL(string: "http://rebind.invalid/page")!),
            "Probe allows its controlled fixture")
        let configuration = WKWebViewConfiguration()
        configuration.defaultWebpagePreferences.allowsContentJavaScript = false
        configuration.websiteDataStore = .nonPersistent()
        configuration.websiteDataStore.proxyConfigurations = [proxy]
        let view = WKWebView(frame: .zero, configuration: configuration)
        view.configuration.userContentController.add(try await WebPreviewPolicy.contentRules())
        let probe = WebBoundaryProbe()
        view.navigationDelegate = probe
        defer {
            view.stopLoading()
            view.navigationDelegate = nil
        }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            probe.complete = { continuation.resume(with: $0) }
            Task { @MainActor in
                try? await Task.sleep(for: .seconds(10))
                if probe.once.claim() {
                    view.stopLoading()
                    continuation.resume(throwing: FeedError.timeout)
                }
            }
            view.load(URLRequest(url: URL(string: "http://rebind.invalid/page")!))
        }
    }

    static func respondToFixture(
        _ connection: NWConnection, data: Data?, port: UInt16,
        receivedRequests: SocketObservation, live: Bool
    ) {
        let response: Data
        if data?.starts(with: Data("GET ".utf8)) == true {
            let request = String(decoding: data!, as: UTF8.self).components(separatedBy: "\r\n").first ?? ""
            receivedRequests.recordText(request)
            if request.contains("/redirect.css ") {
                let redirect = Data(
                    "HTTP/1.1 302 Found\r\nLocation: http://127.0.0.1:\(port)/forbidden-redirect\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                        .utf8)
                connection.send(
                    content: redirect, isComplete: true, completion: .contentProcessed { _ in connection.cancel() })
                return
            }
            let body: String
            if request.contains("/page ") {
                body =
                    "<html><head><link rel='stylesheet' href='http://assets.invalid/style.css'><link rel='stylesheet' href='http://assets.invalid/redirect.css'></head><body>Publisher prose<img src='http://assets.invalid/image.svg'><img src='http://127.0.0.1:\(port)/forbidden'><img src='http://localhost:\(port)/forbidden-localhost'><img src='http://2130706433:\(port)/forbidden-decimal'><img src='http://0x7f000001:\(port)/forbidden-hex'><img src='http://127.1:\(port)/forbidden-short'><img src='http://0x7f.0.0.1:\(port)/forbidden-mixed-hex'><img src='http://0177.0.0.1:\(port)/forbidden-octal'><img src='http://%31%32%37.0.0.1:\(port)/forbidden-encoded'><img src='http://user@127.0.0.1:\(port)/forbidden-userinfo'><img src='http://127.0.0.1.:\(port)/forbidden-trailing-dot'>\(live ? "<img src='http://localtest.me:\(port)/forbidden-dns'>" : "")</body></html>"
            } else if request.contains(".svg ") {
                body = "<svg xmlns='http://www.w3.org/2000/svg' width='1' height='1'></svg>"
            } else if request.contains("/style.css ") {
                body = "body { color: black; }"
            } else {
                body = "OK"
            }
            let mime: String
            if request.contains(".svg ") {
                mime = "image/svg+xml"
            } else if request.contains(".css ") {
                mime = "text/css"
            } else {
                mime = "text/html"
            }
            let cacheHeader =
                request.contains("/cached-image.svg ")
                ? "Cache-Control: public, max-age=600\r\n" : "Cache-Control: no-store\r\n"
            response = Data(
                "HTTP/1.1 200 OK\r\n\(cacheHeader)Content-Type: \(mime)\r\nContent-Length: \(body.utf8.count)\r\nConnection: close\r\n\r\n\(body)"
                    .utf8)
        } else {
            response = data ?? Data()
        }
        connection.send(content: response, isComplete: true, completion: .contentProcessed { _ in connection.cancel() })
    }

    static func testCompletionOnce() async {
        print("  - Testing CompletionOnce atomicity...")
        let completion = CompletionOnce()
        let gate = OpenGate()
        await withTaskGroup(of: Bool.self) { group in
            for _ in 0..<100 {
                group.addTask {
                    await gate.wait()
                    return completion.claim()
                }
            }
            await eventually("Every claim worker reaches the start gate") { await gate.arrivals == 100 }
            await gate.open()
            var claims = 0
            for await result in group {
                if result {
                    claims += 1
                }
            }
            assertEqual(claims, 1, "CompletionOnce must allow exactly one claim across concurrent tasks")
        }
        assertFalse(completion.claim(), "The completion stays claimed after all workers finish")
    }

    static func testSocketNetworkBoundary() async throws {
        print("  - Testing socket boundary: pinning, mixed DNS, loopback, malformed commands and fail-closed proxy...")
        let upstream = try NWListener(using: .tcp, on: .any)
        let upstreamQueue = DispatchQueue(label: "test.proxy.upstream")
        let receivedRequests = SocketObservation()
        let live = ProcessInfo.processInfo.environment["NEWS_LIVE_READER_CHECK"] == "1"
        if live {
            assertTrue(
                {
                    if case .blocked = IPAddressValidator.validateHost("localtest.me") { return true }
                    return false
                }(), "Live DNS-alias control resolves to a private address")
        }
        upstream.newConnectionHandler = { connection in
            connection.start(queue: upstreamQueue)
            connection.receive(minimumIncompleteLength: 1, maximumLength: 32768) { data, _, _, _ in
                respondToFixture(
                    connection, data: data, port: upstream.port!.rawValue,
                    receivedRequests: receivedRequests, live: live)
            }
        }
        await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
            let once = SocketObservation()
            upstream.stateUpdateHandler = { state in
                if case .ready = state, once.claim() { continuation.resume() }
            }
            upstream.start(queue: upstreamQueue)
        }
        defer { upstream.cancel() }
        let fixturePort = upstream.port!
        let observed = SocketObservation()
        let connector: NetworkBoundaryProxy.Connector = { host, _ in
            observed.record(host)
            return NWConnection(host: "127.0.0.1", port: fixturePort, using: .tcp)
        }
        let mixed = NetworkBoundaryProxy(
            resolver: { _ in .allowed(ips: ["93.184.216.34", "127.0.0.1"]) }, connector: connector)
        let (mixedClient, mixedReply) = try await socksConnect(mixed, host: "mixed.invalid")
        assertEqual(mixedReply[1], 2, "Mixed public/private DNS answers are rejected before connecting")
        mixedClient.cancel()
        await mixed.stop()
        let production = NetworkBoundaryProxy(connector: connector)
        for host in [
            "127.0.0.1", "localhost", "2130706433", "0x7f000001", "localhost.", "test.local.", "intranet", "::1",
            "fe80::1%en0",
        ] {
            let (client, reply) = try await socksConnect(production, host: host)
            assertEqual(reply[1], 2, "Private/alternate/scoped address denied at the socket boundary")
            client.cancel()
        }
        let (udpClient, udpReply) = try await socksConnect(production, host: "93.184.216.34", command: 3)
        assertEqual(udpReply[1], 2, "UDP ASSOCIATE is denied")
        try await socketSend(udpClient, Data("trailing".utf8))
        do {
            _ = try await socketRead(udpClient, count: 1)
            assertTrue(false, "Rejected tunnel never relays trailing client bytes")
        } catch let error as FeedError {
            assertEqual(error, .network("EOF"), "Rejected tunnel drains unread bytes and closes without a reset")
        }
        udpClient.cancel()
        let (portClient, portReply) = try await socksConnect(production, host: "93.184.216.34", port: 22)
        assertEqual(portReply[1], 2, "Unapproved ports denied")
        portClient.cancel()
        assertEqual(observed.count, 0, "Rejected requests never construct an upstream connection")
        await production.stop()
        let allowed = NetworkBoundaryProxy(
            resolver: { host in
                ["rebind.invalid", "93.184.216.34", "assets.invalid"].contains(host)
                    ? .allowed(ips: ["93.184.216.34"]) : IPAddressValidator.validateHost(host)
            }, connector: connector)
        let (client, reply) = try await socksConnect(allowed, host: "rebind.invalid")
        assertEqual(reply[1], 0, "Approved destinations connect")
        try await socketSend(client, Data("relay proof".utf8))
        assertEqual(
            try await socketRead(client, count: 11), Data("relay proof".utf8),
            "Tunnel forwards data without rewriting it")
        client.cancel()
        assertEqual(
            observed.hosts, ["93.184.216.34"], "Connector receives the validated numeric IP, never the DNS hostname")
        let configuration = URLSessionConfiguration.ephemeral
        let proxy = try await allowed.configuration()
        assertFalse(proxy.allowFailover, "Native proxy may not fall back to direct connections")
        configuration.proxyConfigurations = [proxy]
        configuration.timeoutIntervalForRequest = 2
        let session = URLSession(configuration: configuration)
        let (body, _) = try await session.data(from: URL(string: "http://93.184.216.34/")!)
        assertEqual(String(decoding: body, as: UTF8.self), "OK", "Native URLSession uses the protected SOCKS tunnel")
        // Native image caching must reuse bytes without bypassing destination policy.
        let imageConfiguration = URLSessionConfiguration.ephemeral
        imageConfiguration.proxyConfigurations = [proxy]
        imageConfiguration.timeoutIntervalForRequest = 2
        imageConfiguration.urlCache = URLCache(memoryCapacity: 1024 * 1024, diskCapacity: 0)
        let imageClient = SecureHTTPClient(configuration: imageConfiguration)
        let imageURL = URL(string: "http://93.184.216.34/cached-image.svg")!
        let initialRequests = receivedRequests.count
        let (firstImage, _) = try await imageClient.fetchImage(from: imageURL, allowHTTP: true)
        let (cachedImage, _) = try await imageClient.fetchImage(from: imageURL, allowHTTP: true)
        assertEqual(cachedImage, firstImage, "Cached image preserves publisher bytes")
        assertEqual(receivedRequests.count, initialRequests + 1, "Fresh images use one protected upstream request")
        do {
            _ = try await imageClient.fetchImage(from: imageURL)
            assertTrue(false, "Cached HTTP images cannot bypass disabled HTTP policy")
        } catch is URLError {
            // With HTTP off the address is requested over HTTPS instead (#794), which this plain-HTTP fixture cannot
            // answer: the cached http bytes are never returned.
        }
        _ = try await imageClient.fetchArticleHTML(from: imageURL, allowHTTP: true)
        assertEqual(receivedRequests.count, initialRequests + 2, "Article fetching still reloads cached URLs")
        let uncachedURL = URL(string: "http://93.184.216.34/uncached-image.svg")!
        _ = try await imageClient.fetchImage(from: uncachedURL, allowHTTP: true)
        _ = try await imageClient.fetchImage(from: uncachedURL, allowHTTP: true)
        assertEqual(receivedRequests.count, initialRequests + 4, "No-store images are fetched again")
        try await verifyWebKitBoundary(proxy: proxy)
        let paths = receivedRequests.hosts
        assertTrue(paths.contains { $0.contains("/style.css ") }, "WebKit stylesheet traverses the protected proxy")
        assertTrue(paths.contains { $0.contains("/image.svg ") }, "WebKit image traverses the protected proxy")
        assertFalse(
            paths.contains { $0.contains("/forbidden") }, "WebKit does not contact the reachable private fixture")
        await allowed.stop()
        let requestCount = receivedRequests.count
        do {
            _ = try await session.data(from: URL(string: "http://rebind.invalid/forbidden-after-stop")!)
            assertTrue(false, "Stopped gateway must not fall back to direct transport")
        } catch {
            // Failure is expected: the preceding assertion rejects an unexpected success.
        }
        assertEqual(
            receivedRequests.count, requestCount, "Stopped proxy never falls back to a reachable direct endpoint")
        if live {
            let publicURL = URL(string: "https://www.nasa.gov/feed/")!
            let directControl = URLSession(configuration: .ephemeral)
            let (controlBody, _) = try await directControl.data(from: publicURL)
            assertFalse(controlBody.isEmpty, "Public control is reachable without the stopped proxy")
            directControl.invalidateAndCancel()
            do {
                _ = try await session.data(from: publicURL)
                assertTrue(false, "Stopped proxy cannot fall back to a proven reachable public host")
            } catch {
                // The stopped proxy must reject the otherwise reachable public endpoint.
            }
        }
        session.invalidateAndCancel()
        for host in ["::127.0.0.1", "2002:7f00:1::", "2001::1", "2001:db8::1", "198.18.0.1", "192.0.2.1"] {
            assertTrue(
                IPAddressValidator.checkLiteralIP(host) != nil,
                "Transition/reserved addresses cannot escape the public boundary")
        }
        // A gateway that stopped or failed after startup restarts on next use; the client follows its new port.
        let gatewayClient = SecureHTTPClient(gateway: allowed, resolver: { _ in .allowed(ips: ["93.184.216.34"]) })
        let restartURL = URL(string: "http://93.184.216.34/restart")!
        let (beforeStop, _) = try await gatewayClient.fetchArticleHTML(from: restartURL, allowHTTP: true)
        assertEqual(String(decoding: beforeStop, as: UTF8.self), "OK", "The client reaches the gateway it started")
        await allowed.stop()
        let (afterStop, _) = try await gatewayClient.fetchArticleHTML(from: restartURL, allowHTTP: true)
        assertEqual(
            String(decoding: afterStop, as: UTF8.self), "OK", "The next request after a gateway stop succeeds")
        await allowed.stop()
    }

    actor TestCounter {
        var value: Int = 0
        func increment() { value += 1 }
    }

    struct SimulatedRefreshError: Error, Equatable {}

    static func testSignpostHelperExecution() async {
        print("  - Testing OSSignposter Measure Execution & Error Propagation (Sync & Async)...")

        // 1. Synchronous helper executes work and returns result
        let result = NewsSignposts.measure(
            signposter: NewsSignposts.database, name: "TestMeasure", metadata: "test=true"
        ) {
            return 42
        }
        assertEqual(result, 42, "measure should return work value")

        // 2. Synchronous helper propagates thrown errors
        struct TestError: Error, Equatable {}
        var caughtError = false
        do {
            try NewsSignposts.measure(signposter: NewsSignposts.feeds, name: "TestError") {
                throw TestError()
            }
        } catch is TestError {
            caughtError = true
        } catch {
            assertTrue(false, "measure must preserve the original error type")
        }
        assertTrue(caughtError, "measure should propagate thrown error")

        // 3. Asynchronous helper executes async work and returns result
        let asyncResult = try? await NewsSignposts.measure(
            signposter: NewsSignposts.database, name: "TestAsyncMeasure", metadata: "async=true"
        ) {
            try await Task.sleep(nanoseconds: 1_000_000)
            return 84
        }
        assertEqual(asyncResult, 84, "async measure should return async work value")

        // 4. Asynchronous helper propagates thrown errors
        var caughtAsyncError = false
        do {
            try await NewsSignposts.measure(signposter: NewsSignposts.feeds, name: "TestAsyncError") {
                try await Task.sleep(nanoseconds: 1_000_000)
                throw TestError()
            }
        } catch is TestError {
            caughtAsyncError = true
        } catch {
            assertTrue(false, "async measure must preserve the original error type")
        }
        assertTrue(caughtAsyncError, "async measure should propagate thrown error")
    }

    @MainActor
    static func testOnboardingAndPermissionTiming() async {
        print("  - Testing the first-launch setting and the deferred notification request (#562)...")
        // The flow walks forward and back one step at a time, from Welcome to Done.
        var walked = [OnboardingStep.welcome]
        while let next = walked.last?.next { walked.append(next) }
        assertEqual(walked, OnboardingStep.allCases, "Continue visits every step once, in order")
        assertEqual(
            walked.map(\.title),
            [
                "Welcome to News", "Choose Your Feeds", "Pick Your Sections", "On-Device Intelligence",
                "Notifications", "You're All Set",
            ], "Each step has its own screen")
        var back = [OnboardingStep.done]
        while let previous = back.last?.previous { back.append(previous) }
        assertEqual(back, walked.reversed(), "Back retraces the same steps")
        assertTrue(OnboardingStep.welcome.previous == nil, "Welcome has no Back")
        assertTrue(OnboardingStep.done.isLast && !OnboardingStep.notifications.isLast, "Only Done is last")
        assertEqual(OnboardingStep.done.continueTitle, "Start Reading", "The last step starts reading")
        assertEqual(OnboardingStep.feeds.continueTitle, "Continue", "Other steps continue")
        assertEqual(OnboardingStep.feeds.position, "Step 2 of 6", "The indicator names the step and the count")
        assertTrue(walked.allSatisfy { !$0.tip.isEmpty && $0.companions.count <= 3 }, "Every step has a tip and art")
        func suite(_ name: String, seed: [String: Any] = [:]) -> (String, UserDefaults) {
            let name = testDefaultsSuite(name)
            let defaults = UserDefaults(suiteName: name)!
            for (key, value) in seed { defaults.set(value, forKey: key) }
            return (name, defaults)
        }
        let (freshName, fresh) = suite("onboarding-fresh")
        let (feedsName, feeds) = suite(
            "onboarding-feeds", seed: [AppSettings.feedURLsKey: ["https://example.com/feed"]])
        let (modeName, mode) = suite("onboarding-mode", seed: [AppSettings.notificationModeKey: "full"])
        defer { for name in [freshName, feedsName, modeName] { removeTestDefaults(name) } }
        assertFalse(AppSettings(defaults: fresh).firstLaunchCompleted, "A fresh install shows the first-launch sheet")
        assertFalse(AppSettings(defaults: fresh).firstLaunchCompleted, "A sheet closed by quitting shows again")
        AppSettings(defaults: fresh).completeFirstLaunch()
        assertTrue(AppSettings(defaults: fresh).firstLaunchCompleted, "Completing the sheet persists")
        assertTrue(AppSettings(defaults: feeds).firstLaunchCompleted, "Existing subscriptions skip the sheet")
        assertTrue(AppSettings(defaults: mode).firstLaunchCompleted, "Settings from an earlier version skip the sheet")

        // The permission request waits for a refresh that leaves stories, the closed sheet and the setting.
        // Refreshes deliver nothing until `delivering` is incremented; then each feed brings one story.
        func manager(_ settings: AppSettings, delivering: TestCounter) async -> FeedManager {
            settings.aiEnabled = false
            let store = ArticleStore(database: DatabaseEngine(path: ":memory:"))
            await store.initialize()
            return FeedManager(
                settings: settings, store: store, schedulesRefresh: false,
                fetchBatch: { urls, _ in
                    guard await delivering.value > 0 else { return [] }
                    return urls.map { url in
                        let story = FeedArticle(
                            title: "First story", link: "https://example.com/onboarding/story", guid: "first",
                            description: "", pubDate: Date(), source: "Publisher")
                        return (url, [story], nil, nil)
                    }
                },
                notifyBatch: { _, _ in }, imageFinder: .unavailable)
        }
        let (newName, newDefaults) = suite("onboarding-permission")
        let (offName, offDefaults) = suite("onboarding-permission-off")
        defer { for name in [newName, offName] { removeTestDefaults(name) } }
        let settings = AppSettings(defaults: newDefaults)
        let delivering = TestCounter()
        let feedManager = await manager(settings, delivering: delivering)
        var requests = 0
        var requestedMidRefresh = false
        let request = NotificationPermissionRequest(feedManager: feedManager, settings: settings) {
            requests += 1
            requestedMidRefresh = requestedMidRefresh || feedManager.isAnyFeedLoading
        }
        assertEqual(requests, 0, "Nothing is asked at launch")
        settings.completeFirstLaunch()
        await feedManager.fetchFeedsAsync()
        assertEqual(requests, 0, "A refresh that brings no stories does not ask")
        await delivering.increment()
        await feedManager.fetchFeedsAsync()
        assertTrue(!feedManager.articles.isEmpty, "The second refresh brings a story")
        assertEqual(requests, 1, "The first refresh with stories asks once")
        assertFalse(requestedMidRefresh, "After an empty refresh, the next one asks only once it has completed")
        await feedManager.fetchFeedsAsync()
        settings.setNotificationsEnabled(false)
        settings.setNotificationsEnabled(true)
        assertEqual(requests, 1, "Later refreshes and toggles in the same launch do not ask again")
        assertTrue(request.hasRequested, "The request records that it asked")
        feedManager.stopBackgroundWork()

        // Stories and a refresh first: the sheet's closing, then turning notifications on, decide.
        let quiet = AppSettings(defaults: offDefaults)
        quiet.setNotificationsEnabled(false)
        let quietDelivering = TestCounter()
        await quietDelivering.increment()
        let quietManager = await manager(quiet, delivering: quietDelivering)
        var quietRequests = 0
        let quietRequest = NotificationPermissionRequest(feedManager: quietManager, settings: quiet) {
            quietRequests += 1
        }
        await quietManager.fetchFeedsAsync()
        assertEqual(quietRequests, 0, "Nothing is asked while the first-launch sheet is open")
        quiet.completeFirstLaunch()
        assertEqual(quietRequests, 0, "With notifications off, closing the sheet does not ask")
        quiet.setNotificationsEnabled(true)
        assertEqual(quietRequests, 1, "Turning notifications on after a refresh with stories asks")
        assertTrue(quietRequest.hasRequested, "The request records that it asked")
        quietManager.stopBackgroundWork()
    }

    @MainActor
    static func testAppSettingsIsolationAndURLNormalization() async {
        print("  - Testing AppSettings UserDefaults Isolation & URLComponents Normalization...")

        let badgeSuite = testDefaultsSuite("test.dock-badge")
        let badgeDefaults = UserDefaults(suiteName: badgeSuite)!
        defer { removeTestDefaults(badgeSuite) }
        assertTrue(AppSettings(defaults: badgeDefaults).showsDockBadge, "The Dock badge is on by default")
        AppSettings(defaults: badgeDefaults).setShowsDockBadge(false)
        assertFalse(AppSettings(defaults: badgeDefaults).showsDockBadge, "Turning the Dock badge off persists")

        // 1. URLComponents Normalization
        let httpFeed = "http://feeds.arstechnica.com/arstechnica/index"
        let normalizedHTTPS = AppSettings.normalizeFeedURL(httpFeed, allowInsecureHTTP: false)
        assertEqual(
            normalizedHTTPS, "https://feeds.arstechnica.com/arstechnica/index",
            "Should upgrade http to https when allowInsecureHTTP is false")

        let preservedHTTP = AppSettings.normalizeFeedURL(httpFeed, allowInsecureHTTP: true)
        assertEqual(
            preservedHTTP, "http://feeds.arstechnica.com/arstechnica/index",
            "Should preserve http when allowInsecureHTTP is true")

        let upperHost = "HTTPS://FEEDS.BBCO.CO.UK/NEWS/RSS.XML/"
        let normalizedUpper = AppSettings.normalizeFeedURL(upperHost)
        assertEqual(
            normalizedUpper, "https://feeds.bbco.co.uk/NEWS/RSS.XML/",
            "Host must be lowercased; a meaningful trailing slash is kept")

        for slashed in [
            "https://www.japantimes.co.jp/feed/", "https://www.eurointegration.com.ua/rss/",
            "https://phys.org/rss-feed/",
            "https://www.theatlantic.com/feed/channel/culture/", "https://www.scmp.com/rss/91/feed/",
        ] {
            assertEqual(
                AppSettings.normalizeFeedURL(slashed), slashed,
                "Feeds served only with a trailing slash keep it: \(slashed)")
        }
        assertEqual(
            AppSettings.normalizeFeedURL("http://phys.org/rss-feed/"), "https://phys.org/rss-feed/",
            "HTTPS upgrade still applies to slashed paths")
        assertEqual(
            AppSettings.normalizeFeedURL("https://example.com/feed/?a=1"), "https://example.com/feed/?a=1",
            "Query follows the kept slash")
        assertEqual(
            AppSettings.normalizeFeedURL("https://example.com/a%2Fb/"), "https://example.com/a%2Fb/",
            "Encoded path is not rewritten")

        let bareDomain = "example.com/"
        let normalizedBare = AppSettings.normalizeFeedURL(bareDomain)
        assertEqual(
            normalizedBare, "https://example.com", "Bare domain should gain https scheme and drop the root slash")

        // #797: a pasted feed: address is unwrapped; any other explicit scheme is refused, not prefixed.
        assertEqual(
            AppSettings.normalizeFeedURL("feed://example.com/rss"), "https://example.com/rss",
            "feed:// addresses are unwrapped")
        assertEqual(
            AppSettings.normalizeFeedURL("feed:https://example.com/rss"), "https://example.com/rss",
            "feed:https:// addresses are unwrapped")
        for refused in [
            "ftp://example.com/rss", "webcal://example.com/cal", "file:///etc/passwd", "javascript:alert(1)",
        ] {
            assertTrue(AppSettings.normalizeFeedURL(refused) == nil, "\(refused) is not a feed address")
        }
        assertEqual(
            AppSettings.normalizeFeedURL("example.com:8443/feed"), "https://example.com:8443/feed",
            "A host with a port still gets https")
        assertEqual(
            AppSettings.normalizeFeedURL("feed: https://example.com/rss"), "https://example.com/rss",
            "A space after feed: is ignored")
        assertEqual(
            AppSettings.normalizeFeedURL("user:pass@example.com/rss"), "https://user:pass@example.com/rss",
            "Credentials without a scheme are not mistaken for a scheme")
        assertTrue(AppSettings.normalizeFeedURL("[2001:db8::1]/feed") != nil, "A bracketed IPv6 host is accepted")
        assertTrue(
            AppSettings.normalizeFeedURL("ftp:user:pass@example.com/rss") == nil,
            "An explicit unsupported scheme is refused before credentials are read")
        assertEqual(
            AppSettings.addFeedFailureMessage(for: "ftp://example.com/rss"),
            "Feed not added. ftp: addresses are not supported. Use an http or https feed address.",
            "Add Feed names a refused scheme")
        assertEqual(
            AppSettings.addFeedFailureMessage(for: "https://example.com/rss"),
            "Feed not added. Check the URL or whether you already subscribe.",
            "A web address keeps the generic failure text")
        assertEqual(
            AppSettings.normalizeFeedURL("feed:8443/rss"), "https://feed:8443/rss",
            "feed: followed by a port is a host named feed, not a wrapper")
        let invalidURL = AppSettings.normalizeFeedURL("")
        assertEqual(invalidURL, nil, "Empty string should return nil")

        // 2. Injected UserDefaults Isolation
        let suiteName = testDefaultsSuite("test.settings.isolation")
        let tempDefaults = UserDefaults(suiteName: suiteName)!
        defer { removeTestDefaults(suiteName) }

        let settings = AppSettings(defaults: tempDefaults)
        _ = settings.addFeed(url: "https://isolated.example.com/rss.xml")
        settings.addSection("IsolatedSection")

        // Verify stored in tempDefaults
        let storedFeeds = tempDefaults.stringArray(forKey: AppSettings.feedURLsKey) ?? []
        assertTrue(
            storedFeeds.contains("https://isolated.example.com/rss.xml"),
            "Injected defaults must receive feedURLs mutations")

        let storedSections = tempDefaults.stringArray(forKey: AppSettings.userSectionsKey) ?? []
        assertTrue(storedSections.contains("IsolatedSection"), "Injected defaults must receive userSections mutations")

        assertEqual(AppSettings.feedKey("https://example.com"), "https://example.com", "A root URL is its own key")
        assertEqual(
            AppSettings.feedKey("https://example.com/feed/"), "https://example.com/feed",
            "One trailing slash is ignored")
        assertEqual(
            AppSettings.feedKey("https://example.com/feed//"), "https://example.com/feed/",
            "Only one trailing slash is ignored")
        assertEqual(
            AppSettings.feedKey("https://example.com/feed/?a=1"), "https://example.com/feed?a=1",
            "The query stays in the key")
        // 3. Slash variants are one subscription; the URL is stored as given and stored subscriptions are never rewritten
        let slashSuite = testDefaultsSuite("test.settings.slash")
        let slashDefaults = UserDefaults(suiteName: slashSuite)!
        defer { removeTestDefaults(slashSuite) }
        slashDefaults.set(["https://legacy.example.com/feed"], forKey: AppSettings.feedURLsKey)
        let slashSettings = AppSettings(defaults: slashDefaults)
        assertEqual(
            slashSettings.feedURLs, ["https://legacy.example.com/feed"], "Stored subscriptions are not migrated")
        assertEqual(
            slashSettings.addFeed(url: "https://legacy.example.com/feed/"), nil,
            "Slash variant of a stored subscription is a duplicate")
        assertEqual(
            slashSettings.addFeed(url: "https://Slash.example.com/feed/"), "https://slash.example.com/feed/",
            "Slashed feed is stored as given")
        assertEqual(
            slashSettings.addFeed(url: "https://slash.example.com/feed"), nil,
            "Slashless variant of a slashed subscription is a duplicate")
        assertEqual(
            slashSettings.addFeed(url: "https://slash.example.com/feed//"), "https://slash.example.com/feed//",
            "Only one trailing slash is insignificant")
        let opml = Data(
            "<opml><body><outline xmlUrl=\"https://opml.example.com/rss/\"/><outline xmlUrl=\"https://opml.example.com/rss\"/><outline xmlUrl=\"https://legacy.example.com/feed/\"/></body></opml>"
                .utf8)
        assertEqual(
            slashSettings.importFeeds(from: opml), 1,
            "OPML import adds one of two slash variants and skips subscribed ones")
        assertEqual(
            slashSettings.feedURLs.suffix(1), ["https://opml.example.com/rss/"],
            "OPML import keeps the first form as given")
        slashSettings.removeFeed(url: "https://legacy.example.com/feed")
        assertEqual(
            slashSettings.addFeed(url: "https://legacy.example.com/feed/"), "https://legacy.example.com/feed/",
            "Removing the stored form frees the slash variant")
        _ = slashSettings.addFeed(url: "https://removal.example.com/feed/")
        slashSettings.removeFeed(url: "https://removal.example.com/feed")
        assertFalse(
            slashSettings.feedURLs.contains { AppSettings.feedKey($0) == "https://removal.example.com/feed" },
            "Removing the slashless form removes a slash-stored subscription")
        _ = slashSettings.addFeed(url: "https://removal.example.com/plain")
        slashSettings.removeFeed(url: "https://removal.example.com/plain/")
        assertFalse(
            slashSettings.feedURLs.contains { AppSettings.feedKey($0) == "https://removal.example.com/plain" },
            "Removing the slash form removes a slashless subscription")
        assertEqual(
            slashDefaults.stringArray(forKey: AppSettings.feedURLsKey), slashSettings.feedURLs,
            "Slash-preserving subscriptions persist as given")
        if let catalogFeed = FeedCatalog.feeds.first(where: { !$0.url.contains("?") && !$0.url.hasSuffix("/") }) {
            _ = slashSettings.addFeed(url: catalogFeed.url + "/")
            assertTrue(
                slashSettings.isSubscribed(catalogFeed), "A slash variant of a catalog feed counts as subscribed")
            assertEqual(
                slashSettings.addCatalogFeeds([catalogFeed, catalogFeed]), 0, "Catalog subscribe skips slash variants")
            assertTrue(
                !CatalogReviewEngine.detectTopicGaps(subscribedURLs: [catalogFeed.url + "/"]).contains {
                    $0.catalogSet == catalogFeed.set
                }, "A slash variant covers its catalog set")
        }
    }

    static func testFixedTaxonomyAndCaseInsensitivity() async {
        print("  - Testing Fixed Taxonomy (12 Categories), Synonyms & Case Insensitivity...")

        // 1. Exactly 12 categories
        assertEqual(NewsCategory.allCases.count, 12, "Taxonomy must define exactly 12 standard categories")

        // 2. Direct case-insensitive matching
        assertEqual(NewsCategory.match(from: "technology"), .technology, "lowercase 'technology'")
        assertEqual(NewsCategory.match(from: "TECHNOLOGY"), .technology, "uppercase 'TECHNOLOGY'")
        assertEqual(NewsCategory.match(from: "  Science  "), .science, "trimmed 'Science'")
        assertEqual(NewsCategory.match(from: "Business"), .business, "standard 'Business'")
        assertEqual(NewsCategory.match(from: "politics"), .politics, "standard 'politics'")
        assertEqual(NewsCategory.match(from: "world"), .world, "standard 'world'")
        assertEqual(NewsCategory.match(from: "Sports"), .sports, "standard 'Sports'")
        assertEqual(NewsCategory.match(from: "entertainment"), .entertainment, "standard 'entertainment'")
        assertEqual(NewsCategory.match(from: "Health"), .health, "standard 'Health'")
        assertEqual(NewsCategory.match(from: "Travel"), .travel, "standard 'Travel'")
        assertEqual(NewsCategory.match(from: "Food"), .food, "standard 'Food'")
        assertEqual(NewsCategory.match(from: "Fashion"), .fashion, "standard 'Fashion'")
        assertEqual(NewsCategory.match(from: "Lifestyle"), .lifestyle, "standard 'Lifestyle'")

        // 3. Synonym and substring matching
        assertEqual(NewsCategory.match(from: "tech news"), .technology, "tech synonym")
        assertEqual(NewsCategory.match(from: "election 2026"), .politics, "election synonym")
        assertEqual(NewsCategory.match(from: "space exploration"), .science, "space synonym")
        assertEqual(NewsCategory.match(from: "market finance"), .business, "finance synonym")
        assertEqual(NewsCategory.match(from: "international affairs"), .world, "international synonym")
        assertEqual(NewsCategory.match(from: "movie reviews"), .entertainment, "movie synonym")
        assertEqual(NewsCategory.match(from: "medical research"), .health, "med synonym")
        assertEqual(NewsCategory.match(from: "culinary arts"), .food, "cook/food synonym")

        // Whole words only (#507): a substring of a longer word is not a cue.
        assertEqual(NewsCategory.match(from: "Wildlife"), nil, "Wildlife is not Lifestyle")
        assertEqual(NewsCategory.match(from: "Stockholm"), nil, "Stockholm is not Business")
        assertEqual(NewsCategory.match(from: "Homeland Security"), nil, "Homeland is not a home")
        assertEqual(NewsCategory.match(from: "Archipelago"), nil, "Archipelago is not a chip")
        assertEqual(NewsCategory.match(from: "Ivy League"), .sports, "A whole-word cue still matches")
        assertEqual(NewsCategory.match(from: "Life & Style"), .lifestyle, "Life & Style is Lifestyle")
        assertEqual(NewsCategory.match(from: "Style"), .fashion, "Style alone is Fashion")
        assertEqual(NewsCategory.match(from: "Fintech"), .technology, "Fintech is Technology")

        // 4. Rejection of unmapped gibberish
        assertEqual(NewsCategory.match(from: "random-gibberish-string-xyz"), nil, "Unrelated strings should return nil")
        assertEqual(NewsCategory.match(from: ""), nil, "Empty string should return nil")
    }

    static func testClassificationMultiStageAndConfidenceTiers() async {
        print("  - Testing Multi-Stage Classification & Confidence Tiers...")

        let classifier = ArticleClassifier.shared

        // Stage 1: RSS Category deterministic hint takes immediate precedence with 0.95 confidence
        let rssResult = await classifier.classify(
            title: "Generic Headline With No Clues",
            description: "Some description here",
            rssCategory: "Technology"
        )
        assertEqual(rssResult.category, "Technology", "RSS hint should determine category")
        assertTrue(rssResult.confidence >= 0.90, "RSS hint should provide >= 0.90 confidence")
        assertTrue(rssResult.evidence.contains("Technology"), "Evidence should include RSS category")

        // Stage 2: Strong keyword title/description scoring
        let techResult = await classifier.classify(
            title: "Apple Announces M-Series Silicon Processor With Neural Acceleration",
            description: "Novel semiconductor architecture speeds machine learning and developer workflows",
            rssCategory: nil
        )
        assertEqual(techResult.category, "Technology", "Strong tech keywords must classify as Technology")
        assertTrue(techResult.confidence >= 0.70, "Confidence should exceed 0.70")
        assertTrue(!techResult.evidence.isEmpty, "Evidence should list matched keywords")

        // Stage 3: Fallback when no keywords match
        let genericResult = await classifier.classify(
            title: "Unspecified Developments Reported",
            description: "Updates will follow as events occur",
            rssCategory: nil
        )
        assertTrue(!genericResult.category.isEmpty, "Default category must be assigned")
    }

    static func testClassificationBenchmarkDataset() async {
        print("  - Testing Classification Benchmark Dataset Across All 12 Categories...")

        struct BenchmarkItem {
            let title: String
            let description: String
            let expectedCategory: NewsCategory
        }

        let dataset: [BenchmarkItem] = [
            BenchmarkItem(
                title: "NVIDIA Unveils Next-Gen AI Chip Architecture for Supercomputing",
                description: "The new GPU silicon accelerates neural network training and cloud datacenter workloads.",
                expectedCategory: .technology
            ),
            BenchmarkItem(
                title: "James Webb Space Telescope Observes Oldest Known Galaxy in Deep Space",
                description:
                    "Astronomers confirm cosmological distance and stellar composition using infrared spectroscopy.",
                expectedCategory: .science
            ),
            BenchmarkItem(
                title: "Federal Reserve Holds Interest Rates Steady As Wall Street Stock Rally Continues",
                description:
                    "Investors react positively to central bank inflation forecast and corporate earnings reports.",
                expectedCategory: .business
            ),
            BenchmarkItem(
                title: "Senate Committee Advances Bipartisan Election Security and Campaign Finance Bill",
                description: "Lawmakers vote in favor of new regulatory oversight before the congressional recess.",
                expectedCategory: .politics
            ),
            BenchmarkItem(
                title: "United Nations Envoy Brokering Ceasefire Talks In International Conflict",
                description: "Global diplomats convene in Geneva to negotiate refugee corridors and humanitarian aid.",
                expectedCategory: .world
            ),
            BenchmarkItem(
                title: "Quarterback Leads NFL Team to Super Bowl Championship Victory",
                description: "The thrilling stadium final concluded with a game-winning touchdown in overtime.",
                expectedCategory: .sports
            ),
            BenchmarkItem(
                title: "Hollywood Director Christopher Nolan Wins Best Director at Academy Awards",
                description: "The blockbuster cinema release dominated the Oscars ceremony with multiple awards.",
                expectedCategory: .entertainment
            ),
            BenchmarkItem(
                title: "Clinical Trial Demonstrates High Efficacy for Targeted Cancer Immunotherapy Drug",
                description:
                    "Hospital oncologists report remission in patients receiving the breakthrough medical treatment.",
                expectedCategory: .health
            ),
            BenchmarkItem(
                title: "International Airlines Expand Non-Stop Flight Routes for Summer Vacation Travelers",
                description: "Tourists book resort hotels and sightseeing packages as travel demand surges.",
                expectedCategory: .travel
            ),
            BenchmarkItem(
                title: "Michelin-Starred Chef Opens New Restaurant Celebrating Seasonal Farm-to-Table Cuisine",
                description:
                    "The tasting menu pairs fine dining dishes with artisanal wines and local pastry desserts.",
                expectedCategory: .food
            ),
            BenchmarkItem(
                title: "Luxury Fashion House Debuts Autumn Haute Couture Collection on Paris Runway",
                description:
                    "Designer apparel, bespoke tailoring, and statement accessories set seasonal wardrobe trends.",
                expectedCategory: .fashion
            ),
            BenchmarkItem(
                title: "Interior Designers Share Tips for Creating a Mindful, Minimalist Home Garden",
                description:
                    "Transform your living space with sustainable furniture, decluttering habits, and indoor plants.",
                expectedCategory: .lifestyle
            ),
        ]

        var correctCount = 0
        for item in dataset {
            let result = await ArticleClassifier.shared.classify(
                title: item.title,
                description: item.description,
                rssCategory: nil
            )
            if result.category == item.expectedCategory.rawValue {
                correctCount += 1
            } else {
                print(
                    "    ⚠️ Benchmark mismatch: '\(item.title)' -> classified as \(result.category), expected \(item.expectedCategory.rawValue)"
                )
            }
        }

        let accuracy = Double(correctCount) / Double(dataset.count)
        print("    Classification accuracy: \(correctCount)/\(dataset.count) (\(Int(accuracy * 100))%)")
        assertTrue(accuracy >= 0.80, "Benchmark accuracy must meet or exceed 80% on ground-truth dataset")
    }

    @MainActor
    static func testOverviewPublisherEvidence(fixtureHost: String) async throws {
        print("  - Testing overview publisher text: thin evidence, deadline, shared fetches and version checks...")
        func article(_ id: String, _ source: String) -> FeedArticle {
            FeedArticle(
                storedID: id, title: "\(source) on the harbor bridge", link: "https://\(fixtureHost)/\(id)", guid: id,
                description: "The harbor bridge reopened after repairs, \(source) reported.", pubDate: Date(),
                source: source)
        }
        func page(_ name: String) -> String {
            """
            \(name) said the harbor bridge reopened to traffic on Monday morning. Crews from \(name) worked through \
            the weekend on the deck. The first buses crossed shortly after six o'clock.

            Engineers told \(name) that two damaged support cables were replaced. The city council approved the \
            final inspection for \(name) on Sunday. Commuters told \(name) the detour had added twenty minutes.
            """
        }
        func success(_ text: String) -> ExtractionOutcome { .success(content: text, imageUrl: nil, document: nil) }
        // Thin evidence: feed summaries alone never reach the model.
        let calls = TestCounter()
        let refusing = NewsTextModel { prompt, _ in
            if prompt.contains("Return plain text only:") { await calls.increment() }
            return "I refuse"
        }
        let (a, b) = (article("ev-a", "Publisher A"), article("ev-b", "Publisher B"))
        let summaries = OverviewPassageSelector().selectPassages(from: [a, b]).passages
        let summaryFallback = OverviewComposer.composeOverview(
            eventID: "thin", eventTitle: "Harbor bridge", verifiedFacts: [], passages: summaries, articles: [a, b])
        let thin = try await OverviewComposer.composeWithModelOutcome(
            fallback: summaryFallback, passages: summaries, articles: [a, b], model: refusing)
        assertEqual(thin.outcome.result, .thinEvidence, "Feed summaries alone are thin evidence")
        assertEqual(await calls.value, 0, "Thin evidence never reaches the model")
        let repeated = String(repeating: "The harbor bridge reopened to traffic on Monday morning. ", count: 6)
        assertFalse(
            OverviewComposer.hasSufficientEvidence([
                EvidencePassage(id: "r1", articleID: a.id, text: repeated),
                EvidencePassage(id: "r2", articleID: b.id, text: repeated),
            ]), "Repeated sentences count once")
        assertFalse(
            OverviewComposer.hasSufficientEvidence([EvidencePassage(id: "one", articleID: a.id, text: page("A"))]),
            "One article alone is not enough to synthesize")

        let database = DatabaseEngine(path: ":memory:")
        try await database.open()
        let store = ArticleStore(database: database)
        let log = ExtractionLog()
        let pages = TestPages()
        let extractor: @Sendable (String) async -> ExtractionOutcome = { link in
            await log.begin(link)
            let reply = await pages.reply(for: link)
            if reply.delay > .zero { try? await Task.sleep(for: reply.delay) }
            await reply.gate?.wait()
            await log.end()
            await reply.during?()
            return reply.outcome
        }
        func coordinator(deadline: Duration = .seconds(4)) -> OverviewGenerationCoordinator {
            OverviewGenerationCoordinator(
                store: store, queue: EnrichmentQueue(store: store), allowsEnergy: { true },
                extractText: extractor, extractionDeadline: deadline)
        }
        func stored(_ id: String) async throws -> FeedArticle? {
            try await database.fetchArticles(limit: 1, id: id).first
        }

        // Extracted text replaces the summary before the inputs are fixed, and invalidates an older overview.
        _ = try await database.upsertArticles([a, b])
        let plain = OverviewGenerationCoordinator(store: store, queue: EnrichmentQueue(store: store))
        let before = await plain.requestOverview(
            eventID: "evidence", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [a, b])
        assertTrue(before != nil, "Without an extractor the summary overview is stored")
        await pages.set(a.link, success(page("Publisher A")))
        await pages.set(b.link, success(page("Publisher B")))
        let extracting = coordinator()
        let after = await extracting.requestOverview(
            eventID: "evidence", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [a, b])
        assertEqual(try await stored(a.id)?.fullContent, page("Publisher A"), "Accepted publisher text is stored")
        assertTrue(after?.inputTextHash != before?.inputTextHash, "Extracted text gives the overview new inputs")
        assertEqual(
            try await database.fetchEventOverview(eventID: "evidence")?.id, after?.id,
            "The summary overview is replaced, not kept as current")
        let again = await extracting.requestOverview(
            eventID: "evidence", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [a, b])
        assertEqual(again?.id, after?.id, "Copies from before extraction still hit the stored overview")
        assertEqual(await log.count(a.link), 1, "Stored text is never fetched again")

        // The reader's own article is left to the reader.
        let (c, d) = (article("ev-c", "Publisher C"), article("ev-d", "Publisher D"))
        _ = try await database.upsertArticles([c, d])
        await pages.set(c.link, success(page("Publisher C")))
        await pages.set(d.link, success(page("Publisher D")))
        _ = await coordinator().requestOverview(
            eventID: "reader", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [c, d],
            excludingFromExtraction: [c.id])
        assertEqual(await log.count(c.link), 0, "The reader's article is not fetched twice")
        assertEqual(await log.count(d.link), 1, "Other representatives are fetched")

        // A slow publisher is cut off at the deadline, keeps its summary and is not retried for the same input.
        let (e, f) = (article("ev-e", "Publisher E"), article("ev-f", "Publisher F"))
        _ = try await database.upsertArticles([e, f])
        await pages.set(e.link, success(page("Publisher E")), delay: .seconds(30))
        await pages.set(f.link, success(page("Publisher F")))
        let slow = coordinator(deadline: .milliseconds(300))
        let clock = ContinuousClock()
        let started = clock.now
        let slowResult = await slow.requestOverview(
            eventID: "slow", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [e, f])
        assertTrue(clock.now - started < .seconds(3), "The deadline bounds the wait for a slow page")
        assertTrue(slowResult != nil, "The overview is still produced")
        assertEqual(try await stored(e.id)?.fullContent, nil, "A page cut off by the deadline is not stored")
        assertEqual(try await stored(f.id)?.fullContent, page("Publisher F"), "The fast page is stored")
        _ = await slow.requestOverview(
            eventID: "slow", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [e, f])
        assertEqual(await log.count(e.link), 1, "A failed fetch is not retried for the same publisher input")

        // At most two fetches run at once, and overlapping requests share them.
        let group = ["ev-g", "ev-h", "ev-i", "ev-j"].enumerated().map { article($1, "Publisher \($0 + 7)") }
        _ = try await database.upsertArticles(group)
        for item in group {
            await pages.set(item.link, success(page(item.source)), delay: .milliseconds(150))
        }
        let shared = coordinator()
        async let first = shared.requestOverview(
            eventID: "shared", eventTitle: "Harbor bridge", membershipVersion: 1, articles: group)
        async let second = shared.requestOverview(
            eventID: "shared", eventTitle: "Harbor bridge", membershipVersion: 1, articles: group,
            priority: .background)
        _ = await (first, second)
        assertTrue(await log.peak <= OverviewGenerationCoordinator.maxConcurrentExtractions, "Two fetches at most")
        for item in group {
            assertEqual(await log.count(item.link), 1, "Overlapping requests fetch each page once")
        }

        // A publisher edit during the fetch wins; quality-rejected and too-short text is not stored.
        let (k, l, m) = (article("ev-k", "Publisher K"), article("ev-l", "Publisher L"), article("ev-m", "Publisher M"))
        _ = try await database.upsertArticles([k, l, m])
        let edited = FeedArticle(
            storedID: k.id, title: "Harbor bridge reopens to buses", link: k.link, guid: k.guid,
            description: k.description, pubDate: k.pubDate, source: k.source)
        await pages.set(
            k.link, success(page("Publisher K")), during: { _ = try? await database.upsertArticles([edited]) })
        await pages.set(l.link, .qualityValidationFailed(reason: "navigation page"))
        await pages.set(m.link, success("Short."))
        _ = await coordinator().requestOverview(
            eventID: "checks", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [k, l, m])
        assertEqual(try await stored(k.id)?.fullContent, nil, "Text fetched for an older publisher version is dropped")
        assertEqual(try await stored(l.id)?.fullContent, nil, "Quality-rejected text is not stored")
        assertEqual(try await stored(m.id)?.fullContent, nil, "Text shorter than the summary is not stored")

        // A cancelled request stops waiting; its fetches end by the deadline and release their slots.
        let (n, o, q) = (article("ev-n", "Publisher N"), article("ev-o", "Publisher O"), article("ev-q", "Publisher Q"))
        _ = try await database.upsertArticles([n, o, q])
        for item in [n, o] {
            await pages.set(item.link, success(page(item.source)), delay: .seconds(30))
        }
        await pages.set(q.link, success(page("Publisher Q")))
        let cancelling = coordinator(deadline: .milliseconds(500))
        let cancelled = Task {
            await cancelling.requestOverview(
                eventID: "cancelled", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [n, o])
        }
        while await log.count(o.link) == 0 { await Task.yield() }
        let cancelledAt = clock.now
        cancelled.cancel()
        assertEqual(await cancelled.value, nil, "A cancelled request returns nothing")
        assertTrue(clock.now - cancelledAt < .milliseconds(400), "A cancelled request stops waiting at once")
        try await Task.sleep(for: .milliseconds(700))
        _ = await cancelling.requestOverview(
            eventID: "after-cancel", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [q, a])
        assertEqual(
            try await stored(q.id)?.fullContent, page("Publisher Q"), "Slots are released after cancelled fetches")

        // An extractor that ignores cancellation cannot hold the overview past the deadline or store late text.
        let (r, t) = (article("ev-r", "Publisher R"), article("ev-t", "Publisher T"))
        _ = try await database.upsertArticles([r, t])
        let stuck = OpenGate()
        await pages.set(r.link, success(page("Publisher R")), gate: stuck)
        await pages.set(t.link, success(page("Publisher T")))
        let stubborn = coordinator(deadline: .milliseconds(300))
        let stubbornStart = clock.now
        let stubbornResult = await stubborn.requestOverview(
            eventID: "stubborn", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [r, t])
        assertTrue(clock.now - stubbornStart < .seconds(3), "A fetch that ignores cancellation is not awaited")
        assertTrue(stubbornResult != nil, "The overview is produced without the stuck page")
        await stuck.open()
        while !(await log.isIdle) { await Task.yield() }
        try await Task.sleep(for: .milliseconds(100))
        assertEqual(try await stored(r.id)?.fullContent, nil, "Text that arrives after the deadline is not stored")

        // Nothing is fetched while the model may not run, and at most four representatives are fetched per event.
        let (u, v) = (article("ev-u", "Publisher U"), article("ev-v", "Publisher V"))
        _ = try await database.upsertArticles([u, v])
        await pages.set(u.link, success(page("Publisher U")))
        let gated = OverviewGenerationCoordinator(
            store: store, queue: EnrichmentQueue(store: store), allowsEnergy: { false },
            extractText: extractor)
        _ = await gated.requestOverview(
            eventID: "gated", eventTitle: "Harbor bridge", membershipVersion: 1, articles: [u, v])
        assertEqual(await log.count(u.link), 0, "Low Power and thermal policy gate page fetches independently of AI")
        let five = ["ev-w1", "ev-w2", "ev-w3", "ev-w4", "ev-w5"].enumerated().map {
            article($1, "Publisher W\($0)")
        }
        _ = try await database.upsertArticles(five)
        for item in five { await pages.set(item.link, success(page(item.source))) }
        _ = await coordinator().requestOverview(
            eventID: "five", eventTitle: "Harbor bridge", membershipVersion: 1, articles: five)
        var fetched = 0
        for item in five { fetched += await log.count(item.link) }
        assertEqual(fetched, OverviewGenerationCoordinator.maxEvidenceFetches, "Four representatives at most")
    }

    /// Every framework error type reaches one of the three outcomes (#508); the macOS 27 types exist only in that SDK.
    static func testModelErrorMapping() {
        print("  - Testing on-device model error mapping (#508)...")
        #if canImport(FoundationModels) && compiler(>=6.4)
            if #available(macOS 27.0, *) {
                let overflow = NewsTextModel.failure(
                    any: LanguageModelError.contextSizeExceeded(
                        .init(contextSize: 4_096, tokenCount: 9_000, debugDescription: "")))
                assertEqual(
                    overflow as? NewsTextModel.Rejected, NewsTextModel.Rejected(reason: .contextWindow),
                    "A macOS 27 context overflow is final")
                let refusal = NewsTextModel.failure(
                    any: LanguageModelError.refusal(.init(explanation: "", debugDescription: "")))
                assertEqual(
                    refusal as? NewsTextModel.Rejected, NewsTextModel.Rejected(reason: .refusal),
                    "A macOS 27 refusal is final")
                assertTrue(
                    NewsTextModel.failure(any: LanguageModelError.timeout(.init(debugDescription: "")))
                        is NewsTextModel.TemporarilyUnavailable, "A timeout retries later")
                assertTrue(
                    NewsTextModel.failure(any: SystemLanguageModel.Error.assetsUnavailable(.init(debugDescription: "")))
                        is NewsTextModel.TemporarilyUnavailable, "Missing model assets retry later")
            }
        #endif
        assertTrue(NewsTextModel.failure(any: CancellationError()) is CancellationError, "Cancellation passes through")
        assertTrue(
            NewsTextModel.failure(any: URLError(.badServerResponse)) is URLError, "Unknown errors stay provisional")
    }

    @MainActor
    static func testPlainTextGeneration(fixtureHost: String) async throws {
        print("  - Testing Plain Text Generation, Support Gates and Refusal Fallbacks...")
        testModelErrorMapping()
        let classified = await ArticleClassifier().classify(
            title: "Airstrikes hit the port", description: "Reported developments")
        assertEqual(classified.category, "World", "Ingestion classification is deterministic; no model stage remains")
        let text =
            "The bridge reopened after engineers completed repairs. Traffic resumed | during the morning. The council approved the repairs."
        let analysisModel = NewsTextModel { _, _ in
            "SUMMARY|The bridge reopened after repairs.\nPOINT|Traffic resumed.\nPOINT|Engineers completed repairs.\nPOINT|The council approved repairs."
        }
        let analysis = try await ArticleAnalyzer(textModel: analysisModel).analyze(
            title: "Bridge reopened", content: text)
        assertEqual(analysis.modelIdentifier, "apple.foundation-model", "Analysis uses plain text")
        let shortAnalysis = try await ArticleAnalyzer(
            textModel: NewsTextModel { _, _ in
                "SUMMARY|The bridge reopened.\nPOINT|Repairs were completed.\nPOINT|Traffic resumed."
            }
        ).analyze(title: "Bridge reopened", content: text)
        assertEqual(
            shortAnalysis.modelIdentifier, "apple.foundation-model",
            "Two supported points do not force a short article to invent a third")
        let fallbackAnalysis = try await ArticleAnalyzer(textModel: .unavailable).analyze(
            title: "Bridge reopened", content: text)
        assertEqual(
            fallbackAnalysis.modelIdentifier, "apple.natural-language.fallback",
            "A refusal keeps source-based extraction")
        assertEqual(fallbackAnalysis.analysisVersion, 3, "A Mac without the model keeps its extractive summary")
        // Non-English text never reaches the model and keeps a final extractive summary (#550).
        let german =
            "Die Brücke wurde nach Abschluss der Reparaturen wieder geöffnet. Der Verkehr rollte am Morgen wieder an. "
            + "Der Stadtrat hatte die Reparaturen im Frühjahr genehmigt, nachdem Ingenieure Risse im Beton gefunden hatten."
        let germanAnalysis = try await ArticleAnalyzer(
            textModel: NewsTextModel { _, _ in
                assertTrue(false, "Non-English text is not sent to the on-device model")
                throw NewsTextModel.TemporarilyUnavailable()
            }
        ).analyze(title: "Brücke wieder geöffnet", content: german)
        assertEqual(
            germanAnalysis.modelIdentifier, "apple.natural-language.fallback", "German text gets the extractive summary"
        )
        assertEqual(germanAnalysis.analysisVersion, 3, "… as a final summary, not a provisional one")
        assertFalse(germanAnalysis.summary.isEmpty, "The extractive summary covers the German text")
        let waitingAnalysis = try await ArticleAnalyzer(
            textModel: NewsTextModel { _, _ in throw NewsTextModel.TemporarilyUnavailable() }
        )
        .analyze(title: "Bridge reopened", content: text)
        assertEqual(
            waitingAnalysis.analysisVersion, 0,
            "A summary made while the model is off or downloading is redone once it can run")
        let failedAnalysis = try await ArticleAnalyzer(textModel: NewsTextModel { _, _ in throw URLError(.timedOut) })
            .analyze(title: "Bridge reopened", content: text)
        assertEqual(failedAnalysis.analysisVersion, 0, "A summary after a failed model request is redone")
        let skippedAnalysis = try await ArticleAnalyzer(textModel: analysisModel).analyze(
            title: "Bridge reopened", content: text, allowFoundationModels: false)
        assertEqual(skippedAnalysis.analysisVersion, 3, "An explicitly extractive request is final")
        let malformedAnalysis = try await ArticleAnalyzer(textModel: NewsTextModel { _, _ in "I refuse" }).analyze(
            title: "Bridge reopened", content: text)
        assertEqual(
            malformedAnalysis.analysisVersion, 3,
            "A malformed answer that greedy sampling would repeat keeps the extractive summary")
        let refusedAnalysis = try await ArticleAnalyzer(
            textModel: NewsTextModel { _, _ in throw NewsTextModel.Rejected(reason: .guardrail) }
        ).analyze(title: "Bridge reopened", content: text)
        assertEqual(
            refusedAnalysis.analysisVersion, 3,
            "A guardrail refusal of this exact text is final: the extractive summary is not redone on every open")
        assertEqual(
            refusedAnalysis.modelIdentifier, "apple.natural-language.fallback",
            "A refused request keeps source-based extraction")
        assertEqual(
            ArticleTextAnswer.analysis("SUMMARY|x\nSUMMARY|y\nPOINT|a\nPOINT|b\nPOINT|c")?.summary, nil,
            "Duplicate summary is rejected")
        let article1 = FeedArticle(
            storedID: "plain-a", title: "Bridge repairs", link: "https://\(fixtureHost)/a", guid: "plain-a",
            description: text, pubDate: Date(), source: "Publisher A")
        let other =
            "Engineers inspected the bridge before traffic resumed. The council funded the repairs. Residents welcomed the reopening. Buses returned to the bridge route on Monday morning. Shop owners near the bridge reported more customers this week. The transport office will publish a full inspection report next month."
        let article2 = FeedArticle(
            storedID: "plain-b", title: "Bridge reopening", link: "https://\(fixtureHost)/b", guid: "plain-b",
            description: other, pubDate: Date(), source: "Publisher B")
        let passages = [
            EvidencePassage(id: "p1", articleID: article1.id, text: text),
            EvidencePassage(id: "p2", articleID: article2.id, text: other),
        ]
        let fallback = OverviewComposer.composeOverview(
            eventID: "plain", eventTitle: "Bridge reopening",
            verifiedFacts: PassageFactExtractor.deterministicExtract(passages: passages), passages: passages,
            articles: [article1, article2])
        let answer = """
            INTRO|P1|The bridge reopened after engineers completed repairs.
            INTRO|P2|Engineers inspected the bridge before traffic resumed&#046;
            FACT|P1|Traffic resumed | during the morning.
            FACT|P1|The council approved the repairs.
            FACT|P2|The council funded the repairs.
            FACT|P2|Engineers destroyed the bridge.
            """
        let overviewModel = NewsTextModel { prompt, _ in
            if prompt.contains("Return plain text only:") { return answer }
            return prompt.contains("Engineers destroyed the bridge.") ? "NO" : "yes."
        }
        let generated = try await OverviewComposer.composeWithModel(
            fallback: fallback, passages: passages, articles: [article1, article2], model: overviewModel)
        assertEqual(generated.facts.count, 3, "Semantic rejection drops a related but unsupported claim")
        assertFalse(generated.id == fallback.id, "Lowercase punctuated support answers permit a new synthesis")
        assertTrue(
            generated.facts.contains { $0.text.contains("|") },
            "Pipes inside a supported sentence survive protocol parsing")
        for verdict in [" Yes! \n", "YES", "YES NO", "YES, but unsupported", "YES\nNO", "NO"] {
            let variant = NewsTextModel { prompt, _ in
                if prompt.contains("Return plain text only:") { return answer }
                return prompt.contains("Engineers destroyed the bridge.") ? "NO" : verdict
            }
            let document = try await OverviewComposer.composeWithModel(
                fallback: fallback, passages: passages, articles: [article1, article2], model: variant)
            assertEqual(
                document.id != fallback.id, verdict == " Yes! \n" || verdict == "YES",
                "Support parsing accepts only the complete YES word, ignoring case and surrounding punctuation")
        }
        let oldVersion = EventOverviewDocument(
            eventID: fallback.eventID,
            version: OverviewVersionContext(
                membershipVersion: fallback.version.membershipVersion,
                inputTextHash: fallback.version.inputTextHash, analysisVersion: 3),
            content: fallback.content, provenance: fallback.provenance)
        assertTrue(
            oldVersion.isStale(currentMembershipVersion: fallback.version.membershipVersion),
            "Overviews cached before the parser fix regenerate")
        assertEqual(
            generated.content.evidenceSections?.introduction?.count, 2, "Introduction sentences carry citations")
        assertEqual(generated.allClaims.count, 5, "Introduction is included in verification")
        assertFalse(generated.summary.contains("&#"), "Synthesized prose decodes HTML entities from older feed text")
        let audited = OverviewQualityAuditor.auditOverview(generated, passages: passages)
        assertEqual(audited.totalClaims, 5, "Audit denominator includes the introduction")
        assertEqual(audited.supportedClaims, 5, "Audit numerator and denominator have the same grain")
        assertTrue(
            OverviewClaimVerifier.verifyOverview(generated, passages: passages, articles: [article1, article2])
                .isFullyVerified, "Retained claims preserve passage lineage")
        let refused = try await OverviewComposer.composeWithModel(
            fallback: fallback, passages: passages, articles: [article1, article2],
            model: NewsTextModel { _, _ in "I refuse" })
        assertEqual(refused.id, fallback.id, "Malformed draft retains the current overview")
        let rejected = try await OverviewComposer.composeWithModel(
            fallback: fallback, passages: passages, articles: [article1, article2],
            model: NewsTextModel { prompt, _ in prompt.contains("Return plain text only:") ? answer : "NO" })
        assertEqual(rejected.id, fallback.id, "Too many rejected sentences retain the current overview")
        // #308: the outcome names why a draft was kept or replaced, without changing the document.
        func outcome(_ model: NewsTextModel, passages: [EvidencePassage]) async throws -> OverviewModelOutcome {
            try await OverviewComposer.composeWithModelOutcome(
                fallback: fallback, passages: passages, articles: [article1, article2], model: model
            ).outcome
        }
        let kept = try await outcome(overviewModel, passages: passages)
        assertEqual(kept.result, .accepted, "Outcome reports a kept draft")
        assertEqual(
            [kept.lines, kept.keptIntroduction, kept.keptFacts, kept.malformedLines], [6, 2, 3, 0],
            "Outcome counts lines and kept sentences")
        assertEqual(kept.deterministicRejections + kept.modelRejections, 1, "The unsupported sentence is counted once")
        let prose = try await outcome(NewsTextModel { _, _ in "I refuse" }, passages: passages)
        assertEqual(prose.result, .unstructured, "Prose without protocol lines is a refusal-like fallback")
        let short = answer.split(separator: "\n").prefix(3).joined(separator: "\n")
        let truncated = try await outcome(NewsTextModel { _, _ in short }, passages: passages)
        assertEqual(truncated.result, .lineCount, "Too few protocol lines is a format fallback")
        // A pasted paragraph keeps its first sentence only when that sentence stands alone (#308).
        assertEqual(
            OverviewComposer.firstCompleteSentence(
                "The council approved the bridge repairs on Monday. Officials gave no reopening date."),
            "The council approved the bridge repairs on Monday.", "A pasted paragraph keeps its first sentence")
        assertEqual(
            OverviewComposer.firstCompleteSentence("Traffic resumed. Officials gave no reopening date for the bridge."),
            nil, "A fragment is not kept as a claim")
        assertEqual(
            OverviewComposer.firstCompleteSentence(
                "The mayor said: \u{201C}We will go on with the work. Nobody will stop the repairs.\u{201D}"),
            nil, "A sentence that breaks a quotation is not kept")
        assertEqual(
            OverviewComposer.firstCompleteSentence("The bridge reopened after repairs."),
            "The bridge reopened after repairs.", "A single sentence is unchanged")
        let pasted = answer.replacingOccurrences(
            of: "FACT|P2|The council funded the repairs.",
            with: "FACT|P2|Engineers inspected the bridge before traffic resumed. The council funded the repairs.")
        let pastedOutcome = try await outcome(
            NewsTextModel { prompt, _ in
                if prompt.contains("Return plain text only:") { return pasted }
                return prompt.contains("Engineers destroyed the bridge.") ? "NO" : "YES"
            }, passages: passages)
        assertEqual(
            [pastedOutcome.keptFacts, pastedOutcome.rejectionReasons["notOneSentence"] ?? 0], [3, 0],
            "The first sentence of a pasted paragraph is verified and kept")
        let fourLines = answer.split(separator: "\n")
            .filter { !$0.contains("INTRO|P2") && !$0.contains("destroyed") }.joined(separator: "\n")
        let fourLineOutcome = try await outcome(
            NewsTextModel { prompt, _ in prompt.contains("Return plain text only:") ? fourLines : "YES" },
            passages: passages)
        assertEqual(fourLineOutcome.result, .accepted, "One introduction and three facts in four lines are accepted")
        let weakDraft = try await outcome(
            NewsTextModel { prompt, _ in prompt.contains("Return plain text only:") ? answer : "NO" },
            passages: passages)
        assertEqual(weakDraft.result, .weakDraft, "Rejected sentences make a weak draft")
        assertEqual(weakDraft.keptIntroduction + weakDraft.keptFacts, 0, "A weak draft keeps no sentence")
        let misnumbered = answer.replacingOccurrences(
            of: "FACT|P2|Engineers destroyed", with: "FACT|P9|Engineers destroyed")
        let malformed = try await outcome(
            NewsTextModel { prompt, _ in prompt.contains("Return plain text only:") ? misnumbered : "YES" },
            passages: passages)
        assertEqual(
            [malformed.malformedLines, malformed.modelRejections], [1, 0],
            "An unknown passage ID is malformed, not judged")
        assertEqual(malformed.result, .accepted, "Five of six valid lines still form a draft")
        let unasked = try await outcome(overviewModel, passages: [])
        assertEqual(unasked.result, .noPassages, "No passages skips the model")
        let staleCitation = OverviewCitation(
            id: "stale", articleID: article1.id, passageID: "p1", passageFingerprint: "old", quote: text)
        let stale = EventOverviewDocument(
            eventID: "plain", version: fallback.version,
            content: OverviewContent(
                title: "Bridge", summary: "", facts: [OverviewFact(id: "stale", text: text, citationIDs: ["stale"])],
                citations: [staleCitation]))
        assertFalse(
            OverviewClaimVerifier.verifyOverview(stale, passages: passages, articles: [article1, article2])
                .isFullyVerified,
            "Citation fingerprint must match the current publisher passage")
        let database = DatabaseEngine(path: ":memory:")
        try await database.open()
        _ = try await database.upsertArticles([article1, article2])
        let store = ArticleStore(database: database)
        let coordinator = OverviewGenerationCoordinator(
            store: store, queue: EnrichmentQueue(store: store))
        let coordinated = await coordinator.requestOverview(
            eventID: "plain", eventTitle: "Bridge reopening", membershipVersion: 1, articles: [article1, article2])
        assertEqual(coordinated?.summary, "", "Production requests omit generated prose")
        assertEqual(coordinated?.kind, .fallbackExcerpts, "Production requests use publisher excerpts")
        let persisted = try await database.fetchEventOverview(eventID: "plain")
        assertEqual(persisted?.id, coordinated?.id, "SQLite stores the generated excerpt document")
        assertEqual(persisted?.summary, "", "SQLite preserves the empty summary")
        assertTrue(!(persisted?.facts.isEmpty ?? true), "SQLite retains publisher facts and citations")
        let blocked = OverviewGenerationCoordinator(
            store: store, queue: EnrichmentQueue(store: store))
        let aiOff = await blocked.requestOverview(
            eventID: "blocked", eventTitle: "Bridge", membershipVersion: 1, articles: [article1, article2])
        assertEqual(
            try await database.fetchEventOverview(eventID: "blocked")?.isStale(currentMembershipVersion: 1), false,
            "Publisher excerpts are final")
        let reused = await coordinator.requestOverview(
            eventID: "blocked", eventTitle: "Bridge", membershipVersion: 1, articles: [article1, article2])
        assertEqual(reused?.id, aiOff?.id, "Another coordinator reuses the same final excerpts")

        let legacy = EventOverviewDocument(
            eventID: "legacy",
            version: OverviewVersionContext(
                membershipVersion: 1, inputTextHash: coordinated!.inputTextHash, analysisVersion: 7),
            content: OverviewContent(title: "Old generated headline", summary: "Old model prose."),
            provenance: OverviewProvenance(memberArticleIDs: [article1.id, article2.id], kind: .synthesized))
        assertTrue(try await database.recordEventOverview(legacy), "Seed a legacy generated overview")
        let replacement = await blocked.requestOverview(
            eventID: "legacy", eventTitle: "Bridge", membershipVersion: 1, articles: [article1, article2])
        assertEqual(replacement?.summary, "", "A cached generated summary regenerates as excerpts")
        assertEqual(replacement?.analysisVersion, EventOverviewDocument.currentAnalysisVersion, "Regeneration uses v8")
        assertTrue(replacement?.id != legacy.id, "The legacy cached document is replaced")

        // Hold the real queue, rather than a retired model call, to verify shared-generation cancellation.
        let gate = OpenGate()
        let queue = EnrichmentQueue(store: store)
        let holders = (0..<3).map { index in
            Task {
                await queue.scheduleOverviewGeneration(eventID: "excerpt-hold-\(index)") {
                    await gate.wait()
                    return nil
                }
            }
        }
        await eventually("Held jobs fill the excerpt queue") { await queue.activeJobCount() == 3 }
        let checks = TestCounter()
        let shared = OverviewGenerationCoordinator(
            store: store, queue: queue,
            allowsEnergy: {
                await checks.increment()
                return true
            })
        let warmup = Task {
            await shared.requestOverview(
                eventID: "joined", eventTitle: "Bridge", membershipVersion: 1,
                articles: [article1, article2], priority: .background)
        }
        await eventually("Background excerpts wait in the queue") {
            await shared.inFlightInputHash(for: "joined") != nil
        }
        let reader = Task {
            await shared.requestOverview(
                eventID: "joined", eventTitle: "Bridge", membershipVersion: 1, articles: [article1, article2])
        }
        await eventually("The reader joins the same request") { await checks.value >= 2 }
        warmup.cancel()
        await gate.open()
        assertEqual(await warmup.value, nil, "The cancelled background request returns nothing")
        let joined = await reader.value
        assertTrue(joined != nil, "Cancelling warmup preserves the reader's shared generation")
        assertEqual(joined?.summary, "", "The joined generation returns excerpts")
        for holder in holders { _ = await holder.value }
        // A macOS update can replace the on-device model: stored overviews and summaries regenerate with the new one.
        let summary = ArticleAnalysis(
            summary: "The bridge reopened.", keyPoints: ["Traffic resumed."], entities: [], category: "World",
            sentiment: nil, modelIdentifier: "apple.foundation-model", analysisVersion: 3)
        assertTrue(await store.saveArticleAnalysis(summary, for: article1.id), "A model summary is stored")
        assertTrue(
            try await database.reconcileModelGeneration("model-a"),
            "An unrecorded model generation invalidates stored results")
        assertEqual(
            try await database.fetchEventOverview(eventID: "plain")?.analysisVersion,
            EventOverviewDocument.currentAnalysisVersion,
            "Publisher excerpts remain final when the model changes")
        assertTrue(
            (await database.fetchArticleAnalysis(for: article1.id)?.analysisVersion ?? 3) < 3,
            "Summaries from an earlier model are redone")
        let current = await coordinator.requestOverview(
            eventID: "plain", eventTitle: "Bridge reopening", membershipVersion: 1, articles: [article1, article2])
        assertEqual(
            current?.analysisVersion, EventOverviewDocument.currentAnalysisVersion,
            "The next request regenerates with the current model")
        assertFalse(
            try await database.reconcileModelGeneration("model-a"), "The same model generation keeps stored results")
        assertEqual(
            try await database.fetchEventOverview(eventID: "plain")?.analysisVersion,
            EventOverviewDocument.currentAnalysisVersion,
            "Results stay current until the model changes")
        assertTrue(
            try await database.reconcileModelGeneration("model-b"), "A new model generation invalidates them again")
        await database.close()
        let roundTrip = try JSONDecoder().decode(EventOverviewDocument.self, from: JSONEncoder().encode(generated))
        assertEqual(roundTrip.allClaims, generated.allClaims, "Introduction citations survive persistence")
        let cancelled = Task {
            try await OverviewComposer.composeWithModel(
                fallback: fallback, passages: passages, articles: [article1, article2],
                model: NewsTextModel { _, _ in
                    try Task.checkCancellation()
                    return answer
                })
        }
        cancelled.cancel()
        let cancellationThrew: Bool
        do {
            _ = try await cancelled.value
            cancellationThrew = false
        } catch is CancellationError { cancellationThrew = true }
        assertTrue(cancellationThrew, "Cancelled generation throws")
    }

    static func testArticleAnalyzerStructuredOutputAndFallbacks() async throws {
        print("  - Testing ArticleAnalyzer Structured Output (Summary, Key Points, Entities, Sentiment)...")

        // The extractive path, independent of whether this Mac's on-device model is ready.
        let analyzer = ArticleAnalyzer(textModel: .unavailable)
        let title = "Tech Giants Unveil Breakthrough Quantum Computing Core"
        let articleBody = """
            Researchers at leading technology institutes have announced a functional 1,000-qubit quantum processor.
            The breakthrough system operates at room temperature, eliminating the need for bulky liquid helium cryostats.
            Dr. Jane Doe presented the research at the International Physics Symposium in Geneva today.
            Commercial applications in cryptography, drug discovery, and materials science are slated for next year.
            Initial benchmark results show an exponential performance leap compared to traditional classical supercomputers.
            """

        let analysis = try await analyzer.analyze(
            title: title, content: articleBody, category: "Technology", allowFoundationModels: false)

        // 1. Summary validation
        assertTrue(!analysis.summary.isEmpty, "Analysis summary should not be empty")
        assertTrue(analysis.summary.count >= 20, "Summary should be a coherent passage")

        // 2. Key Points validation (between 2 and 5 items)
        assertTrue(!analysis.keyPoints.isEmpty, "Key points should not be empty")
        assertTrue(
            analysis.keyPoints.count >= 2 && analysis.keyPoints.count <= 5,
            "Key points count should be bounded (2-5 points)")

        // 3. Entities validation
        assertTrue(!analysis.entities.isEmpty, "Entities should be extracted")

        // 4. Sentiment validation
        assertTrue(analysis.sentiment != nil, "Sentiment should be evaluated")

        // 5. Model identifier and versioning
        assertTrue(!analysis.modelIdentifier.isEmpty, "Model identifier should identify engine")
        assertEqual(
            analysis.analysisVersion, 3, "Analysis version invalidates summaries from the old extraction pipeline")

        // 6. Headline words next to punctuation still count for sentence selection (#514).
        let punctuated = await ExtractiveArticleSummarizer().summarize(
            title: "Westfield: gunman's 'identity' revealed",
            content: """
                The city council met on Tuesday to discuss parking fees. \
                Residents asked for lower rates near the harbour. \
                Councillors agreed to review the schedule next month. \
                Separately, police named the Westfield gunman as a local man. \
                The gunman had been known to officers for years.
                """)
        assertTrue(
            punctuated.text.contains("Westfield gunman"),
            "The sentence repeating the headline's punctuated nouns is selected over earlier unrelated ones")
    }

    static func testInteractiveAnalysisCancellation() async {
        print("  - Testing Interactive Analysis Cooperative Cancellation...")

        let analyzer = ArticleAnalyzer.shared
        let largeContent = String(
            repeating:
                "The rapid development of autonomous distributed systems continues to evolve across multiple technological sectors. ",
            count: 100)

        let task = Task {
            try await analyzer.analyze(title: "Massive Article", content: largeContent)
        }

        // Cancel task immediately
        task.cancel()

        var caughtCancellation = false
        do {
            _ = try await task.value
        } catch is CancellationError {
            caughtCancellation = true
        } catch let err as AIAnalysisError where err == .cancelled {
            caughtCancellation = true
        } catch {
            caughtCancellation = true
        }
        assertTrue(
            caughtCancellation, "Cancelled analysis task must throw CancellationError or AIAnalysisError.cancelled")
    }

    static func testGranularCacheClearingAndRetention() async throws {
        print("  - Testing Granular Cache Purging (Selective Deletes & Feed Preservation)...")

        let db = DatabaseEngine(path: ":memory:")
        try await db.open()
        defer { Task { await db.close() } }

        // 1. Populate feeds and articles
        let testFeed = "https://example.com/tech.xml"
        let article1 = FeedArticle(
            title: "Article One", link: "https://example.com/1", guid: "art-1", description: "Desc 1", pubDate: Date(),
            source: "Test Feed", fullContent: "Content One")
        let article2 = FeedArticle(
            title: "Article Two", link: "https://example.com/2", guid: "art-2", description: "Desc 2", pubDate: Date(),
            source: "Test Feed", fullContent: "Content Two")

        try await db.upsertArticles([article1, article2], feedUrl: testFeed)
        _ = try await db.toggleSaved(articleId: article1.id)  // article1 is saved!

        // Save AI enrichment for both
        let analysis = ArticleAnalysis(
            summary: "Summary text", keyPoints: ["Point 1", "Point 2"], entities: [], category: "Technology",
            sentiment: nil, modelIdentifier: "test", analysisVersion: 1)
        try await db.saveArticleAnalysis(analysis, for: article1.id)
        try await db.saveArticleAnalysis(analysis, for: article2.id)

        // Verify initial state
        let initialAnalysis1 = await db.fetchArticleAnalysis(for: article1.id)
        assertTrue(initialAnalysis1 != nil, "Article 1 should have analysis")
        let initialAnalysis2 = await db.fetchArticleAnalysis(for: article2.id)
        assertTrue(initialAnalysis2 != nil, "Article 2 should have analysis")

        try await db.upsertArticleEmbeddings([article2.id: [0.5, 0.25]], modelVersion: 1)
        let event = try await db.createEvent(memberArticleIDs: [article2.id])
        _ = try await db.recordEventOverview(
            EventOverviewDocument(
                eventID: event.id,
                version: OverviewVersionContext(membershipVersion: event.membershipVersion, inputTextHash: "hash"),
                content: OverviewContent(
                    title: "Event", summary: "Summary",
                    citations: [
                        OverviewCitation(
                            id: "citation", articleID: article2.id, passageID: "p", passageFingerprint: "f",
                            quote: "Quote")
                    ])))

        // 2. Test clearArticleEnrichment(): clears AI analysis, overviews and embeddings, keeps articles and events
        try await db.clearArticleEnrichment()
        let clearedAnalysis1 = await db.fetchArticleAnalysis(for: article1.id)
        assertTrue(clearedAnalysis1 == nil, "Article 1 enrichment must be purged")
        let clearedAnalysis2 = await db.fetchArticleAnalysis(for: article2.id)
        assertTrue(clearedAnalysis2 == nil, "Article 2 enrichment must be purged")
        assertTrue(
            try await db.fetchArticleEmbeddings(articleIDs: [article2.id], modelVersion: 1).isEmpty,
            "Clearing AI analysis removes story embeddings")
        assertTrue(try await db.fetchEventOverview(eventID: event.id) == nil, "Clearing AI analysis removes overviews")
        assertTrue(try await db.fetchEvent(id: event.id) != nil, "Events themselves are kept")

        let articlesAfterEnrichmentClear = try await db.fetchArticles(limit: 10)
        assertEqual(articlesAfterEnrichmentClear.count, 2, "Articles must remain intact after enrichment purge")

        // 3. Test clearArticleCache(): clears non-saved article bodies, keeps saved stories intact
        try await db.clearArticleCache()
        let articlesAfterContentClear = try await db.fetchArticles(limit: 10)
        let savedArticle = articlesAfterContentClear.first { $0.id == article1.id }
        assertEqual(savedArticle?.fullContent, "Content One", "Saved article content must NOT be cleared")
        let unsavedArticle = articlesAfterContentClear.first { $0.id == article2.id }
        assertTrue(unsavedArticle?.fullContent == nil, "Non-saved article content must be set to nil")

        // Cache cleanup must not delete user history.
        try await db.markRead(articleId: article2.id, isRead: true)
        try await db.clearAllDatabaseCache()
        let remainingArticles = try await db.fetchArticles(limit: 10)
        assertEqual(remainingArticles.count, 2, "Cache cleanup must preserve article headers and history")
        assertEqual(
            remainingArticles.first(where: { $0.id == article1.id })?.fullContent, "Content One",
            "Saved body survives cache cleanup")
        assertTrue(try await db.getReadArticleIDs().contains(article2.id), "Read history survives cache cleanup")

        // Clear All Caches removes everything Clear Analysis removes (#811)
        try await db.upsertArticleEmbeddings([article2.id: [0.5, 0.25]], modelVersion: 1)
        try await db.upsertArticleFeatures(
            [article2.id: EventFeatures(title: article2.title, description: "", date: Date(timeIntervalSince1970: 0))],
            version: EventFeatures.storageVersion)
        try await db.upsertPairDecisions(
            [
                DatabaseEngine.PairDecision(
                    articleID: article1.id, otherArticleID: article2.id, decision: "related-act",
                    reason: "differentAct", score: 0.4, features: #"{"cosine":0.7}"#)
            ], matcherVersion: EventMatcher.version)
        _ = try await db.recordEventOverview(
            EventOverviewDocument(
                eventID: event.id,
                version: OverviewVersionContext(membershipVersion: event.membershipVersion, inputTextHash: "hash"),
                content: OverviewContent(
                    title: "Event", summary: "Summary",
                    citations: [
                        OverviewCitation(
                            id: "citation", articleID: article2.id, passageID: "p", passageFingerprint: "f",
                            quote: "Quote")
                    ])))
        try await db.clearAllDatabaseCache()
        assertTrue(
            try await db.fetchArticleEmbeddings(articleIDs: [article2.id], modelVersion: 1).isEmpty,
            "Clear All Caches removes story embeddings (#811)")
        assertTrue(
            try await db.fetchArticleFeatures(articleIDs: [article2.id], version: EventFeatures.storageVersion).isEmpty,
            "Clear All Caches removes matcher features (#811)")
        let pairRows = try await db.eventRows("SELECT features FROM pair_assessments;")
        assertEqual(pairRows.count, 1, "Clear All Caches keeps the pair decision (#811)")
        assertTrue(
            (pairRows.first?.first ?? nil) == nil, "Clear All Caches clears the pair decision's features (#811)")
        assertTrue(
            try await db.fetchEventOverview(eventID: event.id) == nil, "Clear All Caches removes overviews (#811)")

        // 5. Test CacheManager methods
        // Do not clear the user's WebKit cache from a unit test.
    }

    static func testNotificationServiceErrorLogging() async {
        print("  - Testing NotificationService Formatting & Robust Dispatching...")

        let service = NotificationService.shared

        // 1. Singular grammar
        let singularSummary = NotificationService.formatMinimalSummary(articleCount: 1, uniqueSourcesCount: 1)
        assertEqual(singularSummary, "1 new article from 1 source", "Singular grammar check")

        // 2. Plural grammar
        let pluralSummary = NotificationService.formatMinimalSummary(articleCount: 5, uniqueSourcesCount: 3)
        assertEqual(pluralSummary, "5 new articles across 3 sources", "Plural grammar check")

        // Edge cases
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 1, uniqueSourcesCount: 0),
            "1 new article across 0 sources", "Edge case: 1 article, 0 sources")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 0, uniqueSourcesCount: 0),
            "0 new articles across 0 sources", "Edge case: 0 articles, 0 sources")
        assertEqual(
            NotificationService.formatMinimalSummary(articleCount: 0, uniqueSourcesCount: 1),
            "0 new articles from 1 source", "Edge case: 0 articles, 1 source")

        // 3. Importance computation range [0.0, 1.0]
        assertEqual(
            NotificationService.breakingSignalWeight(in: "Studies show diesel bodies replacement"), 0,
            "Signal words match whole words only")
        assertEqual(
            NotificationService.breakingSignalWeight(in: "Man dies in attack, police say"), 2,
            "Whole-word breaking signals weigh a point each")
        assertEqual(
            NotificationService.breakingSignalWeight(in: "President announces the company launches a fund"), 1.5,
            "Announcement and office-holder words weigh half (#545)")
        let score = service.computeImportance(
            title: "Breaking News: Major Crisis Declared", description: "Officials announce emergency response.")
        assertTrue(score >= 0.0 && score <= 1.0, "Score must be bounded between 0.0 and 1.0")

        // One banner per event (#523): the strongest report represents its event; singles stand alone.
        func report(_ id: Int, _ title: String) -> FeedArticle {
            FeedArticle(
                title: title, link: "https://notify.invalid/\(id)", guid: "notify-\(id)", description: "",
                pubDate: Date(timeIntervalSince1970: 1_700_000_000), source: "Publisher \(id)")
        }
        let quiet = report(1, "Council meets on Tuesday")
        let loud = report(
            2,
            "Breaking: explosion kills dozens in Paris, London, Berlin, Madrid, Rome, Vienna, Lisbon and Dublin; emergency declared"
        )
        let third = report(3, "Explosion reported downtown")
        let single = report(4, "Local library extends opening hours")
        let events = [quiet.id: "event-a", loud.id: "event-a", third.id: "event-a"]
        let chosen = await NotificationService.representatives(of: [quiet, loud, third, single], events: events)
        assertEqual(
            chosen.map(\.article.id), [loud.id, single.id], "One report per event, the strongest, then the single")
        let alone = await NotificationService.representatives(of: [quiet, single], events: [:])
        assertEqual(alone.map(\.article.id), [quiet.id, single.id], "Without events every story stands alone in order")

        // 4. Robust dispatching (no crashes across all 3 notification tiers)
        let sampleArticle = FeedArticle(
            title: "Urgent Update", link: "https://example.com/urgent", guid: "sample-guid",
            description: "Details follow", pubDate: Date(), source: "Wire Service")
        await service.triageAndNotify(newArticles: [sampleArticle], delivery: .init(mode: .minimal))
        await service.triageAndNotify(newArticles: [sampleArticle], delivery: .init(mode: .privacy))
        await service.triageAndNotify(newArticles: [sampleArticle], delivery: .init(mode: .full))

        // 5. Banners arrive one at a time, a pause apart, threaded per story (#587): two new reports of one event are
        // one banner; three events are three spaced banners with their own threads. A breaking story is an active
        // alert with sound; a lesser one is passive and silent.
        struct Posted: Sendable {
            let at = ContinuousClock.now
            let thread: String
            let active: Bool
            let sound: Bool
            let body: String
            let category: String
            init(_ request: UNNotificationRequest) {
                thread = request.content.threadIdentifier
                active = request.content.interruptionLevel == .active
                sound = request.content.sound != nil
                body = request.content.body
                category = request.content.categoryIdentifier
            }
        }
        actor Recorder {
            var posted: [Posted] = []
            func record(_ item: Posted) { posted.append(item) }
        }
        let recorder = Recorder()
        let spaced = NotificationService(post: { await recorder.record(Posted($0)) }, spacing: .milliseconds(60))
        // Three signal words and six named places put a score at 0.75 before sentiment, so these are breaking
        // whatever the sentiment tagger says.
        let fourth = report(
            5,
            "Earthquake kills hundreds in Tokyo, Osaka, Kyoto, Nagoya, Sapporo, Kobe and Sendai; emergency declared as crisis deepens"
        )
        let fifth = report(
            6,
            "Explosion at a refinery in Houston, Dallas, Austin, Denver, Phoenix, Tucson and Boise, dozens killed; urgent evacuation"
        )
        let pairEvents = [quiet.id: "event-a", loud.id: "event-a", fourth.id: "event-b", fifth.id: "event-c"]
        await spaced.triageAndNotify(
            newArticles: [quiet, loud, fourth, fifth], delivery: .init(mode: .full, events: pairEvents))
        let posted = await recorder.posted
        assertEqual(posted.count, 3, "Two reports of one event and two other events are three banners")
        assertEqual(
            Set(posted.map(\.thread)), ["event-a", "event-b", "event-c"], "Each banner is threaded under its event")
        assertTrue(
            zip(posted, posted.dropFirst()).allSatisfy { $1.at - $0.at >= .milliseconds(60) },
            "Banners of one refresh are posted at least the spacing apart")
        assertTrue(posted.allSatisfy { $0.active && $0.sound }, "Breaking stories are active alerts with sound")
        assertTrue(
            posted.allSatisfy { $0.category == NotificationActionIdentifier.category },
            "A story's banner carries Save, Mark as Read and Open (#560)")
        let quietRecorder = Recorder()
        let quietService = NotificationService(post: { await quietRecorder.record(Posted($0)) }, spacing: .zero)
        await quietService.triageAndNotify(newArticles: [quiet], delivery: .init(mode: .full))
        assertTrue(
            (await quietRecorder.posted).allSatisfy { !$0.active && !$0.sound },
            "A story below the breaking score is passive and silent when it notifies")
        let minimalRecorder = Recorder()
        let minimal = NotificationService(post: { await minimalRecorder.record(Posted($0)) }, spacing: .zero)
        await minimal.triageAndNotify(
            newArticles: [quiet, loud, third, single], delivery: .init(mode: .minimal, events: events))
        assertEqual(
            (await minimalRecorder.posted).first?.body, "2 new articles across 2 sources",
            "Summary modes count one report per event too")
        assertEqual((await minimalRecorder.posted).first?.category, "", "A summary banner has no story actions")

        // 6. Normal lane (#588, #665): of 100 new stories, three are breaking, every fourth is Technology (a top
        // interest) and every tenth event has three publishers. At most five normal banners in the rolling hour.
        var seeded: [(article: FeedArticle, score: Double)] = []
        var seededEvents: [String: String] = [:]
        var publishers: [String: Int] = [:]
        for index in 0..<100 {
            var article = report(100 + index, "Story \(index)")
            article.category = ["Technology", "Food", "Travel", "Sports"][index % 4]
            article.identityFeedURL = "https://other.invalid/feed"
            seededEvents[article.id] = "seeded-\(index)"
            publishers["seeded-\(index)"] = index % 10 == 0 ? 3 : 1
            seeded.append((article, index < 3 ? 0.7 : 0.3))
        }
        var delivery = NotificationDelivery(mode: .full, events: seededEvents)
        delivery.publishers = publishers
        delivery.interests = NotificationService.topInterests(["technology": 9, "politics": 4, "world": 2, "food": 1])
        assertEqual(
            NotificationService.rankedInterests(["technology": 9, "politics": 4, "world": 2, "food": 1]),
            ["technology", "politics", "world"], "The top three interests by weight")
        func planned(_ delivery: NotificationDelivery, pending: [String: [(article: FeedArticle, score: Double)]] = [:])
            -> [String]
        {
            NotificationService.plan(new: seeded, pending: pending, delivery: delivery).banners.map {
                $0.article?.title ?? NotificationService.groupedBody($0)
            }
        }
        assertEqual(
            planned(delivery), ["Story 0", "Story 1", "Story 2", "Story 20", "Story 40"],
            "Breaking stories and top-interest stories with three publishers notify, strongest first, five at most")
        delivery.ledger.normalLastHour = 3
        assertEqual(planned(delivery), ["Story 0", "Story 1"], "The rolling hour's earlier banners use the allowance")
        delivery.ledger.normalLastHour = 5
        assertTrue(planned(delivery).isEmpty, "A full hour posts no normal banner")
        delivery.ledger.normalLastHour = 0
        delivery.interests = []
        assertEqual(
            planned(delivery), ["Story 0", "Story 1", "Story 2"], "Without interests only breaking stories notify")

        // 7. Repeated events (#545, #665): an event announced today stays quiet while its lead headline is the one
        // announced, unless it rises to a higher lane; a new lead headline notifies again.
        delivery.leadTitles = ["seeded-1": "Story 1 lead"]
        delivery.ledger.announced = [
            "seeded-1": .init(leadKey: EventFeedSummary.titleKey("Story 1 lead"), lane: .normal)
        ]
        assertEqual(planned(delivery), ["Story 0", "Story 2"], "A second report of an announced event does not notify")
        delivery.ledger.announced["seeded-1"]?.leadKey = EventFeedSummary.titleKey("An earlier lead")
        assertEqual(planned(delivery), ["Story 0", "Story 1", "Story 2"], "A changed lead headline notifies again")

        // 8. Starred lane: one banner per feed and 20 minutes, standing for every pending story (#665).
        let starredFeed = "https://starred.invalid/feed"
        func starredStory(_ index: Int, event: String? = nil) -> (article: FeedArticle, score: Double) {
            var article = FeedArticle(
                title: "Starred \(index)", link: "https://notify.invalid/\(500 + index)", guid: "notify-\(500 + index)",
                description: "", pubDate: Date(timeIntervalSince1970: 1_700_000_000), source: "Starred Daily")
            article.identityFeedURL = starredFeed
            if let event { delivery.events[article.id] = event }
            return (article, 0.3)
        }
        delivery.starredFeedURLs = [starredFeed]
        delivery.ledger.announced = [:]
        let one = [starredFeed: [starredStory(1)]]
        assertTrue(planned(delivery, pending: one).contains("Starred 1"), "One pending story is an individual banner")
        let burst = (0..<20).map { starredStory($0) }
        let grouped = NotificationService.plan(new: seeded, pending: [starredFeed: burst], delivery: delivery).banners
            .filter { $0.lane == .starred }
        assertEqual(grouped.count, 1, "Twenty stories from a starred feed are one banner, not twenty")
        assertEqual(grouped.first?.title, "Starred Daily", "A grouped starred banner is titled with the feed")
        assertEqual(grouped.first?.thread, "starred-\(starredFeed)", "Grouped starred banners share a feed thread")
        assertTrue(
            grouped.first.map(NotificationService.groupedBody)?.hasPrefix("20 new stories\nStarred ") == true,
            "The grouped body counts the stories, then two headlines")
        delivery.ledger.lastStarred[starredFeed] = delivery.now.addingTimeInterval(-10 * 60)
        assertFalse(planned(delivery, pending: one).contains("Starred 1"), "Within 20 minutes the feed stays pending")
        delivery.ledger.lastStarred[starredFeed] = delivery.now.addingTimeInterval(-21 * 60)
        assertTrue(planned(delivery, pending: one).contains("Starred 1"), "After 20 minutes its pending stories post")
        delivery.starredFeedURLs = []
        assertFalse(planned(delivery, pending: one).contains("Starred 1"), "Unstarring stops the feed's banners")
        delivery.starredFeedURLs = [starredFeed]

        // B: an event announced only as normal rises to starred; one announced as starred posts no individual banner,
        // but its story still counts in the feed's next group.
        let risen = [starredFeed: [starredStory(30, event: "known")]]
        delivery.ledger.announced = ["known": .init(leadKey: EventFeedSummary.titleKey("Starred 30"), lane: .normal)]
        assertTrue(planned(delivery, pending: risen).contains("Starred 30"), "Normal → starred notifies")
        delivery.ledger.announced["known"]?.lane = .starred
        assertFalse(planned(delivery, pending: risen).contains("Starred 30"), "A starred event does not repeat")
        let mixed = NotificationService.plan(
            new: seeded, pending: [starredFeed: [starredStory(30, event: "known"), starredStory(31)]],
            delivery: delivery
        ).banners.filter { $0.lane == .starred }
        assertEqual(mixed.first?.count, 2, "N counts the announced event's story as well")
        assertEqual(mixed.first?.headlines.first, "Starred 31", "Headlines prefer the unannounced story")
        delivery.ledger.announced = [:]

        // 9. Priority lane: exceptional news, the highest lane, coalesced in bursts and never silenced.
        assertTrue(
            NotificationService.isPriority(title: "Earthquake kills hundreds", score: 0.8, publishers: 4),
            "A full-weight signal, a high score and four publishers are priority")
        assertFalse(
            NotificationService.isPriority(title: "Earthquake kills hundreds", score: 0.8, publishers: 3),
            "Three publishers are not enough")
        assertFalse(
            NotificationService.isPriority(title: "President announces a fund", score: 0.9, publishers: 6),
            "Half-weight words never make priority")
        var majors: [(article: FeedArticle, score: Double)] = []
        for index in 0..<5 {
            let article = report(700 + index, "Explosion \(index)")
            delivery.events[article.id] = "major-\(index)"
            delivery.publishers["major-\(index)"] = 5
            majors.append((article, 0.9 - Double(index) / 100))
        }
        var priority = NotificationService.plan(new: majors, pending: [:], delivery: delivery)
        assertEqual(
            priority.banners.map { $0.article?.title ?? NotificationService.groupedBody($0) },
            ["Explosion 0", "Explosion 1", "Explosion 2", "2 more major stories\nExplosion 3\nExplosion 4"],
            "A priority burst posts three banners, then one grouped banner")
        assertTrue(priority.banners.allSatisfy { $0.lane == .priority && $0.sound }, "Priority banners sound")
        delivery.ledger.priorityLastHalfHour = 3
        delivery.ledger.priorityGroupLastHalfHour = true
        priority = NotificationService.plan(new: majors, pending: [:], delivery: delivery)
        assertTrue(priority.banners.isEmpty, "Past both limits nothing posts now")
        assertEqual(priority.queued.map(\.event), (0..<5).map { "major-\($0)" }, "Every key waits; none is silenced")
        delivery.ledger.priorityGroupLastHalfHour = false
        delivery.ledger.priorityQueue = priority.queued
        priority = NotificationService.plan(new: [], pending: [:], delivery: delivery)
        assertEqual(priority.banners.map(\.count), [5], "The waiting keys arrive in the next grouped banner")
        assertEqual(
            Set(priority.banners.first.map { Array($0.announces.keys) } ?? []),
            Set((0..<5).map { "major-\($0)" } + (priority.banners.first?.members ?? [])),
            "The grouped banner announces every waiting key and each key's own report (#790)")
        delivery.ledger.priorityLastHalfHour = 0
        delivery.ledger.priorityQueue = []

        // A higher lane wins: an event that is priority and has a starred report posts one priority banner.
        var starredMajor = majors[0].article
        starredMajor.identityFeedURL = starredFeed
        delivery.events[starredMajor.id] = "major-0"
        let both = NotificationService.plan(
            new: [majors[0], (starredMajor, 0.3)], pending: [starredFeed: [(starredMajor, 0.3)]], delivery: delivery)
        assertEqual(
            both.banners.map(\.lane), [.priority], "The same event qualifying twice posts once, in the higher lane")
        let together = NotificationService.plan(
            new: seeded + [majors[1]], pending: [starredFeed: [starredStory(40), starredStory(41)]], delivery: delivery)
        assertEqual(
            together.banners.map(\.lane), [.priority, .starred, .normal, .normal, .normal],
            "Simultaneous arrivals post priority, then the starred group, then normal stories")

        // Two events of one story (#740): one banner per pass, threaded by the story; a later event of an announced
        // story adds to it without notifying again, unless it reaches a higher lane.
        var storyDelivery = NotificationDelivery(mode: .full)
        let stormFirst = report(800, "Storm reaches the coast")
        let stormSecond = report(801, "Storm leaves thousands without power")
        let stormMajor = report(802, "Explosion at a storm shelter")
        storyDelivery.events = [stormFirst.id: "storm-a", stormSecond.id: "storm-b", stormMajor.id: "storm-c"]
        storyDelivery.stories = ["storm-b": "storm-a", "storm-c": "storm-a"]
        storyDelivery.publishers = ["storm-c": 5]
        let storyPass = NotificationService.plan(
            new: [(stormFirst, 0.7), (stormSecond, 0.75)], pending: [:], delivery: storyDelivery
        ).banners
        assertEqual(
            storyPass.map { $0.article?.title ?? "" }, ["Storm leaves thousands without power"],
            "Two events of one story post one banner, by the stronger report")
        assertEqual(storyPass.first?.thread, "storm-a", "A story's banners share the story's thread")
        storyDelivery.ledger.announced["storm-a"] = .init(
            leadKey: EventFeedSummary.titleKey(stormFirst.title), lane: .normal)
        assertTrue(
            NotificationService.plan(new: [(stormSecond, 0.75)], pending: [:], delivery: storyDelivery).banners
                .isEmpty,
            "A new event of an announced story does not notify again")
        assertEqual(
            NotificationService.plan(new: [(stormMajor, 0.9)], pending: [:], delivery: storyDelivery).banners.map(
                \.lane), [.priority],
            "A new event of an announced story notifies when it reaches a higher lane")
        // Both events announced: the stronger one unchanged, the other with a new lead headline. The new lead posts.
        var bothAnnounced = storyDelivery
        bothAnnounced.ledger.announced["storm-b"] = .init(leadKey: "an older lead", lane: .normal)
        bothAnnounced.ledger.announced["storm-a"] = .init(
            leadKey: EventFeedSummary.titleKey(stormFirst.title), lane: .normal)
        assertEqual(
            NotificationService.plan(
                new: [(stormFirst, 0.8), (stormSecond, 0.75)], pending: [:], delivery: bothAnnounced
            ).banners.map { $0.article?.title ?? "" }, ["Storm leaves thousands without power"],
            "An unchanged event of a story does not hide the other event's new lead")
        // A waiting priority key of the story drops out when another of its events gets a banner this pass.
        var queuedStory = NotificationDelivery(mode: .full)
        let shelterBlast = report(803, "Explosion at a storm shelter kills four")
        queuedStory.events = [shelterBlast.id: "storm-c"]
        queuedStory.stories = ["storm-b": "storm-a", "storm-c": "storm-a"]
        queuedStory.publishers = ["storm-c": 5]
        queuedStory.ledger.priorityQueue = [
            QueuedPriority(event: "storm-b", title: "Storm leaves thousands without power", score: 0.8, leadKey: "x")
        ]
        let queuedPass = NotificationService.plan(new: [(shelterBlast, 0.9)], pending: [:], delivery: queuedStory)
        assertEqual(
            queuedPass.banners.map(\.grouped), [false],
            "A story's waiting key is covered by its new individual banner, not grouped beside it")
        // Two waiting keys of one story, left by earlier passes, count once in the next grouped banner.
        var twoQueued = NotificationDelivery(mode: .full)
        twoQueued.stories = ["storm-b": "storm-a", "storm-c": "storm-a"]
        twoQueued.ledger.priorityQueue = [
            QueuedPriority(event: "storm-c", title: "Explosion at a storm shelter", score: 0.9, leadKey: "c"),
            QueuedPriority(event: "storm-b", title: "Storm leaves thousands without power", score: 0.8, leadKey: "b"),
            QueuedPriority(event: "quake", title: "Earthquake strikes the north", score: 0.85, leadKey: "q"),
        ]
        let groupedOnce = NotificationService.plan(new: [], pending: [:], delivery: twoQueued).banners
        assertEqual(groupedOnce.map(\.count), [2], "A story queued twice counts once in the grouped banner")
        assertEqual(
            Set(groupedOnce.first.map { Array($0.announces.keys) } ?? []), ["storm-b", "storm-c", "quake"],
            "The grouped banner still announces every waiting key")
        // A waiting key whose own event was announced under another lead still posts after a priority announcement.
        twoQueued.ledger.priorityQueue = [
            QueuedPriority(event: "storm-b", title: "Storm death toll rises", score: 0.8, leadKey: "new lead")
        ]
        twoQueued.ledger.announced["storm-b"] = .init(leadKey: "old lead", lane: .priority)
        assertEqual(
            NotificationService.plan(new: [], pending: [:], delivery: twoQueued).banners.map(\.count), [1],
            "A waiting key with a changed lead survives the story's priority announcement")
        // An event announced in the normal lane whose story another event announced in priority does not post again
        // in the starred lane without a new lead.
        var laneDelivery = NotificationDelivery(mode: .full)
        var starredStorm = stormFirst
        starredStorm.identityFeedURL = "https://starred.invalid/feed"
        laneDelivery.starredFeedURLs = ["https://starred.invalid/feed"]
        laneDelivery.events = [starredStorm.id: "storm-a"]
        laneDelivery.stories = ["storm-c": "storm-a"]
        laneDelivery.ledger.announced = [
            "storm-a": .init(leadKey: EventFeedSummary.titleKey(stormFirst.title), lane: .normal),
            "storm-c": .init(leadKey: "c", lane: .priority),
        ]
        assertTrue(
            NotificationService.plan(
                new: [(starredStorm, 0.5)], pending: ["https://starred.invalid/feed": [(starredStorm, 0.5)]],
                delivery: laneDelivery
            ).banners.isEmpty,
            "A story announced in priority does not post again in the starred lane")
        // A stale starred event does not hide a fresh normal event of the same story.
        var staleStarred = NotificationDelivery(mode: .full)
        staleStarred.starredFeedURLs = ["https://starred.invalid/feed"]
        staleStarred.events = [starredStorm.id: "storm-a", stormSecond.id: "storm-b"]
        staleStarred.stories = ["storm-b": "storm-a"]
        staleStarred.ledger.announced = [
            "storm-a": .init(leadKey: EventFeedSummary.titleKey(stormFirst.title), lane: .starred),
            "storm-b": .init(leadKey: "an older lead", lane: .normal),
        ]
        assertEqual(
            NotificationService.plan(
                new: [(starredStorm, 0.5), (stormSecond, 0.75)],
                pending: ["https://starred.invalid/feed": [(starredStorm, 0.5)]], delivery: staleStarred
            ).banners.map { $0.article?.title ?? "" }, ["Storm leaves thousands without power"],
            "A fresh normal event posts beside a stale starred sibling")
        // A stale priority event does not hide a fresh normal event of the same story.
        var stalePriority = NotificationDelivery(mode: .full)
        stalePriority.events = [stormMajor.id: "storm-c", stormSecond.id: "storm-b"]
        stalePriority.stories = ["storm-b": "storm-a", "storm-c": "storm-a"]
        stalePriority.publishers = ["storm-c": 5]
        stalePriority.ledger.announced = [
            "storm-c": .init(leadKey: EventFeedSummary.titleKey(stormMajor.title), lane: .priority),
            "storm-b": .init(leadKey: "an older lead", lane: .normal),
        ]
        assertEqual(
            NotificationService.plan(
                new: [(stormMajor, 0.9), (stormSecond, 0.75)], pending: [:], delivery: stalePriority
            ).banners.map { $0.article?.title ?? "" }, ["Storm leaves thousands without power"],
            "A fresh normal event posts beside a stale priority sibling with a new lead")

        // Three publishers on arrival give a normal banner; a fourth makes it priority once, and never a third time.
        let rising = report(800, "Explosion levels block")
        delivery.events[rising.id] = "rising"
        delivery.publishers["rising"] = 3
        delivery.leadTitles["rising"] = rising.title
        let first = NotificationService.plan(new: [(rising, 0.9)], pending: [:], delivery: delivery).banners
        assertEqual(first.map(\.lane), [.normal], "Three publishers: a normal banner")
        let lead = EventFeedSummary.titleKey(rising.title)
        delivery.ledger.announced["rising"] = .init(leadKey: lead, lane: .normal)
        delivery.publishers["rising"] = 4
        let follow = report(801, "Explosion toll rises")
        delivery.events[follow.id] = "rising"
        assertEqual(
            NotificationService.plan(new: [(follow, 0.9)], pending: [:], delivery: delivery).banners.map(\.lane),
            [.priority], "The fourth publisher raises the event to one priority banner")
        delivery.ledger.announced["rising"]?.lane = .priority
        let later = report(802, "Explosion inquiry")
        delivery.events[later.id] = "rising"
        assertTrue(
            NotificationService.plan(new: [(later, 0.9)], pending: [:], delivery: delivery).banners.isEmpty,
            "An event announced as priority never posts a third banner")

        // Storage (#545, #665): the ledger reads what was recorded, keeps the highest lane, clamps a clock set back and
        // prunes old rows.
        do {
            let db = DatabaseEngine(path: ":memory:")
            try await db.open()
            let opener = report(300, "Lead report opens the event")
            let joiner = report(301, "Later report joins the event")
            try await db.upsertArticles([opener, joiner])
            let event = try await db.createEvent(memberArticleIDs: [opener.id])
            _ = try await db.addArticles([joiner.id], toEvent: event.id)
            assertEqual(
                try await db.eventLeadTitles([event.id]), [event.id: opener.title],
                "The lead story is the one that opened the event, not the newest member")
            let now = Date(timeIntervalSince1970: 1_700_000_000)
            let key = EventFeedSummary.titleKey(opener.title)
            try await db.recordNotification(
                PlannedBanner(
                    lane: .priority, grouped: false, thread: event.id, sound: true, announces: [event.id: key]),
                at: now)
            try await db.recordNotification(
                PlannedBanner(
                    lane: .normal, grouped: false, thread: event.id, sound: false, announces: [event.id: key]),
                at: now)
            try await db.recordNotification(
                PlannedBanner(lane: .starred, grouped: true, count: 4, feedURL: starredFeed, thread: "s", sound: false),
                at: now)
            try await db.queuePriority(
                [QueuedPriority(event: "waiting", title: "W", score: 0.8, leadKey: "w")], at: now)
            var ledger = try await db.notificationLedger(now: now.addingTimeInterval(60))
            assertEqual(ledger.announced[event.id], .init(leadKey: key, lane: .priority), "The highest lane is kept")
            assertEqual(ledger.normalLastHour, 1, "Normal banners count in the rolling hour")
            assertEqual(ledger.priorityLastHalfHour, 1, "Individual priority banners count in the half hour")
            assertEqual(ledger.lastStarred[starredFeed], now, "The feed's last starred banner is kept")
            assertEqual(ledger.priorityQueue.map(\.event), ["waiting"], "Waiting priority keys are read back")
            ledger = try await db.notificationLedger(now: now.addingTimeInterval(3601))
            assertEqual(ledger.normalLastHour, 0, "The hour rolls")
            ledger = try await db.notificationLedger(now: now.addingTimeInterval(-7200))
            assertEqual(ledger.normalLastHour, 1, "A clock set back clamps the later rows to now")
            ledger = try await db.notificationLedger(now: now.addingTimeInterval(-7200 + 3601))
            assertEqual(ledger.normalLastHour, 0, "So the window lasts at most its length from the change")
            ledger = try await db.notificationLedger(now: now.addingTimeInterval(2 * 86400))
            assertTrue(
                ledger.announced.isEmpty && ledger.priorityQueue.isEmpty, "A day later nothing is announced or waiting")
            try await db.recordNotification(
                PlannedBanner(lane: .normal, grouped: false, thread: "x", sound: false),
                at: now.addingTimeInterval(8 * 86400))
            ledger = try await db.notificationLedger(now: now.addingTimeInterval(8 * 86400))
            assertTrue(ledger.lastStarred.isEmpty, "Rows older than a week are pruned")
            await db.close()
        } catch {
            assertTrue(false, "Notification delivery storage failed: \(error)")
        }
    }

    /// #790: a banner for a report outside any event records the report itself. When another outlet's report later
    /// clusters with it, the event counts as announced, so the new report posts no second banner on another thread.
    @MainActor
    static func testNotifyBeforeClustering() async throws {
        print("  - Testing a report notified before clustering announces its later event (#790)...")
        let db = DatabaseEngine(path: ":memory:")
        try await db.open()
        let now = Date(timeIntervalSince1970: 1_700_000_000)
        func report(_ id: String, _ title: String, hoursAgo: Double, source: String) -> FeedArticle {
            FeedArticle(
                storedID: id, title: title, link: "https://notify.invalid/\(id)", guid: id, description: "",
                pubDate: now.addingTimeInterval(-hoursAgo * 3600), source: source)
        }
        let first = report("n790-a", "Breaking: Mosul dam failure, emergency declared", hoursAgo: 2, source: "Wire One")
        let second = report(
            "n790-b", "Breaking: Mosul dam bursts, emergency declared", hoursAgo: 1, source: "Daily Two")
        _ = try await db.upsertArticles([first, second])

        let alone = NotificationService.plan(
            new: [(article: first, score: 0.9)], pending: [:],
            delivery: NotificationDelivery(mode: .full, now: now, ledger: try await db.notificationLedger(now: now)))
        assertEqual(alone.banners.count, 1, "The report alone posts a banner")
        assertEqual(
            alone.banners.first?.announces, [first.id: EventFeedSummary.titleKey(first.title)],
            "A report outside any event is announced under its own ID")
        for banner in alone.banners { try await db.recordNotification(banner, at: now) }
        var ledger = try await db.notificationLedger(now: now.addingTimeInterval(60))
        assertTrue(
            NotificationService.plan(
                new: [(article: first, score: 0.9)], pending: [:],
                delivery: NotificationDelivery(mode: .full, now: now.addingTimeInterval(60), ledger: ledger)
            ).banners.isEmpty, "The announced report alone does not post again")

        let event = try await db.createEvent(memberArticleIDs: [first.id, second.id], at: now)
        let later = now.addingTimeInterval(600)
        ledger = try await db.notificationLedger(now: later)
        let announced = NotificationLedger.Announcement(leadKey: EventFeedSummary.titleKey(first.title), lane: .normal)
        assertEqual(
            ledger.announced, [event.id: announced, first.id: announced],
            "The report's announcement is copied to the event it joined, under the event's lead headline, and kept")
        let clustered = NotificationService.plan(
            new: [(article: second, score: 0.9)], pending: [:],
            delivery: NotificationDelivery(
                mode: .full, events: [first.id: event.id, second.id: event.id], publishers: [event.id: 2],
                leadTitles: [event.id: first.title], now: later, ledger: ledger))
        assertTrue(clustered.banners.isEmpty, "The second outlet's report of the announced event posts no banner")

        // The report keeps its own row: separated into another event, it makes that event announced too.
        let third = report("n790-c", "Breaking: Mosul dam failure floods villages", hoursAgo: 0.5, source: "Post")
        _ = try await db.upsertArticles([third])
        _ = try await db.separateArticle(first.id, fromEvent: event.id)
        let moved = try await db.createEvent(memberArticleIDs: [first.id, third.id], at: later)
        ledger = try await db.notificationLedger(now: later.addingTimeInterval(60))
        assertEqual(
            ledger.announced[moved.id]?.lane, .normal, "The event the separated report joins inherits its announcement")
        let separated = NotificationService.plan(
            new: [(article: third, score: 0.9)], pending: [:],
            delivery: NotificationDelivery(
                mode: .full, events: [first.id: moved.id, third.id: moved.id], publishers: [moved.id: 2],
                leadTitles: [moved.id: first.title], now: later.addingTimeInterval(60), ledger: ledger))
        assertTrue(separated.banners.isEmpty, "The separated report's new event posts no duplicate banner")
        await db.close()
    }

    /// Notification lanes through `FeedManager` (#665): the normal limit rolls across refreshes and a relaunch, delivery
    /// never removes a story, starring a feed brings up no backlog, and a starred burst is one banner.
    @MainActor
    static func testNotificationLanesAcrossRefreshes(fixtureRoot: URL) async throws {
        print("  - Testing notification lanes across refreshes and relaunch...")
        // Three full-weight signal words and six named places: each is breaking, and alone it is never priority.
        let headlines = [
            "Breaking: earthquake in Tokyo, Osaka, Kyoto, Nagoya, Sapporo and Kobe; emergency declared",
            "Breaking: explosion in Houston, Dallas, Austin, Denver, Phoenix and Tucson; emergency declared",
            "Breaking: attack in Paris, Lyon, Marseille, Nice, Lille and Bordeaux; emergency declared",
            "Breaking: crisis in Lagos, Abuja, Kano, Ibadan, Accra and Lome; emergency declared",
            "Breaking: mayors arrested in Madrid, Seville, Valencia, Bilbao, Malaga and Zaragoza; emergency session",
            "Breaking: dozens killed in Lima, Quito, Bogota, Caracas, Santiago and Montevideo; emergency declared",
            "Breaking: minister resigns in Cairo, Alexandria, Giza, Luxor, Aswan and Suez; emergency session",
            "Breaking: cars recalled in Berlin, Munich, Hamburg, Cologne, Frankfurt and Stuttgart; emergency checks",
            "Breaking: governors indicted in Sydney, Melbourne, Brisbane, Perth, Adelaide and Hobart; emergency sitting",
        ]
        let start = Date()
        func story(_ id: String, _ title: String, source: String) -> FeedArticle {
            FeedArticle(
                title: title, link: fixtureRoot.appendingPathComponent("lanes/\(id)").absoluteString, guid: id,
                description: "", pubDate: start, source: source)
        }
        let loud = headlines.indices.map { story("loud-\($0)", headlines[$0], source: "Wire \($0)") }
        let plainFeed = fixtureRoot.appendingPathComponent("lanes-plain").absoluteString
        let starredFeed = fixtureRoot.appendingPathComponent("lanes-starred").absoluteString
        let suite = testDefaultsSuite("test.notification.lanes")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        settings.feedURLs = [plainFeed, starredFeed]
        settings.aiEnabled = false
        settings.notificationsEnabled = true
        settings.notificationMode = .full
        struct Posted: Sendable {
            let title: String
            let body: String
            let thread: String
            let category: String
        }
        actor Recorder {
            var posted: [Posted] = []
            func record(_ request: UNNotificationRequest) {
                posted.append(
                    Posted(
                        title: request.content.title, body: request.content.body,
                        thread: request.content.threadIdentifier, category: request.content.categoryIdentifier))
            }
        }
        let recorder = Recorder()
        let service = NotificationService(post: { await recorder.record($0) }, spacing: .zero)
        let path = FileManager.default.temporaryDirectory.appendingPathComponent("lanes-\(UUID().uuidString).sqlite3")
            .path
        defer {
            for suffix in ["", "-wal", "-shm"] { try? FileManager.default.removeItem(atPath: path + suffix) }
        }
        var store = ArticleStore(database: DatabaseEngine(path: path))
        await store.initialize()
        // A refresh without a clock reads the real one at the pass, as the app does, after its stories are stored. It
        // returns the titles of the stories its banners covered (#584).
        @discardableResult
        func refresh(plain: [FeedArticle] = [], starred: [FeedArticle] = [], at clock: Date? = nil) async -> Set<String>
        {
            let manager = FeedManager(
                settings: settings, store: store, schedulesRefresh: false,
                fetchBatch: { urls, _ in urls.map { ($0, $0 == starredFeed ? starred : plain, nil, nil) } },
                notifyBatch: { articles, delivery in
                    await service.triageAndNotify(newArticles: articles, delivery: delivery)
                }, imageFinder: .unavailable, now: { clock ?? Date() })
            await manager.fetchFeedsAsync()
            manager.stopBackgroundWork()
            return Set(store.articles.filter { manager.notifiedStoryIDs.contains($0.id) }.map(\.title))
        }

        // The normal limit rolls: five of six post, a refresh 30 minutes later after a relaunch posts none, and one 61
        // minutes after the first posts again.
        let firstNotified = await refresh(plain: Array(loud.prefix(6)), at: start)
        assertEqual(await recorder.posted.count, 5, "Five normal banners in the first hour")
        assertEqual(firstNotified.count, 5, "The five posted stories count as notified, the sixth does not")
        assertTrue(firstNotified.isSubset(of: Set(headlines.prefix(6))), "Only this refresh's stories are notified")
        await store.database.close()
        store = ArticleStore(database: DatabaseEngine(path: path))
        await store.initialize()
        await refresh(plain: Array(loud[6...7]), at: start.addingTimeInterval(30 * 60))
        assertEqual(await recorder.posted.count, 5, "Thirty minutes later, after a relaunch, the hour is still full")
        await refresh(plain: [loud[8]], at: start.addingTimeInterval(61 * 60))
        assertEqual(await recorder.posted.count, 6, "Sixty-one minutes after the first banners, one posts again")
        let stored = Set(try await store.database.fetchArticles(limit: nil).map(\.title))
        assertTrue(Set(headlines).isSubset(of: stored), "Every story is stored, notified or not")
        assertTrue(
            Set(headlines).isSubset(of: Set(store.articles.map(\.title))), "Every story stays in the reader's feed")

        // Starring a feed brings up none of its backlog; its next new story notifies, and a burst 21 minutes later is
        // one grouped banner.
        let backlog = (0..<5).map {
            story("backlog-\($0)", "Starred column \($0) on garden design", source: "Starred Daily")
        }
        await refresh(starred: backlog)
        let before = await recorder.posted.count
        assertTrue(settings.setFeedStarred(starredFeed, true), "The feed is starred")
        await refresh(plain: [story("quiet", "Library extends opening hours", source: "Town Paper")])
        assertEqual(await recorder.posted.count, before, "Starring a feed posts nothing for its backlog")
        await refresh(
            starred: backlog + [story("fresh", "Starred column on winter bulbs", source: "Starred Daily")])
        let single = await recorder.posted.dropFirst(before)
        assertEqual(single.map(\.title), ["Starred Daily"], "The feed's first new story is one starred banner")
        assertEqual(
            single.map(\.category), [NotificationActionIdentifier.category],
            "A starred story's banner has story actions")
        let burst = (0..<20).map { story("burst-\($0)", "Starred note \($0) about orchards", source: "Starred Daily") }
        let burstNotified = await refresh(starred: burst, at: Date().addingTimeInterval(21 * 60))
        assertEqual(burstNotified, Set(burst.map(\.title)), "A grouped banner's stories all count as notified")
        let grouped = await recorder.posted.dropFirst(before + 1)
        assertEqual(grouped.count, 1, "Twenty new starred stories are one banner: \(grouped.map(\.body))")
        assertEqual(grouped.first?.thread, "starred-\(starredFeed)", "The burst is threaded under the feed")
        assertTrue(
            grouped.first?.body.hasPrefix("20 new stories\n") == true,
            "The burst counts every story: \(grouped.first?.body ?? "")")
        assertEqual(grouped.first?.category, "", "A grouped banner has no story actions")
        await store.database.close()
    }

    /// Cross-refresh dedupe through `FeedManager` (#545): the first refresh announces an event; a report that joins it
    /// in the next refresh posts no second banner; once the recorded lead headline differs, a new report notifies.
    @MainActor
    static func testNotificationDedupeAcrossRefreshes(fixtureRoot: URL) async throws {
        print("  - Testing notification dedupe across refreshes...")
        let now = Date()
        func report(_ id: String, _ title: String, hoursAgo: Double, source: String) -> FeedArticle {
            FeedArticle(
                title: title, link: fixtureRoot.appendingPathComponent("dedupe/\(id)").absoluteString, guid: id,
                description:
                    "The disaster agency AFAD said buildings collapsed in Malatya, Ankara and Istanbul after the earthquake struck eastern Turkey.",
                pubDate: now.addingTimeInterval(-hoursAgo * 3600), source: source)
        }
        // Three signal words and the named places make every report breaking, so only the dedupe keeps one quiet.
        let quake = [
            report(
                "d1", "Breaking: earthquake strikes Malatya in eastern Turkey, emergency declared", hoursAgo: 3,
                source: "Wire One"),
            report(
                "d2", "Breaking: Malatya earthquake, emergency declared as AFAD says buildings collapsed",
                hoursAgo: 2.5,
                source: "Daily Two"),
            report(
                "d3", "Breaking: rescuers search collapsed buildings after Malatya earthquake, emergency declared",
                hoursAgo: 2, source: "Herald Three"),
            report(
                "d4", "Breaking: eastern Turkey earthquake, emergency declared as buildings collapse in Malatya",
                hoursAgo: 1.5, source: "Courier Four"),
        ]
        let feeds = (1...4).map { fixtureRoot.appendingPathComponent("dedupe-feed-\($0)").absoluteString }
        let suite = testDefaultsSuite("test.notification.dedupe")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        settings.feedURLs = feeds
        settings.aiEnabled = false
        settings.notificationsEnabled = true
        settings.notificationMode = .full
        let store = ArticleStore(database: DatabaseEngine(path: ":memory:"))
        await store.initialize()
        actor Recorder {
            var threads: [String] = []
            func record(_ thread: String) { threads.append(thread) }
        }
        let recorder = Recorder()
        let service = NotificationService(
            post: { await recorder.record($0.content.threadIdentifier) }, spacing: .zero)
        // Each refresh is a manager over the same library whose feeds carry the first `count` reports, one per feed.
        func refresh(_ count: Int) async {
            let manager = FeedManager(
                settings: settings, store: store, schedulesRefresh: false,
                fetchBatch: { urls, _ in
                    urls.map { url in
                        let index = feeds.firstIndex(of: url) ?? count
                        return (url, index < count ? [quake[index]] : [], nil, nil)
                    }
                },
                notifyBatch: { articles, delivery in
                    await service.triageAndNotify(newArticles: articles, delivery: delivery)
                }, imageFinder: .unavailable)
            await manager.fetchFeedsAsync()
            manager.stopBackgroundWork()
        }

        await refresh(2)
        let first = await recorder.threads
        assertEqual(first.count, 1, "Two reports of one new event are one banner: \(first)")
        let ids = store.articles.map(\.id)
        let event = try await store.database.eventIDs(forArticles: ids)
        assertEqual(Set(event.values).count, 1, "The first refresh groups both reports into one event: \(event)")

        await refresh(3)
        let joined = try await store.database.eventIDs(forArticles: store.articles.map(\.id))
        assertEqual(Set(joined.values).count, 1, "The third report joins the announced event: \(joined)")
        assertEqual(await recorder.threads, first, "A report joining an event announced today posts no second banner")

        guard let announced = joined.values.first else { return }
        try await store.database.recordNotification(
            PlannedBanner(
                lane: .normal, grouped: false, thread: announced, sound: false,
                announces: [announced: EventFeedSummary.titleKey("An earlier lead headline")]), at: Date())
        await refresh(4)
        assertEqual(
            await recorder.threads, first + [announced], "A new report notifies once the lead headline changed")
        await store.database.close()

        // A merge never makes an announced story new again: the absorbed event's announcement and waiting priority key
        // move to the event it joined, keyed to that event's lead headline, so its next report stays quiet.
        let merges = DatabaseEngine(path: ":memory:")
        try await merges.open()
        let lead = report("m1", "Dam bursts near Mosul as floodwater reaches villages", hoursAgo: 4, source: "Wire One")
        let fragment = report("m2", "Breaking: Mosul dam failure, emergency declared", hoursAgo: 3, source: "Daily Two")
        let waiting = report("m3", "Breaking: Mosul flood toll rises, emergency declared", hoursAgo: 2, source: "Post")
        let later = report("m4", "Breaking: Mosul evacuations widen, emergency declared", hoursAgo: 1, source: "Times")
        _ = try await merges.upsertArticles([lead, fragment, waiting, later])
        let survivor = try await merges.createEvent(memberArticleIDs: [lead.id]).id
        let absorbed = try await merges.createEvent(memberArticleIDs: [fragment.id]).id
        let queued = try await merges.createEvent(memberArticleIDs: [waiting.id]).id
        try await merges.recordNotification(
            PlannedBanner(
                lane: .priority, grouped: false, thread: absorbed, sound: true,
                announces: [absorbed: EventFeedSummary.titleKey(fragment.title)]), at: now)
        let stale = QueuedPriority(event: queued, title: waiting.title, score: 0.8, leadKey: "old", story: waiting.id)
        try await merges.queuePriority([stale], at: now)
        _ = try await merges.mergeEvents(absorbed, into: survivor)
        _ = try await merges.mergeEvents(queued, into: survivor)
        let ledger = try await merges.notificationLedger(now: now)
        let leadKey = EventFeedSummary.titleKey(lead.title)
        assertEqual(
            ledger.announced, [survivor: .init(leadKey: leadKey, lane: .priority)],
            "The survivor inherits the absorbed announcement and its lane, under its own lead headline")
        assertEqual(
            ledger.priorityQueue,
            [QueuedPriority(event: survivor, title: waiting.title, score: 0.8, leadKey: leadKey, story: waiting.id)],
            "A waiting priority key moves to the survivor with its story")
        let quiet = NotificationService.plan(
            new: [(article: later, score: 0.9)], pending: [:],
            delivery: NotificationDelivery(
                mode: .full, events: [later.id: survivor], publishers: [survivor: 2],
                leadTitles: [survivor: lead.title], now: now, ledger: ledger))
        assertTrue(quiet.banners.isEmpty, "A breaking report of the merged event posts no second banner")
        await merges.close()
    }

    @MainActor
    static func testArticleStoreErrorResilience() async {
        print("  - Testing ArticleStore Error Resilience & Database Failures...")

        let db = DatabaseEngine(path: ":memory:")
        try? await db.open()
        let store = ArticleStore(database: db)
        await store.initialize()

        let article = FeedArticle(
            title: "Test Error Article", link: "https://example.com/error", guid: "test-err-guid", description: "Test",
            pubDate: Date(), source: "Test")
        await store.batchUpsert(articles: [article], feedUrl: "https://example.com/feed")

        // Force close the database to trigger failure scenarios
        await db.close()

        // 1. toggleSave returns false on failure (PR #18)
        let savedResult = await store.toggleSave(article: article)
        assertFalse(savedResult, "toggleSave should return false when database throws an error")

        // 2. markAsRead catches error and does not mutate in-memory read state (PR #19)
        await store.markAsRead(id: "test-err-guid", isRead: true)
        assertFalse(
            store.readArticleIDs.contains("test-err-guid"),
            "readArticleIDs should not contain ID when DB markRead fails")

        // 3. markAllAsRead catches error gracefully without crashing (PR #20)
        await store.markAllAsRead()
    }

    @MainActor
    static func testSystemErrorHardeningAndResilience() async {
        print("  - Testing System Error Hardening & Resilience across Coordinators and Views...")

        // 1. FeedManager.addFeed Boolean feedback
        let suite = testDefaultsSuite("test.error.feedmanager")
        let defaults = UserDefaults(suiteName: suite)!
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: defaults)
        let db = DatabaseEngine(path: ":memory:")
        let store = ArticleStore(database: db)
        await store.initialize()
        let manager = FeedManager(
            settings: settings, store: store, schedulesRefresh: false,
            fetchBatch: { urls, _ in urls.map { ($0, [], nil, nil) } },
            notifyBatch: { _, _ in })

        let validURL = "https://example.com/feed.xml"
        let addedFirst = manager.addFeed(url: validURL)
        assertTrue(addedFirst, "Adding a new valid feed returns true")
        let addedDuplicate = manager.addFeed(url: validURL)
        assertFalse(addedDuplicate, "Adding a duplicate feed returns false")
        let addedInvalid = manager.addFeed(url: "https://")
        assertFalse(addedInvalid, "Adding an invalid scheme-only URL returns false")
        let addedEmpty = manager.addFeed(url: "   ")
        assertFalse(addedEmpty, "Adding an empty/whitespace URL returns false")
        manager.stopBackgroundWork()

        // 2. MigrationCoordinator corrupt legacy data handling
        let migrationSuite = testDefaultsSuite("test.error.migration")
        let migrationDefaults = UserDefaults(suiteName: migrationSuite)!
        defer { removeTestDefaults(migrationSuite) }
        migrationDefaults.set(Data("corrupted JSON content".utf8), forKey: "saved_articles")
        let migrationCoordinator = MigrationCoordinator(database: db, userDefaults: migrationDefaults)
        do {
            let stats = try await migrationCoordinator.migrateIfNeeded()
            assertEqual(stats.savedStories, 0, "Corrupted legacy saved stories are gracefully skipped")
        } catch {
            assertTrue(false, "migrateIfNeeded should not rethrow legacy JSON parsing failure: \(error)")
        }

        // 3. SentenceEmbedder corrupt file handling
        let tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try? FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tempDir) }
        let corruptVocab = tempDir.appendingPathComponent("vocab.txt")
        try? "invalid vocab file".write(to: corruptVocab, atomically: true, encoding: .utf8)
        let corruptModel = tempDir.appendingPathComponent("minilm.mlmodelc")
        try? "invalid coreml model".write(to: corruptModel, atomically: true, encoding: .utf8)
        let embedder = SentenceEmbedder(modelURL: corruptModel, vocabURL: corruptVocab)
        let available = await embedder.isAvailable
        assertFalse(available, "SentenceEmbedder with corrupted files gracefully sets isAvailable to false")

        // 4. OverviewGenerationCoordinator graceful error handling when database closed
        let failingDb = DatabaseEngine(path: ":memory:")
        let failingStore = ArticleStore(database: failingDb)
        let coordinator = OverviewGenerationCoordinator(
            store: failingStore, queue: EnrichmentQueue(store: failingStore))
        await failingDb.close()
        let result = await coordinator.requestOverview(
            eventID: "err-event", eventTitle: "Error Event", membershipVersion: 1,
            articles: [
                FeedArticle(
                    title: "Test", link: "https://example.com/item", guid: "g1",
                    description: "Desc", pubDate: Date(), source: "Src")
            ])
        assertTrue(result == nil, "requestOverview with failing database returns nil without crashing")
    }

    static func testFeedArticleWrapContextNavigation() async {
        print("  - Testing FeedArticleWrap Context Preservation & Filtered Navigation Boundaries...")

        let artA = FeedArticle(
            title: "Article A", link: "https://example.com/a", guid: "a", description: "Desc A", pubDate: Date(),
            source: "Source 1", category: "Technology")
        let artB = FeedArticle(
            title: "Article B", link: "https://example.com/b", guid: "b", description: "Desc B", pubDate: Date(),
            source: "Source 2", category: "Science")
        let artC = FeedArticle(
            title: "Article C", link: "https://example.com/c", guid: "c", description: "Desc C", pubDate: Date(),
            source: "Source 1", category: "Technology")
        let artD = FeedArticle(
            title: "Article D", link: "https://example.com/d", guid: "d", description: "Desc D", pubDate: Date(),
            source: "Source 3", category: "Business")

        let allGlobal = [artA, artB, artC, artD]
        let techFilter = [artA, artC]

        // 1. Wrap with filtered context
        let wrap = FeedArticleWrap(article: artA, contextArticles: techFilter)
        assertEqual(wrap.article.id, artA.id, "Wrapped article ID must match artA")
        assertEqual(wrap.contextArticles.count, 2, "Filtered context must contain exactly 2 articles")
        assertEqual(
            wrap.contextArticles.map(\.id), [artA.id, artC.id], "Filtered context articles must match techFilter")

        // 2. Boundary simulation in filtered context:
        // In techFilter: artA is index 0. Has next (artC), but NO previous.
        let idxA = wrap.contextArticles.firstIndex(where: { $0.id == artA.id })
        assertEqual(idxA, 0, "artA should be at index 0 in filtered context")
        let hasPrevInFilter = idxA.map { $0 > 0 } ?? false
        let hasNextInFilter = idxA.map { $0 + 1 < wrap.contextArticles.count } ?? false
        assertFalse(hasPrevInFilter, "artA must not have previous article in filtered context")
        assertTrue(hasNextInFilter, "artA must have next article (artC) in filtered context")

        // In techFilter: Next article from artA is artC (skipping artB which is Science!)
        let nextArt = wrap.contextArticles[idxA! + 1]
        assertEqual(nextArt.id, artC.id, "Next article in tech filter must be artC, skipping artB")

        // In global context without filter: Next article from artA would have been artB
        let globalIdxA = allGlobal.firstIndex(where: { $0.id == artA.id })!
        let globalNext = allGlobal[globalIdxA + 1]
        assertEqual(globalNext.id, artB.id, "In unfiltered global context, next is artB")

        // 3. Fallback behavior when contextArticles is empty
        let wrapEmpty = FeedArticleWrap(article: artB)
        assertTrue(wrapEmpty.contextArticles.isEmpty, "Default contextArticles should be empty")

        // 4. Stable uniqueness of wrap identity
        let wrap2 = FeedArticleWrap(article: artA, contextArticles: techFilter)
        assertTrue(wrap.id != wrap2.id, "Each wrap must have a distinct UUID identity for navigation state")
    }

    static func testArticleContentRedactionAndTypography() async {
        print("  - Testing ArticleContentRedactor and Typography...")

        // 1. Test trailing and fused boilerplate removal (e.g. '...last year.Read full article\nComments')
        let rawJunk =
            "The launcher delivered a batch of CubeSats to low-Earth orbit from a spaceport in northern Norway, and Isar tasted success after its first test flight ended in failure last year.Read full article\nComments"
        let cleaned = ArticleContentRedactor.redactAndSplit(rawJunk)
        assertEqual(cleaned.count, 1, "Should filter boilerplate lines and clean fused text")
        assertEqual(
            cleaned.first,
            "The launcher delivered a batch of CubeSats to low-Earth orbit from a spaceport in northern Norway, and Isar tasted success after its first test flight ended in failure last year.",
            "Should strip .Read full article and drop Comments")

        // 2. Test syndication footers and standalone boilerplate lines
        let syndicationText = """
            Apple has introduced a new capability in Swift.

            The post Apple Announces New Swift Features appeared first on 9to5Mac.

            Comments
            """
        let cleanedSyndication = ArticleContentRedactor.redactAndSplit(syndicationText)
        assertEqual(cleanedSyndication.count, 1, "Should strip syndication notice and comments line")
        assertEqual(
            cleanedSyndication.first, "Apple has introduced a new capability in Swift.",
            "Content should match without syndication")

        // 3. Test preservation of legitimate words in content
        let normalText = "The spokesperson declined to make any further comments on the ongoing investigation."
        let cleanedNormal = ArticleContentRedactor.cleanText(normalText)
        assertEqual(cleanedNormal, normalText, "Should not redact 'comments' inside a legitimate sentence")

        // 4. Test paragraph splitting for long unformatted RSS blocks (> 650 chars)
        let longBlock =
            "SpaceX is dialing back its Falcon 9 launch program, and there is no certainty about when SpaceX's reusable next-generation super-heavy-lift rocket will carry payloads. "
            + "Customers in any sector will usually welcome competition. Theoretically, competition will lead to lower prices and allow the best to rise to the top. "
            + "So it's no surprise satellite operators are cheering the success of a new launch provider. This was especially the case when Germany's Isar Aerospace reached orbit for the first time with its Spectrum rocket. "
            + "The launcher delivered a batch of CubeSats to low-Earth orbit from a spaceport in northern Norway, marking a milestone."
        let splitParagraphs = ArticleContentRedactor.redactAndSplit(longBlock)
        assertTrue(
            splitParagraphs.count >= 2,
            "Monolithic text should be split into multiple paragraphs at sentence boundaries")

    }

