    static func testContentQualityValidation() async {
        print("  - Testing ContentQualityValidator Rules...")

        // 1. Valid paragraphs pass
        let valid = [
            "The international summit concluded today with landmark agreements on carbon emission reduction targets across all member economies.",
            "Delegates committed billions in concessional financing to support clean energy transitions in developing nations over the next ten years.",
            "Independent observers commended the transparency mechanisms embedded within the final treaty text as unprecedented in multilateral diplomacy.",
        ]
        assertEqual(
            ContentQualityValidator.validate(paragraphs: valid), .valid, "Substantive article must pass validation")

        // 2. Empty paragraphs rejected
        assertEqual(
            ContentQualityValidator.validate(paragraphs: []), .rejected(reason: "No readable paragraphs found"),
            "Empty paragraphs rejected")

        // 3. Too short rejected
        let tooShort = ["This is a tiny snippet."]
        if case .rejected(let reason) = ContentQualityValidator.validate(paragraphs: tooShort) {
            assertTrue(reason.contains("too short"), "Must reject short snippets")
        } else {
            assertTrue(false, "Should reject very short snippets")
        }

        // 4. High boilerplate rejected
        let boilerplate = [
            "The post High Altitude Rescue appeared first on Himalayan News Network.",
            "Photo credit: Associated Press News Wire Archives / John Doe Photographer.",
            "Read full article",
            "A single short paragraph covering the mountain rescue effort in northern Nepal.",
        ]
        if case .rejected(let reason) = ContentQualityValidator.validate(paragraphs: boilerplate) {
            assertTrue(reason.contains("boilerplate"), "Must detect high boilerplate ratio")
        } else {
            assertTrue(false, "Should reject boilerplate heavy text")
        }

        // 5. Repetitive syndicated loop rejected
        let repeated = [
            "The council published a detailed report on local transport improvements and future investment.",
            "The council published a detailed report on local transport improvements and future investment.",
            "The council published a detailed report on local transport improvements and future investment.",
        ]
        if case .rejected(let reason) = ContentQualityValidator.validate(paragraphs: repeated) {
            assertTrue(reason.contains("repetitive"), "Must detect duplicate text loop")
        } else {
            assertTrue(false, "Should reject repetitive syndication loops")
        }
    }

    static func testReaderFurnitureRemoval() async {
        print("  - Testing reader furniture removal (title, stamps, bios, follow prompts, rails, teasers)...")
        let pipeline = ContentExtractionPipeline.shared
        let body = """
            <p>We gave the phone a seven out of ten. But that was not always the score we planned, and it might not be the right score forever. Such are the challenges of reviewing a big new idea about the most popular device.</p>
            <p>On this episode, the hosts debate whether the phone deserved the score it got, and try to work through how this device might change over time. Is the outer screen a feature or a bug for the device as a whole?</p>
            <p>After that, the hosts talk about the huge security flaw that rocked the web this week and what it means for the future of the web, artificial intelligence, and everything else people build online.</p>
            """
        func texts(_ outcome: ExtractionOutcome) -> [String] {
            outcome.document?.blocks.map { "\($0.kind):\($0.text)" } ?? []
        }

        // A publisher lede: the title, a standfirst after it, a time stamp, an author bio, a follow prompt and
        // rails of teaser cards, none with a semantic class name.
        let ledePage = """
            <html><head><title>Phones</title></head><body><article>
            <div class="l1"><div><h1>The phone should have been a tablet</h1><p class="c1">On the podcast: Notes on a phone review, a security scandal, and more.</p></div>
            <div><span class="s1"><time datetime="2026-10-23T17:00:00Z">Oct 23, 2026, 5:00 PM UTC</time></span></div>
            <div><div><span class="c1">is editor-at-large and podcast co-host with over a decade of experience covering consumer tech. Previously, at three other publications.</span></div></div></div>
            <div class="e1">\(body)
            <div class="t1"><span><strong>Follow topics and authors</strong> from this story to see more like this in your personalized homepage feed and to receive email updates.</span><ul><li id="follow-author-x"><span>Dana Pierce</span></li></ul></div>
            </div></article>
            <div class="x1"><h2>Most Popular</h2><ol><li><a href="/a">A dangerous grip on outer space</a></li><li><a href="/b">People are coding their way to better TVs</a></li></ol></div>
            <div class="y1"><h2>Top Stories</h2><div class="z1"><span>Jess Weatherbed 4:52 PM UTC</span><a href="/c">No, the phone is not a small phone and that is fine</a></div><div class="z1"><span>Andrew Webster 12:00 PM UTC</span><a href="/d">A streamer cannot fire its way out of this downward spiral</a></div></div>
            </body></html>
            """
        let lede = pipeline.extractFromHTML(ledePage, baseUrl: "https://news.example/a")
        let ledeKinds = lede.document?.blocks.map(\.kind) ?? []
        assertEqual(
            ledeKinds, [.standfirst, .paragraph, .paragraph, .paragraph],
            "The paragraph after <h1> is the standfirst; stamp, bio, follow prompt and rails are not story text: "
                + "\(texts(lede))")
        assertTrue(
            lede.document?.blocks.first?.text.hasPrefix("On the podcast:") == true,
            "The standfirst keeps the publisher's text")

        // A recommendation section inside the body (Al Jazeera's more-on) and a class-less one both go; a real
        // section heading stays, as does prose that names a former editor.
        let sectioned = """
            <html><body><main><div class="wysiwyg">\(body)
            <section class="more-on"><h2>Recommended Stories</h2><ul><li><a href="/x">Regulator sues network claiming retaliation over coverage</a></li></ul></section>
            <h2>Public, private, or both?</h2>
            <p>Jordan Smith is a former editor of the paper, and said the plan would take a strong partnership with local and state governments before anything could be built on the coast.</p>
            <section><h2>Related Articles</h2><p><a href="/y">Launch site study names three candidates</a></p></section>
            <p>There were 175 orbital launch attempts last year from the two existing ranges, and officials project the country will need far more capacity before the end of the decade.</p>
            <div class="author-mini-bio"><img src="https://news.example/head.jpg" width="200" height="200"><p>Stephen Clark Space Reporter</p></div>
            <p>Stephen Clark is a space reporter at the publication, covering private space companies and the world's space agencies.</p>
            </div></main></body></html>
            """
        let section = pipeline.extractFromHTML(sectioned, baseUrl: "https://news.example/b")
        let sectionTexts = texts(section)
        assertEqual(
            section.document?.blocks.map(\.kind) ?? [],
            [.paragraph, .paragraph, .paragraph, .heading, .paragraph, .paragraph],
            "Navigation headings and bios go, section headings and prose stay: \(sectionTexts)")
        assertTrue(
            sectionTexts.contains { $0.hasPrefix("heading:Public, private") }
                && sectionTexts.contains { $0.contains("former editor") }
                && !sectionTexts.contains {
                    $0.contains("Recommended") || $0.contains("Related") || $0.contains("space reporter at")
                },
            "Only the publisher's own heading and prose remain: \(sectionTexts)")

        // Utility-class hidden duplicates are not shown twice; a feed teaser ending in its own link is incomplete.
        let hiddenDuplicate = pipeline.extractFromHTML(
            "<html><body><article><div class=\"ad-shell hidden\"><p>A sponsored placeholder paragraph the page keeps hidden until an advertising script fills it.</p></div>\(body)</article></body></html>"
        )
        assertEqual(
            hiddenDuplicate.document?.blocks.count, 3,
            "A `hidden` utility class hides its subtree: \(texts(hiddenDuplicate))")
        let responsive = pipeline.extractFromHTML(
            "<html><body><article><div class=\"hidden md:block\">\(body)</div></article></body></html>")
        assertEqual(
            responsive.document?.blocks.count, 3,
            "`hidden md:block` shows on wide windows, so its body stays: \(texts(responsive))")
        // Layout modifiers name what sits beside the story, not the story (PBS, Science News, Variety, IEEE).
        for wrapper in [
            "<section class=\"article-with-sidebar\">", "<div class=\"page__body page__body--with-sidebar\">",
            "<div class=\"non_member_follow\">",
        ] {
            let tag = wrapper.hasPrefix("<section") ? "section" : "div"
            let wrapped = pipeline.extractFromHTML("<html><body><main>\(wrapper)\(body)</\(tag)></main></body></html>")
            assertEqual(wrapped.document?.blocks.count, 3, "\(wrapper) keeps the story: \(texts(wrapped))")
        }
        let teaser = pipeline.extractFromHTML(
            body
                + "<p><a href=\"https://news.example/story/\">Read full article</a></p><p><a href=\"https://news.example/story/#comments\">Comments</a></p>",
            baseUrl: "https://news.example/story/")
        assertEqual(teaser.document?.isComplete, false, "A teaser ending in Read full article is incomplete")
        assertEqual(
            teaser.document?.hasCompleteArticleBody, false, "The reader fetches the page for an incomplete teaser")
        let continued = pipeline.extractFromHTML(
            body + " <a href=\"https://news.example/story/\">Continue reading...</a>",
            baseUrl: "https://news.example/story/")
        assertEqual(continued.document?.isComplete, false, "A Guardian-style Continue reading… link marks a teaser")
        let whole = pipeline.extractFromHTML(body, baseUrl: "https://news.example/story/")
        assertEqual(whole.document?.isComplete, true, "Three full paragraphs without a trailing link are complete")
        // The Verge: three paragraphs over 600 characters that end "… Read the full story at The Verge." (#586). The
        // completeness rule does not override the closing line, and the same body trailing off in an ellipsis is a
        // teaser too; a sentence that merely says "read more" is not.
        let verge = pipeline.extractFromHTML(
            body.replacingOccurrences(
                of: "</p>", with: "… Read the full story at The Verge.</p>", options: .backwards,
                range: body.range(of: "</p>", options: .backwards)),
            baseUrl: "https://www.theverge.com/story/")
        assertEqual(verge.document?.isComplete, false, "A Verge teaser closing with the publisher line is incomplete")
        assertEqual(verge.document?.hasCompleteArticleBody, false, "The reader fetches The Verge page")
        let trailing = pipeline.extractFromHTML(
            body.replacingOccurrences(
                of: "</p>", with: "…</p>", options: .backwards, range: body.range(of: "</p>", options: .backwards)),
            baseUrl: "https://news.example/story/")
        assertEqual(trailing.document?.isComplete, false, "A last paragraph trailing off in an ellipsis is a teaser")
        let mention = pipeline.extractFromHTML(
            body.replacingOccurrences(
                of: "</p>", with: " Those who want detail can read more in the report.</p>", options: .backwards,
                range: body.range(of: "</p>", options: .backwards)),
            baseUrl: "https://news.example/story/")
        assertEqual(mention.document?.isComplete, true, "A sentence that merely says \"read more\" is not a teaser")
        assertTrue(ReaderDocument.closesAsTeaser("Read more on Ars Technica"), "Read more on <publisher>")
        assertTrue(ReaderDocument.closesAsTeaser("Continue reading at Engadget…"), "Continue reading at <publisher>")
        assertFalse(ReaderDocument.closesAsTeaser("The minister said she would read more before deciding."), "Prose")
    }

    static func testExtractionOutcomeDiagnostics() async {
        print("  - Testing ExtractionOutcome Diagnostics & Failure Types...")

        let outcomeSuccess = ExtractionOutcome.success(content: "Article body", imageUrl: "https://example.com/img.jpg")
        assertTrue(outcomeSuccess.isSuccess, "Must identify success")
        assertEqual(outcomeSuccess.content, "Article body", "Content accessible")
        assertEqual(outcomeSuccess.imageUrl, "https://example.com/img.jpg", "Image accessible")
        assertEqual(outcomeSuccess.failureReason, nil, "No failure reason on success")

        let outcomeHTTP = ExtractionOutcome.httpError(status: 403)
        assertTrue(!outcomeHTTP.isSuccess, "Not success")
        assertEqual(outcomeHTTP.failureReason, "HTTP Error 403", "HTTP status failure message")

        let outcomeBlocked = ExtractionOutcome.securityBlocked(reason: "Private IP")
        assertEqual(outcomeBlocked.failureReason, "Security blocked: Private IP", "Security failure message")

        let outcomeNetwork = ExtractionOutcome.networkError(reason: "Connection timeout")
        assertEqual(outcomeNetwork.failureReason, "Connection timeout", "Network failure message")
    }

    static func testCanonicalClassificationDisambiguation() async {
        print("  - Testing Canonical Classification Disambiguation for Overlapping Topics...")
        for headline in [
            "Dubai’s GDP reaches $129bn in H1", "Man who died in aircraft crash named",
            "India trade deal talks continue",
        ] {
            assertFalse(
                ArticleSection.matches(
                    "Tech", title: headline, description: "Officials said the discussions continue.", category: nil),
                "AI must not match inside Dubai, said or aircraft")
            let result = await NaturalLanguageTopicClassifier().classifyTopic(
                title: headline, description: "Officials said the discussions continue.", text: nil, rssCategory: nil)
            assertTrue(result?.category != "Technology", "Whole-word classification rejects incidental AI substrings")
        }
        assertFalse(
            ArticleSection.matches(
                "Tech", title: "Hospital care report", description: "Get our free app", category: "Health"),
            "A recognized category overrides incidental promotional words")
        assertTrue(
            ArticleSection.matches("Tech", title: "AI hardware launches", description: "", category: nil),
            "Standalone AI remains a technology cue")
        assertTrue(
            ArticleSection.matches("Politics", title: "Political row over the budget", description: "", category: nil),
            "Section cues are whole words, so the stem 'politic' had to become 'politics' and 'political'")
        assertTrue(
            ArticleSection.matches("Sports", title: "Sports roundup: weekend results", description: "", category: nil),
            "'sports' is a Sports cue in its own right")

        // Overlap 1: Health + Technology (AI scanner for hospital patients)
        assertEqual(
            NewsCategory.match(from: "medical AI clinical diagnostic scanner"), .health, "Health cue overrides tech")

        // Overlap 2: Science + Technology (NASA satellite mission)
        assertEqual(
            NewsCategory.match(from: "NASA telescope deep space observatory"), .science, "Astronomy cue overrides tech")

        // Overlap 3: Business + Politics (Stock market inflation Wall Street)
        assertEqual(
            NewsCategory.match(from: "Wall Street stock market inflation revenue"), .business,
            "Market cues resolve to business")

        // Overlap 4: Politics + World (Senate Congress election)
        assertEqual(
            NewsCategory.match(from: "Senate Congress election campaign"), .politics,
            "Governance cues resolve to politics")

        // Overlap 5: World diplomacy (International foreign global treaty)
        assertEqual(
            NewsCategory.match(from: "International global foreign diplomat summit"), .world,
            "Diplomacy resolves to world")

        // Misfiles measured on a labelled 200-story library sample (#546, audit of 24 October 2026).
        // No result is World, as every caller reads it (`news_topic`, `ArticleClassifier`).
        func content(_ title: String, _ description: String = "", text: String? = nil) -> String {
            NaturalLanguageTopicClassifier.classifyContent(title: title, description: description, text: text)?
                .category ?? NewsCategory.world.rawValue
        }
        assertEqual(
            content("Drone strike on Abyei market near Sudan-South Sudan border kills 150"), "World",
            "A marketplace is not the stock market")
        assertEqual(content("Half a million Palestinians lose food aid"), "World", "Food aid is not Food")
        assertEqual(content("Toulouse v Troyes Ligue 1 game postponed"), "Sports", "A league name is a Sports cue")
        assertEqual(
            content("Watkins-inspired Al-Hilal end Al-Ittihad's unbeaten run in Saudi Clasico"), "Sports",
            "World loses a tie: a Saudi derby is Sports")
        assertEqual(
            content("Macron takes aim at Trump for using France riots for election gain"), "World",
            "A foreign place in the headline outranks election cues")
        assertEqual(
            content("Trump praises man who punched protester at rally in South Carolina"), "Politics",
            "National politics stays Politics")
        assertEqual(
            content("New White House press secretary says China lacked proper toilets"), "Politics",
            "A domestic cue keeps Politics despite a foreign name")
        assertEqual(content("Kenya confirms four new Ebola cases, bringing total to seven"), "Health", "Ebola")
        assertEqual(
            content("Comcast loses more customers, claims other ISPs' cheap prices are irrational"), "Business",
            "Customers and prices are Business")
        assertEqual(content("Pikmin 4 is $20 off ahead of its Nintendo Switch 2 update"), "Technology", "Games")
        assertEqual(content("Deforestation in Brazil's Amazon falls to all-time low"), "Science", "Environment")
        assertEqual(content("Apple Music has a new logo"), "Technology", "Apple stays a technology cue")
        assertEqual(content("Grandma's apple pie recipe wins the county bake-off"), "Food", "Apple alone is no cue")
        assertEqual(content("Apple's iPhone sales rise"), "Technology", "The possessive names the company")
        // Second pass (#546, 26 October): place and leader names count half, new topic cues; measured on the same
        // sample and on a fresh 200-story draw.
        assertEqual(
            content(
                "Kenya confirms new Ebola cases as Congo outbreak spreads",
                "The first infections passed on inside Kenya, officials in Nairobi and Kampala said."), "Health",
            "A place says where, Ebola says what")
        assertEqual(
            content(
                "Omani label takes its ballerina heels to Paris",
                "The footwear label showed its new collection during Paris Fashion Week."), "Fashion",
            "Paris is where, footwear is what")
        assertEqual(
            content(
                "UN warns El Nino could be strongest on record",
                "The UN's aid chief says the humanitarian system cannot cope alone."), "Science",
            "An international body is an actor, El Nino the topic")
        assertEqual(
            content(
                "Trump's losing battle with green energy",
                "The war and the AI boom strengthen the case for clean power, despite the president's efforts."),
            "Politics", "President is no World cue")
        assertEqual(
            content(
                "Casualties feared as multi-storey building collapses in Nairobi",
                "The building came down in a densely populated business and residential area."), "World",
            "A building collapse is world news, not Business")
        assertEqual(
            content("Fuel dealers urge consumers to avoid panic buying", "Dealers say pricing remains an issue."),
            "Business", "Consumers are a Business cue")
        assertEqual(
            content(
                "Lee Chang Dong ponders the ethics of the camera",
                "His seventh feature film is inspired by true events.",
                text: "The film follows a factory worker; the director shot the feature film in Seoul."),
            "Entertainment", "A feature film outweighs the camera")
        assertEqual(
            content(
                "Australian politician who was hit by car has lost both legs",
                "She is receiving treatment in a Melbourne hospital."), "World",
            "An attack on a foreign politician is World")
        assertEqual(
            content("Canadian diplomats advised to avoid appearing with midterm candidates"), "World",
            "Foreign diplomats outrank a midterm cue")
        assertEqual(
            content("Tangier's timeless trattoria enters a new era", "The reinvention of a much-loved hang-out."),
            "Food", "A trattoria is Food")
        assertEqual(
            content(
                "Review: Crystal Lake drags at first, then hits a vein", "The prequel series is based on Jason's mom.",
                text: "Peacock series Crystal Lake doesn't feel like a Friday the 13th movie at first."),
            "Entertainment", "A prequel series is Entertainment")
        assertEqual(
            content(
                "Why an old role-playing game still has thousands of active players",
                "The single-player RPG is just OK, but players don't mind."), "Technology", "An RPG is a game")
        assertEqual(
            content(
                "Derron prepares to defend her Dubai title", "She faces a field of 20 professional triathletes.",
                text: "Derron won the triathlon in Dubai last year."), "Sports", "Triathlon is Sports")
        assertEqual(
            content(
                "Why is the UK at the forefront of AI-driven job cuts?",
                "AI-linked job losses in the UK run at twice the rate of the US and Germany."), "Technology",
            "AI job cuts in the UK are Technology")
        assertEqual(
            content("DJI's vlogging camera is a good deal at under $400"), "Technology",
            "A camera deal stays Technology")
    }

    @MainActor
    static func testDiagnosticsExport() async throws {
        print("  - Testing the diagnostics export and its redaction (#564)...")
        let now = Date(timeIntervalSince1970: 1_790_000_000)
        let title = "Minister resigns over leaked budget memo"
        let log = [
            DiagnosticsExport.LogLine(
                date: now, category: "Feeds", level: "Error",
                message: "Fetch failed for https://reader:pw@news.example.com/world/2026/leaked-memo?id=7 after 3 tries"
            ),
            DiagnosticsExport.LogLine(
                date: now, category: "Database", level: "Notice",
                message: "Integrity check at /Users/mars/Library/Containers/com.marspater.news/Data/news.sqlite: ok"),
            DiagnosticsExport.LogLine(
                date: now, category: "Feeds", level: "Info", message: "Stored \(title) from feed:https://x.example/a"),
        ]
        let suite = testDefaultsSuite("diagnostics-export")
        defer { removeTestDefaults(suite) }
        let settings = AppSettings(defaults: UserDefaults(suiteName: suite)!)
        let failing = FeedHealth(FeedFetchState(failures: 2), now: now)
        let summary = DiagnosticsExport.summary(
            settings: settings, feedHealth: ["https://feeds.example.org/private/world.xml": failing], schema: 26,
            now: now)
        let files = DiagnosticsExport.files(summary: summary, log: log, titles: [title, "Short"])
        let text = files.values.joined()
        for hidden in ["/world/", "leaked-memo", "id=7", "reader:pw", "/private/world.xml", "/Users/mars", title] {
            assertTrue(!text.contains(hidden), "The export leaves out \(hidden)")
        }
        let tricky = DiagnosticsExport.redact(
            "a https://news.example.com/private'token b https://reader@mail@news.example.com:8443/p c", titles: [])
        assertEqual(tricky, "a news.example.com b news.example.com c", "Quotes and repeated @ never keep URL text")
        let logText = files["log.txt"] ?? ""
        assertTrue(logText.contains("Fetch failed for news.example.com after 3 tries"), "URLs keep their host")
        assertTrue(logText.contains("at ~/Library/Containers/com.marspater.news/Data/news.sqlite"), "Home becomes ~")
        assertTrue(logText.contains("Stored <story> from feed:x.example"), "Story titles are replaced")
        assertTrue(logText.hasPrefix("2026-09-21T14:13:20Z Error Feeds: "), "Lines carry date, level and category")
        let summaryText = files["summary.txt"] ?? ""
        assertTrue(summaryText.contains("Library schema version: 26"), "The summary names the schema version")
        assertTrue(summaryText.contains("Feeds: 2, starred: 0"), "The summary counts subscriptions")
        assertTrue(
            summaryText.contains("feeds.example.org: Not responding (2 failed attempts)"), "Feed health by host")

        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let zip = directory.appendingPathComponent("News Diagnostics.zip")
        try DiagnosticsExport.archive(files, to: zip)
        try DiagnosticsExport.archive(files, to: zip)  // An existing file is replaced.
        assertTrue(try Data(contentsOf: zip).starts(with: [0x50, 0x4B, 0x03, 0x04]), "The export is a zip archive")
        let listing = Process()
        let output = Pipe()
        listing.executableURL = URL(fileURLWithPath: "/usr/bin/unzip")
        listing.arguments = ["-Z1", zip.path]
        listing.standardOutput = output
        try listing.run()
        listing.waitUntilExit()
        let names = String(decoding: output.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
        assertTrue(
            names.contains("News Diagnostics/summary.txt") && names.contains("News Diagnostics/log.txt"),
            "The zip holds the summary and the log: \(names)")

        // This process's own entries are readable from the unified log, as the app's are.
        let marker = "diagnostics-check-\(UUID().uuidString)"
        NewsSignposts.launchLog.notice("\(marker, privacy: .public)")
        // The unified log may store the entry a moment later; poll briefly instead of reading once.
        let deadline = ContinuousClock.now + .seconds(5)
        var found = false
        while !found && ContinuousClock.now < deadline {
            let own = try DiagnosticsExport.currentLaunchLog()
            found = own.contains { $0.message == marker && $0.category == "Launch" }
            if !found { try await Task.sleep(for: .milliseconds(100)) }
        }
        assertTrue(found, "The export reads this launch's log")
    }

    @MainActor
