        ]
        let art3Independent = FeedArticle(
            storedID: "art-rep-3",
            title: "Analysis: Equatorial ice discovery alters future exploration plans",
            link: "https://" + hostC + "/deep-dive-ice",
            guid: "indep-3",
            description: "How the new ice discovery changes exploration logistics.",
